INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C1','kor',4,2,'u5',2,'이 단원에서 배울 두 가지 — 온라인 대화 예절을 지키며 대화하기 · 읽는 이를 생각하며 편지 쓰기 — 둘 다 상대를 살피는 일에서 시작',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C2','kor',4,2,'u5',2,'같은 마음, 다른 방법 — 편지는 천천히 써서 오래 남고 메시지는 떨어져 있어도 빠르게 닿음 — 어느 쪽도 가짜 마음이 아니고 예절이 필요 없는 방법도 아님',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C3','kor',4,2,'u5',2,'마음을 전하는 여러 방법 — 만나서 말하기 · 전화 · 손 편지 · 온라인 대화 · 영상 대화 — 마음속으로만 생각하거나 남에게 대신 말해 달라고만 하는 것은 전하는 일이 아님',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C4','kor',4,2,'u5',2,'더 좋은 방법은 없음 — 방법마다 잘하는 일이 달라서 고를 것은 「어느 것이 더 좋은가」가 아니라 「지금 이 상황에 무엇이 알맞은가」',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C5','kor',4,2,'u5',2,'상황과 방법 잇기 — 상대가 어디에 있는지 · 얼마나 급한지 · 오래 간직할 마음인지를 보고 방법을 고름',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C6','kor',4,2,'u5',2,'가장 먼저 생각할 것 — 방법을 고르기 전에 상대가 지금 어떤 상황인지, 어떤 마음일지를 먼저 살핌 — 가장 빠른 것 · 내가 편한 것 ✗',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C7','kor',4,2,'u5',2,'온라인 대화의 뜻 — 인터넷이나 스마트폰 같은 디지털 기기로 주고받는 대화 — 글로도, 목소리로도, 얼굴을 보면서도 함',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C8','kor',4,2,'u5',2,'온라인 대화의 종류 — 온라인 대화방 · 쪽지와 전자 우편 · 온라인 게시판(댓글) · 영상 통화 · 영상 회의',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C9','kor',4,2,'u5',2,'온라인 대화 가려내기 — 디지털 기기로 상대와 말이 오가면 온라인 대화 — 혼자 공책에 적거나 혼자 자료를 찾아 읽는 일은 아님',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C10','kor',4,2,'u5',2,'온라인 대화의 세 가지 특성 — 디지털 기기가 있어야 시작함 · 떨어진 곳에서도 주고받음 · 대화 상대가 누구인지 알기 어려울 때가 있음',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C11','kor',4,2,'u5',2,'기본 성질이지 규칙이 아님 — 영상 회의는 정해진 같은 시간에 모여야 하고 우리 반 대화방은 누가 말하는지 다 앎 — 어떤 온라인 대화인지에 따라 달라짐',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C12','kor',4,2,'u5',2,'직접 대화와 같은 점 — 화면이 사이에 있을 뿐 사람과 사람이 뜻을 주고받는 일 — 존중과 배려 · 주제에 맞는 말은 똑같이 필요',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C13','kor',4,2,'u5',2,'좋은 점과 조심할 점 — 멀리·늦은 시간에도 전함 · 얼굴 보고 하기 어려운 말도 꺼냄 / 개인 정보가 새어 나감 · 남의 사진이나 글을 함부로 옮기면 피해',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C14','kor',4,2,'u5',2,'온라인 대화를 보는 알맞은 생각 — 조심할 점이 있으니 아예 안 쓰기 ✗ · 편리하니 무엇이든 괜찮다 ✗ — 조심할 점을 알고 예절을 지키며 씀',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C15','kor',4,2,'u5',3,'토의는 교실에서, 화면에서는 준비 — 토의는 여러 사람이 의견을 주고받아야 해서 화면에서는 무엇이 문제인지 · 왜 생기는지 · 어떤 의견이 알맞은지를 준비함',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C16','kor',4,2,'u5',3,'주제와 관련 없는 그림말 되풀이 — 모인 까닭(주제)과 상관없는 말이나 그림말을 되풀이하면 대화는 오가도 정해지는 것이 없음',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C17','kor',4,2,'u5',3,'확인하지 않은 이야기 퍼뜨리기 — 사실인지 확인하지 않은 이야기를 여러 사람이 읽는 곳에 쓰면 그 글에 나온 사람이 크게 다칠 수 있음 — 「아마 맞을걸」도 확인이 아님',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C18','kor',4,2,'u5',3,'문제가 더 잘 생기는 까닭 — 얼굴을 마주 보지 않아 내 말이 어떻게 닿는지 안 보임 · 이름이 드러나지 않을 때가 있어 평소에 안 할 말도 쉽게 함 — 기기가 나쁜 것이 아님',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C19','kor',4,2,'u5',3,'온라인 대화가 더 알맞은 때 — 멀리 이사 간 친구에게 소식 전하기 · 아파서 못 온 날 숙제 묻기 · 쑥스러워 못 하던 말 꺼내기 — 문제 상황을 보았다고 나쁜 것이 되지 않음',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C20','kor',4,2,'u5',3,'온라인 대화 예절 다섯 가지 — 주제와 관련 없는 말·그림말 되풀이 ✗ · 부르기 전에 먼저 묻기 · 올리기 전에 사실 확인 · 보이지 않아도 존중 · 남의 사진·영상은 허락 없이 ✗',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C21','kor',4,2,'u5',3,'사진·영상은 허락을 받고 — 남의 사진이나 영상을 올리기 전에 찍힌 사람에게 먼저 물어봄 — 재미있어할 것 같아도 마찬가지',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C22','kor',4,2,'u5',3,'대화방에 부를 때는 먼저 묻기 — 상대가 그 대화방에 들어올지 먼저 물어보고 부름 — 묻지 않고 자꾸 초대하지 않음',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C23','kor',4,2,'u5',3,'뜻을 알기 어려운 말 — 줄인 말·그림말을 상대가 모르면 대화에서 밀려남 — 쓰던 말을 그대로 쓰지 않고 알아들을 수 있는 말로',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C24','kor',4,2,'u5',3,'토의할 때 지킬 것 — 말차례를 지킴 · 다른 사람의 의견을 존중하며 들음 · 주제와 관련 있는 이야기 — 토의는 이기는 일이 아니라 함께 정하는 일',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C25','kor',4,2,'u5',3,'의견이 알맞은지 따지는 기준 — 실제로 할 수 있는 의견인가 · 좋은 점이 불편한 점보다 큰가 — 「좋은 말 같으니까」나 지킬 수 없는 극단(아무 말도 안 하기·아예 안 쓰기) ✗',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C26','kor',4,2,'u5',5,'온라인 대화가 편리한 때 — 멀리 떨어져 만나기 어려울 때 · 사진이나 자료를 주고받을 때 · 서로 시간이 맞지 않을 때 · 여러 사람에게 한꺼번에 알릴 때',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C27','kor',4,2,'u5',5,'직접 만나는 편이 나은 때 — 다투어 마음이 상한 짝에게 사과하기처럼 표정과 목소리가 함께 가야 하는 일 — 온라인이 언제나 더 편하지는 않음',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C28','kor',4,2,'u5',5,'온라인 대화 계획 네 칸 — 대화 상대(누구와) · 온라인으로 하는 까닭(왜) · 대화 방식(대화방·쪽지·전자 우편·영상 통화) · 대화 주제(무엇을)',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C29','kor',4,2,'u5',5,'온라인에서도 높임 표현 — 같은 내용도 누구에게 하느냐에 따라 말이 달라짐 — 웃어른께는 화면에서도 높임 표현(「~해 주시겠어요?」·「뵐 수 있을까요?」)',ARRAY['[4국04-04](차시 머리 표기 — 높임 표현)']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C30','kor',4,2,'u5',5,'모르는 사람이 말을 걸 때 — 이름·사는 곳·학교·사진을 알려 주지 않음 · 만나자고 해도 따르지 않음 · 어른께 바로 알림 — 예절이 아니라 나를 지키는 일',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C31','kor',4,2,'u5',5,'대화하는 동안 지킬 것 — 정한 주제에 맞는 말 · 상대의 말에 답하기 · 먼저 나갈 때 양해 구하기 · 뜻을 모를 말은 풀어서 쓰기',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C32','kor',4,2,'u5',5,'상대가 못 알아들었을 때 — 못 알아들은 것은 상대 잘못이 아님 — 뜻이 통하도록 풀어서 다시 말함(똑같이 다시 보내기 · 「그것도 모르냐」 ✗)',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C33','kor',4,2,'u5',5,'점검표의 쓸모 — 「예 / 아니요」 표는 잘한 것처럼 보이려고 채우는 표가 아니라 「아니요」 줄을 찾아 그 줄로 돌아가 고치려고 채우는 표 — 점수가 없음',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C34','kor',4,2,'u5',5,'다짐은 하나를 지키기 — 오늘 배운 것 가운데 한 가지만 골라 이번 주에 꼭 지킬 일로 — 많이 정하기보다 하나를 지키는 것이 나음',ARRAY['온라인 대화 예절(성취기준 번호 확인 필요)']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C35','kor',4,2,'u5',7,'편지는 아주 오래된 방법 — 종이가 생기기 훨씬 전부터 흙판·나무판·가죽에 글을 적어 보냄 — 기기가 없던 때에도 마음은 오갔음',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C36','kor',4,2,'u5',7,'편지로 전하면 좋은 점 — 시간이 들어 정성이 담김 · 천천히 정리하고 고쳐 쓸 수 있음 · 글로 남아 오래 간직 · 쑥스러운 말도 씀 — 언제나 빠르다·언제나 더 좋다 ✗',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C37','kor',4,2,'u5',7,'유담이 편지의 내용 — 여름 방학에 큰이모께서 밤하늘의 별자리 이름을 짚어 주신 일에 대한 고마운 마음 — 무엇이 고마웠는지까지 밝힘',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C38','kor',4,2,'u5',7,'편지의 짜임 일곱 — 받는 사람 · 첫인사 · 전하고 싶은 말 · 끝인사 · 쓴 날짜 · 쓴 사람 · 추신',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C39','kor',4,2,'u5',7,'추신은 보탤 말이 있을 때만 — 다 쓴 뒤에 보탤 말이 생겼을 때만 「추신」으로 덧붙임 — 꼭 써야 하는 칸이 아님',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C40','kor',4,2,'u5',7,'읽는 이에 맞춘 높임 표현 — 웃어른께는 부르는 말(「~께」) · 문장 끝(「~습니다」) · 이름 뒤(「올림·드림」) 세 곳 모두 높임 / 친구에게는 「~에게 · 씀」',ARRAY['[4국04-04](차시 머리 표기 — 높임 표현)']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C41','kor',4,2,'u5',7,'높임은 상대에 맞추는 것 — 높임은 마음의 크기가 아니라 상대에 맞추는 것 — 친구에게 높임말을 쓰지 않는다고 마음이 작은 것이 아님',ARRAY['[4국04-04](차시 머리 표기 — 높임 표현)']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C42','kor',4,2,'u5',7,'모자란 편지의 빈 곳 — 웃어른께 높임을 맞추지 않음 · 무엇이 고마웠는지 알 수 없음 · 첫인사·끝인사·쓴 날짜가 없음 — 길이나 글씨가 흠의 중심이 아님',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C43','kor',4,2,'u5',7,'「읽는 이를 생각한다」의 뜻 — 전하려는 마음은 그대로 두고 읽는 이의 상황을 살펴 표현을 고름 — 좋아할 말만 골라 쓰기 ✗ · 떠오르는 대로 쓰기 ✗',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C44','kor',4,2,'u5',9,'편지 쓰기 전 계획 넷 — 마음을 전할 사람 · 있었던 일 · 전하고 싶은 마음 · 마음을 나타내는 표현',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C45','kor',4,2,'u5',9,'편지로 전하기 좋은 일 — 그 사람과 나 사이에 마음이 오간 일(대신 해 준 일 · 이사 가는 이웃 · 동생이 처음 해낸 일) — 급식 반찬 · 날씨 바람은 편지 글감이 되기 어려움',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C46','kor',4,2,'u5',9,'마음의 다섯 갈래 — 감사(도움 받음) · 사과(내가 잘못) · 축하(좋은 일) · 위로(힘든 일을 겪는 중) · 응원(무언가를 앞둠)',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C47','kor',4,2,'u5',9,'처음 · 가운데 · 끝 — 처음 — 부르는 말·안부·날씨 / 가운데 — 쓴 까닭·있었던 일·그때의 마음·헤아리는 말 / 끝 — 바라는 점·끝인사·쓴 날짜·쓴 사람',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C48','kor',4,2,'u5',9,'구체적으로 ≠ 길게 — 무슨 일이 있었는지 읽는 사람이 알 수 있게 쓰는 것 — 더 긴 문장이나 「아주아주·정말정말」 되풀이가 구체적인 것이 아님',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C49','kor',4,2,'u5',9,'솔직함과 배려 — 내 마음을 솔직하게 쓰되 상대의 지금 처지를 살핌(다친 친구에게 신나게 뛰어논 이야기 ✗) — 둘 중 하나를 고르는 것이 아님',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C50','kor',4,2,'u5',9,'다 쓰고 소리 내어 읽기 — 다 쓴 편지를 소리 내어 천천히 읽으면 쓸 때 안 보이던 곳이 보임 — 점검표는 고쳐 쓸 곳을 찾으려고 채움(점수 없음)',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C51','kor',4,2,'u5',9,'편지봉투 쓰는 법 — 보내는 사람은 왼쪽 위 · 받는 사람은 오른쪽 아래 · 우편 번호 다섯 자리 · 웃어른이면 「귀하·님께」, 친구면 「에게·앞」',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C52','kor',4,2,'u5',9,'편지는 닿아야 편지 — 다 쓴 편지는 직접 건네거나 우체통에 넣거나 학급에서 모아 함께 나눔 — 써 두기만 하면 마음이 전해지지 않음',ARRAY['읽는 이를 생각하며 마음을 전하는 글 쓰기(성취기준 번호 확인 필요)']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C53','kor',4,2,'u5',11,'실천 활동 셋 — 온라인 대화 예절 알리기(표어) · 비밀 친구에게 편지 쓰기 · 매체 견주기 놀이 — 만드는 일은 교실에서, 화면에서는 가려낼 기준을 정함',ARRAY['배운 내용 실천하기(성취기준 번호 확인 필요)']::text[],53) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C54','kor',4,2,'u5',11,'표어다운 것 — 짧은 한 줄 · 한 가지만 · 읽으면 바로 알 수 있는 말 · 무엇을 하자는 것인지가 들어 있음 — 설명처럼 길게 · 「아예 하지 말자」 ✗',ARRAY['배운 내용 실천하기(성취기준 번호 확인 필요)']::text[],54) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C55','kor',4,2,'u5',11,'알리는 방법 정하기 — 언제 · 어디서 · 누구에게 · 어떻게 — 온 학교에 오래 알리려면 여러 사람이 여러 날 볼 수 있는 곳(알림판)',ARRAY['배운 내용 실천하기(성취기준 번호 확인 필요)']::text[],55) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C56','kor',4,2,'u5',11,'비밀 친구 편지 — 이름을 밝히지 않고 정한 기간 동안 씀 · 둘만 겪은 특별한 일은 내가 누구인지 드러나니 쓰지 않고 친구의 좋은 점을 칭찬 · 「○○에게 … 씀」',ARRAY['배운 내용 실천하기(성취기준 번호 확인 필요)']::text[],56) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C57','kor',4,2,'u5',11,'매체마다 잘하는 일 — 매체 견주기 놀이는 이기고 지는 놀이가 아님 — 온라인 대화방은 더 빠르고 편지는 더 오래 남는 것처럼 잘하는 일이 다름',ARRAY['배운 내용 실천하기(성취기준 번호 확인 필요)']::text[],57) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C58','kor',4,2,'u5',11,'겹받침 ㄺ의 소리 — 보통 [ㄱ]만 소리 남(읽다[익따] · 굵다[국따] · 늙다[늑따]) — 뒤에 ㄱ이 오면 [ㄹ](읽고[일꼬] · 굵게[굴께] · 늙고[늘꼬])',ARRAY['[4국04-05](차시 머리 표기) · 겹받침 ㄺ·ㄼ 발음(번호 확인 필요)']::text[],58) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C59','kor',4,2,'u5',11,'겹받침 ㄼ의 소리 — 보통 [ㄹ]로 소리 남(넓다[널따] · 짧다[짤따] · 여덟[여덜]) — 다만 밟-은 [밥-](밟고[밥꼬])',ARRAY['[4국04-05](차시 머리 표기) · 겹받침 ㄺ·ㄼ 발음(번호 확인 필요)']::text[],59) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u5-C60','kor',4,2,'u5',11,'온라인에서 다시 쓰면 좋은 말 — 뜻을 알기 어렵게 줄인 말 · 주제와 관련 없는 그림말만 보내기 · 사정을 말하지 않고 툭 던지는 말 — 상대가 알아듣고 서운하지 않게 다시 씀',ARRAY['[4국04-05](차시 머리 표기) · 겹받침 ㄺ·ㄼ 발음(번호 확인 필요)']::text[],60) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X01','kor',4,'u5',ARRAY['K4-2-u5-C1']::text[],'이 단원에서 배울 내용을 「온라인 대화를 안 하는 법」이나 「편지는 옛날 것」처럼 엉뚱하게 여긴다','상대를 살피는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X02','kor',4,'u5',ARRAY['K4-2-u5-C2']::text[],'전하는 방법에 따라 마음이 진짜이거나 가짜라고 여긴다(편지는 진짜, 메시지는 가짜)','같은 마음, 다른 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X03','kor',4,'u5',ARRAY['K4-2-u5-C2','K4-2-u5-C12']::text[],'온라인 대화나 메시지에서는 예절을 지키지 않아도 된다고 여긴다','화면 너머에도 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X04','kor',4,'u5',ARRAY['K4-2-u5-C3']::text[],'마음속으로만 생각하거나 남에게 대신 말해 달라고만 해도 마음이 전해진다고 여긴다','건네야 전해져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X05','kor',4,'u5',ARRAY['K4-2-u5-C4','K4-2-u5-C57']::text[],'어느 한 방법이 언제나 더 좋다고 방법에 등수를 매긴다','상황에 알맞은 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X06','kor',4,'u5',ARRAY['K4-2-u5-C5']::text[],'상대가 있는 곳·급한 정도·간직할 마음을 보지 않고 상황과 방법을 엇갈리게 잇는다','어디에 · 얼마나 급한지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X07','kor',4,'u5',ARRAY['K4-2-u5-C6']::text[],'마음을 전할 때 가장 먼저 생각할 것을 「가장 빠른 방법」으로 여긴다','상대의 상황 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X08','kor',4,'u5',ARRAY['K4-2-u5-C6']::text[],'마음을 전할 때 가장 먼저 생각할 것을 「내가 가장 편한 방법」으로 여긴다','상대의 마음 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X09','kor',4,'u5',ARRAY['K4-2-u5-C7','K4-2-u5-C9']::text[],'혼자 공책에 적거나 혼자 자료를 읽는 일처럼 상대와 말이 오가지 않는 일도 온라인 대화라고 여긴다','말이 오가나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X10','kor',4,'u5',ARRAY['K4-2-u5-C8','K4-2-u5-C10']::text[],'온라인 대화의 종류나 세 가지 특성(기기·시간과 장소·대화 상대)을 엇갈리게 잇는다','무엇 · 어디 · 누구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X11','kor',4,'u5',ARRAY['K4-2-u5-C11']::text[],'온라인 대화의 특성을 언제나 그런 규칙으로 여긴다(언제나 상대를 모름 · 언제 들어가도 상관없음)','대체로 그래요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X12','kor',4,'u5',ARRAY['K4-2-u5-C12']::text[],'온라인 대화는 직접 대화와 전혀 다른 일이라 존중이나 주제에 맞는 말이 필요 없다고 여긴다','똑같은 것도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X13','kor',4,'u5',ARRAY['K4-2-u5-C13','K4-2-u5-C14','K4-2-u5-C19']::text[],'조심할 점이 있으니 온라인 대화는 아예 안 쓰는 것이 가장 좋다고 여긴다','잘 쓰는 법을 배워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X14','kor',4,'u5',ARRAY['K4-2-u5-C13','K4-2-u5-C14','K4-2-u5-C27']::text[],'편리하니까 온라인에서는 무엇을 해도 괜찮고 만나서 하는 대화는 필요 없다고 여긴다','편리함과 예절은 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X15','kor',4,'u5',ARRAY['K4-2-u5-C15','K4-2-u5-C24']::text[],'토의를 화면에서 혼자 끝낼 수 있다고 여기거나 토의를 이기고 지는 일로 여긴다','함께 정하는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X16','kor',4,'u5',ARRAY['K4-2-u5-C16']::text[],'대화방 문제의 까닭을 사람 수나 대화한 시각처럼 엉뚱한 데서 찾는다','모인 까닭은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X17','kor',4,'u5',ARRAY['K4-2-u5-C17']::text[],'「아마 맞을 것」이면 확인하지 않은 이야기도 올려도 되거나, 그 글의 문제를 길이에서 찾는다','올리기 전에 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X18','kor',4,'u5',ARRAY['K4-2-u5-C18']::text[],'온라인 대화에서 문제가 생기는 까닭을 디지털 기기 자체가 나쁜 탓으로 여긴다','얼굴 · 이름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X19','kor',4,'u5',ARRAY['K4-2-u5-C18']::text[],'문제가 생기는 까닭을 「글자 쓰기가 말보다 느려서」처럼 상관없는 데서 찾는다','보이지 않는 얼굴') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X20','kor',4,'u5',ARRAY['K4-2-u5-C20','K4-2-u5-C21']::text[],'남의 사진이나 영상은 다들 재미있어하면 허락 없이 올려도 된다고 여긴다','찍힌 사람에게 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X21','kor',4,'u5',ARRAY['K4-2-u5-C20','K4-2-u5-C22']::text[],'상대에게 묻지 않고 대화방에 불러도 되고 자꾸 초대해도 된다고 여긴다','들어올지 먼저 물어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X22','kor',4,'u5',ARRAY['K4-2-u5-C23','K4-2-u5-C32']::text[],'상대가 뜻을 몰라도 내가 쓰던 말을 그대로 쓰거나, 못 알아들은 것을 상대 잘못으로 여긴다','알아듣게 풀어서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X23','kor',4,'u5',ARRAY['K4-2-u5-C20','K4-2-u5-C31']::text[],'답이 늦으면 답할 때까지 계속 말을 걸어 재촉해도 된다고 여긴다','상대의 사정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X24','kor',4,'u5',ARRAY['K4-2-u5-C25']::text[],'의견을 「좋은 말 같으니까」로 고르거나 지킬 수 없는 극단(아무 말도 안 하기 · 아예 안 쓰기)을 예절로 고른다','지킬 수 있는가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X25','kor',4,'u5',ARRAY['K4-2-u5-C24']::text[],'토의에서 말차례를 무시하거나 주제와 상관없는 이야기를 해도 된다고 여긴다','말차례 · 존중 · 주제') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X26','kor',4,'u5',ARRAY['K4-2-u5-C26','K4-2-u5-C27']::text[],'온라인 대화가 언제나 더 편하다고 여겨 마음 상한 일의 사과도 온라인이 낫다고 고른다','표정과 목소리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X27','kor',4,'u5',ARRAY['K4-2-u5-C28','K4-2-u5-C44']::text[],'계획의 칸(누구·왜·어떻게·무엇)과 정한 내용을 엇갈리게 잇는다','누구 · 왜 · 무엇') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X28','kor',4,'u5',ARRAY['K4-2-u5-C29']::text[],'화면에서는 웃어른께도 반말을 쓰거나 재촉하고 낱말만 툭 보내도 된다고 여긴다','화면이라도 높임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X29','kor',4,'u5',ARRAY['K4-2-u5-C30']::text[],'모르는 사람이 물으면 예의를 지켜 이름·학교·사진을 알려 주어야 한다고 여긴다','나를 지키는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X30','kor',4,'u5',ARRAY['K4-2-u5-C30']::text[],'모르는 사람이 말을 걸어오면 어른께 알리지 않고 혼자 넘기거나 혼자 판단한다','어른께 바로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X31','kor',4,'u5',ARRAY['K4-2-u5-C33','K4-2-u5-C50']::text[],'점검하다가 「아니요」가 나오면 「예」가 되도록 표시를 고쳐 둔다','고칠 곳 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X32','kor',4,'u5',ARRAY['K4-2-u5-C33','K4-2-u5-C50']::text[],'점검하다가 「아니요」가 나온 줄은 넘기고 다음 줄만 본다','그 줄로 돌아가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X33','kor',4,'u5',ARRAY['K4-2-u5-C34']::text[],'다짐은 많이 정할수록 좋다고 여긴다','하나를 지키기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X34','kor',4,'u5',ARRAY['K4-2-u5-C31','K4-2-u5-C60']::text[],'대화방에서 먼저 나갈 때 아무 말 없이 나가거나 까닭 없이 툭 끊어도 된다고 여긴다','양해를 구해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X35','kor',4,'u5',ARRAY['K4-2-u5-C35','K4-2-u5-C57']::text[],'편지는 옛날 것이라 이제는 쓸 수 없다거나, 기기가 생긴 뒤에 생긴 방법이라고 여긴다','아주 오래된 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X36','kor',4,'u5',ARRAY['K4-2-u5-C36']::text[],'편지는 언제나 빠르게 닿는다거나 다른 방법보다 언제나 더 좋다고 여긴다','천천히 · 오래') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X37','kor',4,'u5',ARRAY['K4-2-u5-C37']::text[],'편지가 전하는 마음을 있었던 일과 다르게 짚는다','무슨 일이 있었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X38','kor',4,'u5',ARRAY['K4-2-u5-C38','K4-2-u5-C47']::text[],'편지의 줄과 짜임(첫인사·전하고 싶은 말·끝인사·쓴 사람)을 엇갈리게 잇는다','짜임 일곱') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X39','kor',4,'u5',ARRAY['K4-2-u5-C39']::text[],'추신은 모든 편지에 꼭 써야 하는 칸이라고 여긴다','보탤 말이 있을 때만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X40','kor',4,'u5',ARRAY['K4-2-u5-C40']::text[],'웃어른께 쓰면서 부르는 말·문장 끝·이름 뒤 가운데 일부만 높임으로 맞춘다','세 곳 모두') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X41','kor',4,'u5',ARRAY['K4-2-u5-C41']::text[],'높임말을 쓰지 않으면 마음이 작은 것이라 여겨 친구에게도 「~께 … 올림」을 써야 한다고 여긴다','상대에 맞춰요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X42','kor',4,'u5',ARRAY['K4-2-u5-C42']::text[],'모자란 편지의 흠을 길이나 글씨에서 찾고 높임·있었던 일·짜임은 살피지 않는다','무엇이 빠졌나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X43','kor',4,'u5',ARRAY['K4-2-u5-C43','K4-2-u5-C49']::text[],'「읽는 이를 생각한다」를 「읽는 이가 좋아할 말만 골라 쓴다」로 여긴다','마음은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X44','kor',4,'u5',ARRAY['K4-2-u5-C43','K4-2-u5-C49']::text[],'읽는 이의 처지는 생각하지 않고 떠오르는 대로 쓰거나, 아예 아무 말도 안 쓰는 것을 배려로 여긴다','처지를 살펴요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X45','kor',4,'u5',ARRAY['K4-2-u5-C45']::text[],'급식 반찬이나 날씨 바람처럼 그 사람과 마음이 오가지 않은 일을 편지 글감으로 고른다','마음이 오간 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X46','kor',4,'u5',ARRAY['K4-2-u5-C46']::text[],'상황에 알맞은 마음의 갈래(감사·사과·축하·위로·응원)를 엇갈리게 고른다','상대의 처지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X47','kor',4,'u5',ARRAY['K4-2-u5-C47']::text[],'있었던 일과 그때의 마음을 처음이나 끝에 들어갈 내용으로 여긴다','쓴 까닭은 가운데') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X48','kor',4,'u5',ARRAY['K4-2-u5-C48']::text[],'구체적으로 쓰라는 말을 길게 쓰거나 「아주아주·정말정말」을 되풀이하라는 말로 여긴다','무슨 일인지 알 수 있게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X49','kor',4,'u5',ARRAY['K4-2-u5-C48']::text[],'「좋았어·고마워」 한마디처럼 짧고 막연한 말이 마음을 더 잘 전한다고 여긴다','읽는 사람이 떠올리게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X50','kor',4,'u5',ARRAY['K4-2-u5-C51']::text[],'편지봉투에서 받는 사람을 왼쪽 위에, 보내는 사람을 오른쪽 아래에 쓴다','받는 사람은 오른쪽 아래') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X51','kor',4,'u5',ARRAY['K4-2-u5-C51']::text[],'웃어른께 보내는 봉투에 「앞·에게」를 쓰거나, 우편 번호를 아무렇게나 쓴다','귀하 · 님께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X52','kor',4,'u5',ARRAY['K4-2-u5-C52']::text[],'편지는 써 두기만 하면 전하지 않아도 마음이 전해진다고 여긴다','닿아야 편지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X53','kor',4,'u5',ARRAY['K4-2-u5-C53','K4-2-u5-C54']::text[],'표어를 설명처럼 길게 쓰거나 여러 가지를 한꺼번에 담고, 화면에서 표어를 다 지을 수 있다고 여긴다','한 줄 · 한 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X54','kor',4,'u5',ARRAY['K4-2-u5-C54']::text[],'「온라인 대화를 아예 하지 말자」처럼 한쪽으로 치우친 말을 표어로 고른다','무엇을 하자?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X55','kor',4,'u5',ARRAY['K4-2-u5-C55']::text[],'알릴 범위와 기간을 생각하지 않고 공책에 적기나 모둠끼리 말하기를 온 학교 알림으로 고른다','몇 사람이 · 며칠 동안') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X56','kor',4,'u5',ARRAY['K4-2-u5-C56']::text[],'비밀 친구 편지에 둘만 겪은 특별한 일을 써서 내가 누구인지 드러나게 한다','좋은 점 칭찬') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X57','kor',4,'u5',ARRAY['K4-2-u5-C57','K4-2-u5-C5']::text[],'매체 견주기를 「어느 매체가 모든 면에서 이기나」로 여긴다','잘하는 일이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X58','kor',4,'u5',ARRAY['K4-2-u5-C58']::text[],'ㄺ 뒤에 ㄱ이 와도 [ㄱ]으로 읽거나, ㄺ을 언제나 [ㄹ]로 읽는다','뒤 글자의 첫소리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X59','kor',4,'u5',ARRAY['K4-2-u5-C58','K4-2-u5-C59']::text[],'겹받침 두 글자를 모두 소리 내어 읽는다([읽꼬] · [넓따])','하나만 소리 나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X60','kor',4,'u5',ARRAY['K4-2-u5-C59']::text[],'ㄼ을 언제나 [ㄹ]로 읽어 밟-도 [발-]로 읽거나, 거꾸로 ㄼ을 언제나 [ㅂ]으로 읽는다','밟-만 [밥-]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u5-X61','kor',4,'u5',ARRAY['K4-2-u5-C60','K4-2-u5-C23']::text[],'다시 쓸 때 더 짧게 줄이거나 그림말만 보내는 것을 알아듣기 쉬운 말로 여긴다','알아듣고 서운하지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_basic#1','kor',4,2,'u5','L02','g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C2',1,'mc','auto','도경이가 고마운 마음을 전한 ㉮와 ㉯가 다른 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X02','K4-2-u5-X03']::text[],false,'{"seq":1,"concept":"K4-2-u5-C2","difficulty":1,"kind":"mc","stem":"도경이가 고마운 마음을 전한 ㉮와 ㉯가 다른 점으로 알맞은 것은 무엇인가요?","options":[{"t":"㉮는 천천히 써서 오래 남고, ㉯는 떨어져 있어도 빠르게 닿는다","correct":true},{"t":"㉮는 진짜 마음이고 ㉯는 가짜 마음이다","mis":"K4-2-u5-X02"},{"t":"㉯는 예절을 지키지 않아도 되는 방법이다","mis":"K4-2-u5-X03"},{"t":"㉮와 ㉯는 전하려는 마음이 서로 다르다","mis":"K4-2-u5-X02"}],"explanation":["둘 다 같은 고마운 마음이에요.","빠르기와 남는 시간이 달라요.","㉮는 오래, ㉯는 빠르게예요."],"asset":{"type":"passage","lines":["비 오는 날, 나윤이는 우산이 없는 도경이에게 우산을 씌워 주었다.","다음 날 도경이는 고마운 마음을 전하기로 했다.","㉮ 종이에 편지를 써서 나윤이의 책상에 놓아 두었다.","㉯ 집에 와서 메시지를 보내 그날 밤에 바로 전했다."],"title":"빌려준 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_basic#2','kor',4,2,'u5','L02','g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C7',1,'mc','auto','온라인 대화의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X09','K4-2-u5-X10','K4-2-u5-X04']::text[],false,'{"seq":2,"concept":"K4-2-u5-C7","difficulty":1,"kind":"mc","stem":"온라인 대화의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"인터넷이나 스마트폰 같은 디지털 기기로 주고받는 대화","correct":true},{"t":"혼자 공책에 쓰는 오늘의 일기","mis":"K4-2-u5-X09"},{"t":"같은 교실에서 마주 보고 나누는 이야기","mis":"K4-2-u5-X10"},{"t":"마음속으로만 하는 혼잣말","mis":"K4-2-u5-X04"}],"explanation":["「온라인」을 떠올려요.","디지털 기기로 해요.","상대와 주고받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_basic#3','kor',4,2,'u5','L02','g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C4',1,'ox','auto','편지가 온라인 대화보다 언제나 더 좋은 방법이에요.',ARRAY['K4-2-u5-X05']::text[],false,'{"seq":3,"concept":"K4-2-u5-C4","difficulty":1,"kind":"ox","stem":"편지가 온라인 대화보다 언제나 더 좋은 방법이에요.","answer":"X","reason_options":[{"t":"방법마다 잘하는 일이 달라 상황에 알맞은 것을 고르기 때문에","correct":true},{"t":"편지는 정성이 담겨 어느 때나 가장 좋은 방법이기 때문에","mis":"K4-2-u5-X05"}],"mis":"K4-2-u5-X05","explanation":["더 좋은 방법은 없어요.","잘하는 일이 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_basic#4','kor',4,2,'u5','L02','g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C9',1,'mc','auto','다음 가운데 온라인 대화인 것은 무엇인가요?',ARRAY['K4-2-u5-X09','K4-2-u5-X04']::text[],false,'{"seq":4,"concept":"K4-2-u5-C9","difficulty":1,"kind":"mc","stem":"다음 가운데 온라인 대화인 것은 무엇인가요?","options":[{"t":"영상 통화로 멀리 사는 사촌과 이야기한다","correct":true},{"t":"공책에 오늘 있었던 일을 적어 둔다","mis":"K4-2-u5-X09"},{"t":"혼자 누리집에서 자료를 찾아 읽는다","mis":"K4-2-u5-X09"},{"t":"마음속으로만 사촌을 떠올린다","mis":"K4-2-u5-X04"}],"explanation":["상대와 말이 오가나요?","혼자 하는 일은 아니에요.","영상 통화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_basic#5','kor',4,2,'u5','L02','g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C10',2,'match','auto','온라인 대화를 직접 대화와 견주었을 때의 특성을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u5-C10","difficulty":2,"kind":"match","stem":"온라인 대화를 직접 대화와 견주었을 때의 특성을 알맞게 이으세요.","pairs":[{"l":"디지털 기기","r":"기기가 있어야 대화를 시작할 수 있다"},{"l":"시간과 장소","r":"떨어진 곳에서도 주고받을 수 있다"},{"l":"대화 상대","r":"누구인지 알기 어려울 때가 있다"}],"mis":"K4-2-u5-X10","explanation":["무엇이 있어야 하나요?","어디에 있어야 하나요?","누구인지 아나요?"],"asset":{"type":"speech","turns":[{"who":"유담","text":"모둠 발표 자료, 어떤 걸로 할지 정하자."},{"who":"소윤","text":"나는 지금 집인데, 대화방에서 정하면 안 될까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_basic#6','kor',4,2,'u5','L02','g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C5',2,'mc','auto','바다 건너에 사는 친척에게 안부를 묻고 싶을 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u5-X06','K4-2-u5-X04','K4-2-u5-X05']::text[],false,'{"seq":6,"concept":"K4-2-u5-C5","difficulty":2,"kind":"mc","stem":"바다 건너에 사는 친척에게 안부를 묻고 싶을 때 알맞은 방법은 무엇인가요?","options":[{"t":"영상 대화나 온라인 대화로 전하기","correct":true},{"t":"찾아가서 얼굴을 보며 말하기","mis":"K4-2-u5-X06"},{"t":"마음속으로 안부를 빌기","mis":"K4-2-u5-X04"},{"t":"가장 좋은 방법인 손 편지만 쓰기","mis":"K4-2-u5-X05"}],"explanation":["상대가 어디에 있나요?","멀리 있어요.","떨어져서도 닿는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_basic#7','kor',4,2,'u5','L02','g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C11',2,'mc','auto','㉮와 ㉯를 보고 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u5-X11','K4-2-u5-X12']::text[],false,'{"seq":7,"concept":"K4-2-u5-C11","difficulty":2,"kind":"mc","stem":"㉮와 ㉯를 보고 알맞게 말한 것은 무엇인가요?","options":[{"t":"어떤 온라인 대화인지에 따라 시간과 상대가 달라질 수 있다","correct":true},{"t":"온라인 대화는 언제나 상대가 누구인지 알 수 없다","mis":"K4-2-u5-X11"},{"t":"온라인 대화는 언제 들어가도 상관이 없다","mis":"K4-2-u5-X11"},{"t":"온라인 대화는 직접 대화와 같은 점이 하나도 없다","mis":"K4-2-u5-X12"}],"explanation":["영상 회의는 같은 시간이에요.","반 대화방은 상대를 알아요.","규칙이 아니라 성질이에요."],"asset":{"type":"passage","lines":["㉮ 영상 회의는 정해진 같은 시간에 모두 들어와야 해요.","㉯ 우리 반 대화방은 누가 말하는지 모두 알고 있어요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_basic#8','kor',4,2,'u5','L02','g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C12',2,'mc','auto','온라인 대화와 직접 대화의 같은 점은 무엇인가요?',ARRAY['K4-2-u5-X10','K4-2-u5-X12']::text[],false,'{"seq":8,"concept":"K4-2-u5-C12","difficulty":2,"kind":"mc","stem":"온라인 대화와 직접 대화의 같은 점은 무엇인가요?","options":[{"t":"둘 다 상대를 존중하며 뜻을 주고받는 일이다","correct":true},{"t":"둘 다 디지털 기기가 있어야 할 수 있다","mis":"K4-2-u5-X10"},{"t":"둘 다 같은 시간에 같은 곳에 있어야 한다","mis":"K4-2-u5-X10"},{"t":"온라인 대화에서는 주제에 맞는 말을 하지 않아도 된다","mis":"K4-2-u5-X12"}],"explanation":["다른 점이 아니라 같은 점이에요.","화면 너머에도 사람이 있어요.","존중하며 주고받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_basic#9','kor',4,2,'u5','L02','g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C6',2,'mc','auto','마음을 전할 때 가장 먼저 생각할 것은 무엇인가요?',ARRAY['K4-2-u5-X07','K4-2-u5-X08','K4-2-u5-X05']::text[],false,'{"seq":9,"concept":"K4-2-u5-C6","difficulty":2,"kind":"mc","stem":"마음을 전할 때 가장 먼저 생각할 것은 무엇인가요?","options":[{"t":"상대가 지금 어떤 상황인지, 어떤 마음일지","correct":true},{"t":"가장 빠르게 전할 수 있는 방법","mis":"K4-2-u5-X07"},{"t":"내가 가장 하기 편한 방법","mis":"K4-2-u5-X08"},{"t":"가장 오래 남는 방법","mis":"K4-2-u5-X05"}],"explanation":["방법보다 먼저예요.","상대를 살펴요.","상황과 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_basic#10','kor',4,2,'u5','L02','g4_2_kor_u5_L02_basic','lesson_basic','K4-2-u5-C14',3,'error','auto','온라인 대화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u5-X13','K4-2-u5-X14']::text[],false,'{"seq":10,"concept":"K4-2-u5-C14","difficulty":3,"kind":"error","stem":"온라인 대화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「개인 정보가 새어 나갈 수 있으니 온라인 대화는 아예 안 하는 게 가장 좋아.」","correct":true,"mis_target":"K4-2-u5-X13"},{"t":"친구 가 — 「멀리 있어도, 늦은 시간에도 마음을 전할 수 있어.」","mis":"K4-2-u5-X14"},{"t":"친구 나 — 「조심할 점을 알고 예절을 지키며 쓰면 돼.」","mis":"K4-2-u5-X13"}],"explanation":["좋은 점도 조심할 점도 있어요.","안 쓰자는 것이 아니에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_challenge#1','kor',4,2,'u5','L02','g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C7',2,'sa','auto','인터넷이나 스마트폰으로 주고받는 대화를 「(  ) 대화」라고 해요. 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u5-C7","difficulty":2,"kind":"sa","stem":"인터넷이나 스마트폰으로 주고받는 대화를 「(  ) 대화」라고 해요. 빈칸에 알맞은 말을 쓰세요.","answer":["온라인"],"explanation":["디지털 기기로 해요.","화면으로 나누는 대화예요.","‘온라인’이에요."],"mis":"K4-2-u5-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_challenge#2','kor',4,2,'u5','L02','g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C8',2,'mc','auto','여러 사람이 한 화면에 모여 얼굴을 보며 이야기하는 온라인 대화는 무엇인가요?',ARRAY['K4-2-u5-X10']::text[],false,'{"seq":2,"concept":"K4-2-u5-C8","difficulty":2,"kind":"mc","stem":"여러 사람이 한 화면에 모여 얼굴을 보며 이야기하는 온라인 대화는 무엇인가요?","options":[{"t":"영상 회의","correct":true},{"t":"전자 우편","mis":"K4-2-u5-X10"},{"t":"온라인 게시판","mis":"K4-2-u5-X10"},{"t":"쪽지","mis":"K4-2-u5-X10"}],"explanation":["여러 사람이 모여요.","얼굴을 보며 말해요.","영상 회의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_challenge#3','kor',4,2,'u5','L02','g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C1',3,'mc','auto','이 단원에서 배울 두 가지(온라인 대화 예절 · 편지 쓰기)가 함께 시작하는 곳은 어디인가요?',ARRAY['K4-2-u5-X01','K4-2-u5-X13']::text[],false,'{"seq":3,"concept":"K4-2-u5-C1","difficulty":3,"kind":"mc","stem":"이 단원에서 배울 두 가지(온라인 대화 예절 · 편지 쓰기)가 함께 시작하는 곳은 어디인가요?","options":[{"t":"상대를 살피는 일","correct":true},{"t":"기기를 빨리 다루는 일","mis":"K4-2-u5-X01"},{"t":"온라인 대화를 줄이는 일","mis":"K4-2-u5-X13"},{"t":"글씨를 예쁘게 쓰는 일","mis":"K4-2-u5-X01"}],"explanation":["대화도 편지도 상대가 있어요.","상대를 먼저 봐요.","상대를 살피는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_challenge#4','kor',4,2,'u5','L02','g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C3',3,'mc','auto','고마운 마음이 있지만 말하기가 쑥스러운 지우가 한 일 가운데 마음이 전해지는 것은 무엇인가요?',ARRAY['K4-2-u5-X04']::text[],false,'{"seq":4,"concept":"K4-2-u5-C3","difficulty":3,"kind":"mc","stem":"고마운 마음이 있지만 말하기가 쑥스러운 지우가 한 일 가운데 마음이 전해지는 것은 무엇인가요?","options":[{"t":"고마웠던 일을 적은 쪽지를 친구에게 건넸다","correct":true},{"t":"고마운 마음을 마음속으로만 오래 생각했다","mis":"K4-2-u5-X04"},{"t":"다른 친구에게 대신 말해 달라고만 부탁했다","mis":"K4-2-u5-X04"},{"t":"말하지 않아도 친구가 저절로 알 거라고 여겼다","mis":"K4-2-u5-X04"}],"explanation":["마음은 저절로 안 가요.","내가 건네야 해요.","쪽지를 건넸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_challenge#5','kor',4,2,'u5','L02','g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C13',3,'mc','auto','온라인 대화의 좋은 점과 조심할 점을 둘 다 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u5-X14','K4-2-u5-X13']::text[],false,'{"seq":5,"concept":"K4-2-u5-C13","difficulty":3,"kind":"mc","stem":"온라인 대화의 좋은 점과 조심할 점을 둘 다 알맞게 말한 것은 무엇인가요?","options":[{"t":"「멀리 있는 친구와도 이야기할 수 있지만, 사는 곳이 새어 나가지 않게 조심해야 해.」","correct":true},{"t":"「편리하니까 아무 사진이나 올려도 돼.」","mis":"K4-2-u5-X14"},{"t":"「조심할 점이 있으니 쓰지 않는 게 낫지.」","mis":"K4-2-u5-X13"},{"t":"「좋은 점만 있으니 조심할 것은 없어.」","mis":"K4-2-u5-X14"}],"explanation":["좋은 점이 있어요.","조심할 점도 있어요.","둘 다 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_challenge#6','kor',4,2,'u5','L02','g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C11',3,'ox','auto','우리 반 대화방도 누가 말하는지 알 수 없으니 아무렇게나 말해도 돼요.',ARRAY['K4-2-u5-X11']::text[],false,'{"seq":6,"concept":"K4-2-u5-C11","difficulty":3,"kind":"ox","stem":"우리 반 대화방도 누가 말하는지 알 수 없으니 아무렇게나 말해도 돼요.","answer":"X","reason_options":[{"t":"우리 반 대화방은 누가 말하는지 다 알고, 상대가 누구든 존중해야 하기 때문에","correct":true},{"t":"온라인 대화는 언제나 상대가 누구인지 알 수 없기 때문에","mis":"K4-2-u5-X11"}],"mis":"K4-2-u5-X11","explanation":["반 대화방은 상대를 알아요.","상대를 몰라도 존중해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_challenge#7','kor',4,2,'u5','L02','g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C5',3,'match','auto','상황에 알맞은 방법을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K4-2-u5-C5","difficulty":3,"kind":"match","stem":"상황에 알맞은 방법을 이으세요.","pairs":[{"l":"바로 옆자리 친구에게 지금 미안하다고 하고 싶다","r":"찾아가서 얼굴을 보며 말하기"},{"l":"오래 간직할 고마운 마음을 전하고 싶다","r":"손 편지를 써서 건네기"},{"l":"먼 나라에 사는 친척에게 안부를 묻고 싶다","r":"영상 대화나 온라인 대화로 전하기"}],"mis":"K4-2-u5-X06","explanation":["상대가 어디에 있나요?","얼마나 오래 남길 마음인가요?","상황이 방법을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_challenge#8','kor',4,2,'u5','L02','g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C4',4,'essay','teacher','「편지가 온라인 대화보다 무조건 낫다」는 친구에게 해 줄 말을 쓰고, 그렇게 생각한 까닭을 예를 들어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u5-C4","difficulty":4,"kind":"essay","stem":"「편지가 온라인 대화보다 무조건 낫다」는 친구에게 해 줄 말을 쓰고, 그렇게 생각한 까닭을 예를 들어 쓰세요.","answer_guide":{"answer":"예: 「무조건 나은 방법은 없어. 상황에 알맞은 방법이 있을 뿐이야.」라고 말해 준다. 편지는 오래 간직할 마음을 담기에 좋지만, 먼 나라에 사는 친척에게 오늘 바로 안부를 묻고 싶을 때는 영상 대화가 더 알맞기 때문이다.","scoring_points":["「무조건 낫다」에 동의하지 않았는가","방법마다 잘하는 일이 다르다는 까닭을 썼는가","상황에 따라 다른 방법이 알맞은 예를 들었는가"]},"explanation":["등수가 없어요.","잘하는 일이 달라요.","예를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_challenge#9','kor',4,2,'u5','L02','g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C6',4,'essay','teacher','도경이가 나윤이에게 고마운 마음을 전하려고 해요. 방법을 고르기 전에 먼저 살필 것을 쓰고, 그것에 맞게 방법을 하나 골라 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u5-C6","difficulty":4,"kind":"essay","stem":"도경이가 나윤이에게 고마운 마음을 전하려고 해요. 방법을 고르기 전에 먼저 살필 것을 쓰고, 그것에 맞게 방법을 하나 골라 까닭을 쓰세요.","answer_guide":{"answer":"예: 먼저 나윤이가 지금 어떤 상황인지, 어떤 마음일지를 살핀다. 나윤이는 같은 반이라 날마다 만나고, 도경이는 고마운 마음을 오래 남기고 싶으니 편지를 써서 건넨다. 오래 간직할 수 있기 때문이다.","scoring_points":["방법보다 상대의 상황과 마음을 먼저 살핀다고 썼는가","방법을 하나 골랐는가","살핀 상황과 이어지는 까닭을 썼는가"]},"explanation":["상대를 먼저 봐요.","상황에 맞춰 골라요.","까닭을 이어요."],"asset":{"type":"passage","lines":["비 오는 날, 나윤이는 우산이 없는 도경이에게 우산을 씌워 주었다.","다음 날 도경이는 고마운 마음을 전하기로 했다.","㉮ 종이에 편지를 써서 나윤이의 책상에 놓아 두었다.","㉯ 집에 와서 메시지를 보내 그날 밤에 바로 전했다."],"title":"빌려준 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L02_challenge#10','kor',4,2,'u5','L02','g4_2_kor_u5_L02_challenge','lesson_challenge','K4-2-u5-C14',4,'mc','auto','소윤이가 「온라인 대화는 좋은 점도 조심할 점도 있대.」라고 말했어요. 이 말에 가장 알맞게 이어지는 생각은 무엇인가요?',ARRAY['K4-2-u5-X13','K4-2-u5-X14']::text[],false,'{"seq":10,"concept":"K4-2-u5-C14","difficulty":4,"kind":"mc","stem":"소윤이가 「온라인 대화는 좋은 점도 조심할 점도 있대.」라고 말했어요. 이 말에 가장 알맞게 이어지는 생각은 무엇인가요?","options":[{"t":"그러니 조심할 점을 알고 예절을 지키며 쓰면 된다","correct":true},{"t":"그러니 조심할 점이 없어질 때까지 쓰지 않는다","mis":"K4-2-u5-X13"},{"t":"그러니 좋은 점이 더 많으면 예절은 몰라도 된다","mis":"K4-2-u5-X14"},{"t":"그러니 만나서 하는 대화는 이제 필요 없다","mis":"K4-2-u5-X14"}],"explanation":["양쪽이 함께 있어요.","한쪽으로 치우치지 않아요.","알고, 지키며 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_basic#1','kor',4,2,'u5','L03','g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C16',1,'mc','auto','승연이네 모둠 대화방에서 찾을 수 있는 문제점은 무엇인가요?',ARRAY['K4-2-u5-X16','K4-2-u5-X25']::text[],false,'{"seq":1,"concept":"K4-2-u5-C16","difficulty":1,"kind":"mc","stem":"승연이네 모둠 대화방에서 찾을 수 있는 문제점은 무엇인가요?","options":[{"t":"주제와 관련 없는 그림말을 되풀이해 보냈다","correct":true},{"t":"대화방에 사람이 너무 적었다","mis":"K4-2-u5-X16"},{"t":"대화를 나눈 시간이 너무 이른 아침이었다","mis":"K4-2-u5-X16"},{"t":"승연이가 주제를 먼저 물어보았다","mis":"K4-2-u5-X25"}],"explanation":["모인 까닭은 주제 정하기였어요.","그림말만 오갔어요.","정해진 것이 없어요."],"asset":{"type":"speech","turns":[{"who":"승연","text":"우리 모둠 발표 주제 뭘로 할까?"},{"who":"친구 1","text":"(주제와 상관없는 그림말을 여러 번 보냄)"},{"who":"승연","text":"…… 주제 정해야 하는데."},{"who":"친구 1","text":"(또 같은 그림말을 보냄)"},{"who":"채율","text":"무슨 말인지 모르겠어. 뭘 하자는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_basic#2','kor',4,2,'u5','L03','g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C17',1,'mc','auto','학년 게시판의 글에서 찾을 수 있는 문제점은 무엇인가요?',ARRAY['K4-2-u5-X17','K4-2-u5-X13']::text[],false,'{"seq":2,"concept":"K4-2-u5-C17","difficulty":1,"kind":"mc","stem":"학년 게시판의 글에서 찾을 수 있는 문제점은 무엇인가요?","options":[{"t":"확인하지 않은 이야기를 여러 사람이 읽는 곳에 썼다","correct":true},{"t":"글이 너무 짧아서 내용을 알기 어려웠다","mis":"K4-2-u5-X17"},{"t":"게시판에는 원래 글을 쓰면 안 된다","mis":"K4-2-u5-X13"},{"t":"「아마 맞을걸」이라고 했으니 확인한 것이다","mis":"K4-2-u5-X17"}],"explanation":["아무도 확인하지 않았어요.","여러 사람이 읽어요.","한 사람이 다칠 수 있어요."],"asset":{"type":"speech","turns":[{"who":"글쓴이 알 수 없음","text":"4반 어떤 애가 그랬다던데, 들었어?"},{"who":"글쓴이 알 수 없음","text":"나도 들었음. 확실한 건 아닌데 아마 맞을걸."},{"who":"글쓴이 알 수 없음","text":"그럼 진짜인가 보네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_basic#3','kor',4,2,'u5','L03','g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C21',1,'ox','auto','친구들이 재미있어할 것 같으면 친구 사진을 허락 없이 대화방에 올려도 돼요.',ARRAY['K4-2-u5-X20']::text[],false,'{"seq":3,"concept":"K4-2-u5-C21","difficulty":1,"kind":"ox","stem":"친구들이 재미있어할 것 같으면 친구 사진을 허락 없이 대화방에 올려도 돼요.","answer":"X","reason_options":[{"t":"사진을 올리기 전에 찍힌 사람에게 먼저 물어야 하기 때문에","correct":true},{"t":"다 같이 웃으면 찍힌 사람도 좋아하기 때문에","mis":"K4-2-u5-X20"}],"mis":"K4-2-u5-X20","explanation":["사진 속 사람이 있어요.","먼저 물어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_basic#4','kor',4,2,'u5','L03','g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C18',1,'mc','auto','온라인 대화에서 문제가 더 잘 생기는 까닭은 무엇인가요?',ARRAY['K4-2-u5-X19','K4-2-u5-X18','K4-2-u5-X16']::text[],false,'{"seq":4,"concept":"K4-2-u5-C18","difficulty":1,"kind":"mc","stem":"온라인 대화에서 문제가 더 잘 생기는 까닭은 무엇인가요?","options":[{"t":"얼굴을 마주 보지 않고 이름이 드러나지 않을 때가 있기 때문에","correct":true},{"t":"글자를 쓰는 일이 말하는 것보다 느리기 때문에","mis":"K4-2-u5-X19"},{"t":"디지털 기기를 쓰는 일 자체가 나쁜 일이기 때문에","mis":"K4-2-u5-X18"},{"t":"대화방에는 늘 사람이 너무 많기 때문에","mis":"K4-2-u5-X16"}],"explanation":["기기가 나쁜 것이 아니에요.","얼굴이 안 보여요.","이름도 안 보일 때가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_basic#5','kor',4,2,'u5','L03','g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C19',2,'mc','auto','온라인 대화가 특히 알맞은 상황은 무엇인가요?',ARRAY['K4-2-u5-X26','K4-2-u5-X17','K4-2-u5-X13']::text[],false,'{"seq":5,"concept":"K4-2-u5-C19","difficulty":2,"kind":"mc","stem":"온라인 대화가 특히 알맞은 상황은 무엇인가요?","options":[{"t":"멀리 이사 간 친구에게 오늘 있었던 일을 전하고 싶을 때","correct":true},{"t":"옆자리 친구에게 바로 사과하고 싶을 때","mis":"K4-2-u5-X26"},{"t":"확인하지 않은 소문을 여럿에게 빠르게 퍼뜨리고 싶을 때","mis":"K4-2-u5-X17"},{"t":"문제 상황을 보았으니 알맞은 때는 하나도 없다","mis":"K4-2-u5-X13"}],"explanation":["지금 만날 수 있나요?","떨어져 있어요.","그때 큰 힘이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_basic#6','kor',4,2,'u5','L03','g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C22',2,'mc','auto','모둠 대화방을 새로 만들 때 알맞게 한 것은 무엇인가요?',ARRAY['K4-2-u5-X21','K4-2-u5-X23']::text[],false,'{"seq":6,"concept":"K4-2-u5-C22","difficulty":2,"kind":"mc","stem":"모둠 대화방을 새로 만들 때 알맞게 한 것은 무엇인가요?","options":[{"t":"들어올지 친구에게 먼저 물어본 뒤 불렀다","correct":true},{"t":"묻지 않고 반 친구 모두를 불렀다","mis":"K4-2-u5-X21"},{"t":"나가 버린 친구를 계속 다시 불렀다","mis":"K4-2-u5-X21"},{"t":"대답이 없는 친구에게 답할 때까지 말을 걸었다","mis":"K4-2-u5-X23"}],"explanation":["상대의 뜻을 먼저 물어요.","억지로 부르지 않아요.","먼저 물어보고 불러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_basic#7','kor',4,2,'u5','L03','g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C24',2,'mc','auto','모둠에서 온라인 대화 예절을 토의할 때 지킬 것은 무엇인가요?',ARRAY['K4-2-u5-X15','K4-2-u5-X25']::text[],false,'{"seq":7,"concept":"K4-2-u5-C24","difficulty":2,"kind":"mc","stem":"모둠에서 온라인 대화 예절을 토의할 때 지킬 것은 무엇인가요?","options":[{"t":"말차례를 지키며 다른 사람의 의견을 존중하며 듣는다","correct":true},{"t":"내 의견이 이길 때까지 크게 말한다","mis":"K4-2-u5-X15"},{"t":"주제와 상관없는 재미있는 이야기를 먼저 한다","mis":"K4-2-u5-X25"},{"t":"다른 사람이 말할 때 끼어들어 내 말을 한다","mis":"K4-2-u5-X25"}],"explanation":["토의는 이기는 일이 아니에요.","함께 정해요.","말차례와 존중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_basic#8','kor',4,2,'u5','L03','g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C25',2,'mc','auto','우리 반 온라인 대화 예절로 정하기에 더 알맞은 의견은 무엇인가요?',ARRAY['K4-2-u5-X24']::text[],false,'{"seq":8,"concept":"K4-2-u5-C25","difficulty":2,"kind":"mc","stem":"우리 반 온라인 대화 예절로 정하기에 더 알맞은 의견은 무엇인가요?","options":[{"t":"사진을 올리기 전에 찍힌 사람에게 먼저 물어본다","correct":true},{"t":"대화방에서는 아무 말도 하지 않는다","mis":"K4-2-u5-X24"},{"t":"우리 반은 온라인 대화를 아예 쓰지 않는다","mis":"K4-2-u5-X24"},{"t":"좋은 말 같으니 「언제나 웃자」로 정한다","mis":"K4-2-u5-X24"}],"explanation":["지킬 수 있나요?","좋은 점이 더 큰가요?","사진은 먼저 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_basic#9','kor',4,2,'u5','L03','g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C23',2,'mc','auto','친구가 대화방에서 줄인 말을 썼는데 채율이는 알아듣지 못했어요. 채율이에게 생긴 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X22','K4-2-u5-X15']::text[],false,'{"seq":9,"concept":"K4-2-u5-C23","difficulty":2,"kind":"mc","stem":"친구가 대화방에서 줄인 말을 썼는데 채율이는 알아듣지 못했어요. 채율이에게 생긴 일로 알맞은 것은 무엇인가요?","options":[{"t":"무슨 이야기가 오가는지 몰라 대화에서 밀려났다","correct":true},{"t":"줄인 말 덕분에 대화를 더 빨리 따라갔다","mis":"K4-2-u5-X22"},{"t":"줄인 말을 모르는 채율이가 잘못한 것이다","mis":"K4-2-u5-X22"},{"t":"그 말을 쓴 친구가 대화에서 이긴 것이다","mis":"K4-2-u5-X15"}],"explanation":["못 알아들은 사람이 있어요.","그 사람은 밀려나요.","알아듣게 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_basic#10','kor',4,2,'u5','L03','g4_2_kor_u5_L03_basic','lesson_basic','K4-2-u5-C20',3,'error','auto','온라인 대화 예절을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u5-X23','K4-2-u5-X17','K4-2-u5-X03']::text[],false,'{"seq":10,"concept":"K4-2-u5-C20","difficulty":3,"kind":"error","stem":"온라인 대화 예절을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「답이 늦으면 답할 때까지 계속 말을 걸어야 해.」","correct":true,"mis_target":"K4-2-u5-X23"},{"t":"친구 가 — 「올리기 전에 사실인지 먼저 확인해야 해.」","mis":"K4-2-u5-X17"},{"t":"친구 나 — 「상대가 보이지 않아도 존중하며 말해야 해.」","mis":"K4-2-u5-X03"}],"explanation":["상대에게도 사정이 있어요.","재촉하지 않아요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_challenge#1','kor',4,2,'u5','L03','g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C15',2,'sa','auto','토의는 여러 사람이 의견을 주고받아야 해요. 이 화면에서는 토의를 준비하고, 실제 토의는 어디에서 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u5-C15","difficulty":2,"kind":"sa","stem":"토의는 여러 사람이 의견을 주고받아야 해요. 이 화면에서는 토의를 준비하고, 실제 토의는 어디에서 하나요? 두 글자로 쓰세요.","answer":["교실"],"explanation":["화면에는 의견을 낼 사람이 없어요.","함께 모이는 곳이에요.","‘교실’이에요."],"mis":"K4-2-u5-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_challenge#2','kor',4,2,'u5','L03','g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C20',2,'blank','auto','온라인 대화 예절: 글을 올리기 전에 (  )인지 먼저 확인해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u5-X17','K4-2-u5-X20']::text[],false,'{"seq":2,"concept":"K4-2-u5-C20","difficulty":2,"kind":"blank","stem":"온라인 대화 예절: 글을 올리기 전에 (  )인지 먼저 확인해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"사실","correct":true},{"t":"재미","mis":"K4-2-u5-X17"},{"t":"유행","mis":"K4-2-u5-X17"},{"t":"인기","mis":"K4-2-u5-X20"}],"explanation":["아마 맞을 것은 아니에요.","확인해요.","‘사실’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_challenge#3','kor',4,2,'u5','L03','g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C17',3,'mc','auto','학년 게시판에 「○○이가 창문을 깼대. 아마 맞을걸.」이라는 글이 올라왔어요. 내가 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X17']::text[],false,'{"seq":3,"concept":"K4-2-u5-C17","difficulty":3,"kind":"mc","stem":"학년 게시판에 「○○이가 창문을 깼대. 아마 맞을걸.」이라는 글이 올라왔어요. 내가 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"확인되지 않은 이야기이니 퍼뜨리지 않고 덧붙이지도 않는다","correct":true},{"t":"「나도 들었어」라고 댓글을 달아 힘을 보탠다","mis":"K4-2-u5-X17"},{"t":"다른 반 대화방에도 옮겨 알린다","mis":"K4-2-u5-X17"},{"t":"「아마」라고 썼으니 사실로 믿는다","mis":"K4-2-u5-X17"}],"explanation":["아무도 확인하지 않았어요.","여러 사람이 읽어요.","퍼뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_challenge#4','kor',4,2,'u5','L03','g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C16',3,'mc','auto','하준이네 대화방에서 당번 순서가 잘 정해지지 않은 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X16','K4-2-u5-X25']::text[],false,'{"seq":4,"concept":"K4-2-u5-C16","difficulty":3,"kind":"mc","stem":"하준이네 대화방에서 당번 순서가 잘 정해지지 않은 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"민재가 주제와 상관없는 그림말을 보내고 뜻을 알기 어려운 말로 대답했기 때문에","correct":true},{"t":"하준이가 먼저 순서를 정하자고 했기 때문에","mis":"K4-2-u5-X16"},{"t":"대화방에 세 사람밖에 없었기 때문에","mis":"K4-2-u5-X16"},{"t":"서아가 주제로 돌아가자고 했기 때문에","mis":"K4-2-u5-X25"}],"explanation":["모인 까닭은 당번 정하기예요.","누가 주제에서 벗어났나요?","민재의 말이에요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"이번 주 텃밭 물 당번 순서 정하자."},{"who":"민재","text":"(주제와 상관없는 그림말만 계속 보냄)"},{"who":"서아","text":"민재야, 당번 순서 먼저 정하고 이야기하자."},{"who":"민재","text":"(뜻을 알기 어렵게 줄인 말로 대답함)"},{"who":"하준","text":"그럼 월요일은 내가 할게. 화요일은 누가 할래?"},{"who":"서아","text":"나는 수요일이 좋아. 민재는?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_challenge#5','kor',4,2,'u5','L03','g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C18',3,'mc','auto','얼굴을 보면 하지 않을 말을 온라인에서는 쉽게 하게 되는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X19','K4-2-u5-X18','K4-2-u5-X17']::text[],false,'{"seq":5,"concept":"K4-2-u5-C18","difficulty":3,"kind":"mc","stem":"얼굴을 보면 하지 않을 말을 온라인에서는 쉽게 하게 되는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"상대의 표정이 보이지 않고 내 이름이 드러나지 않을 때가 있어서","correct":true},{"t":"온라인에서는 말을 빨리 써야 해서","mis":"K4-2-u5-X19"},{"t":"기기가 사람을 나쁘게 만들어서","mis":"K4-2-u5-X18"},{"t":"온라인에서 한 말은 금방 사라져서","mis":"K4-2-u5-X17"}],"explanation":["내 말이 어떻게 닿는지 안 보여요.","이름도 숨을 수 있어요.","그래서 더 조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_challenge#6','kor',4,2,'u5','L03','g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C19',3,'ox','auto','온라인 대화에서 문제 상황을 여러 번 보았으니 온라인 대화는 나쁜 것이에요.',ARRAY['K4-2-u5-X13']::text[],false,'{"seq":6,"concept":"K4-2-u5-C19","difficulty":3,"kind":"ox","stem":"온라인 대화에서 문제 상황을 여러 번 보았으니 온라인 대화는 나쁜 것이에요.","answer":"X","reason_options":[{"t":"떨어져 있거나 바로 만나기 어려울 때 큰 힘이 되기도 해서 잘 쓰는 법을 배우는 것이기 때문에","correct":true},{"t":"문제가 생길 수 있는 것은 모두 쓰지 않아야 하기 때문에","mis":"K4-2-u5-X13"}],"mis":"K4-2-u5-X13","explanation":["알맞은 때도 있어요.","잘 쓰는 법을 배워요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_challenge#7','kor',4,2,'u5','L03','g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C25',3,'mc','auto','「친구 사진은 올리기 전에 꼭 묻자」와 「대화방에서는 서로 말을 하지 말자」 가운데 예절로 정하기에 알맞은 것과 그 까닭은 무엇인가요?',ARRAY['K4-2-u5-X24']::text[],false,'{"seq":7,"concept":"K4-2-u5-C25","difficulty":3,"kind":"mc","stem":"「친구 사진은 올리기 전에 꼭 묻자」와 「대화방에서는 서로 말을 하지 말자」 가운데 예절로 정하기에 알맞은 것과 그 까닭은 무엇인가요?","options":[{"t":"앞의 것 — 모두 지킬 수 있고 좋은 점이 불편한 점보다 크기 때문에","correct":true},{"t":"뒤의 것 — 말을 안 하면 다툼이 아예 없어지기 때문에","mis":"K4-2-u5-X24"},{"t":"뒤의 것 — 더 엄격해서 좋은 말 같기 때문에","mis":"K4-2-u5-X24"},{"t":"둘 다 — 좋은 말이면 모두 예절이 되기 때문에","mis":"K4-2-u5-X24"}],"explanation":["지킬 수 있나요?","좋은 점이 더 큰가요?","앞의 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_challenge#8','kor',4,2,'u5','L03','g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C16',4,'essay','teacher','승연이네 대화방에서 친구 1이 그림말 대신 할 말을 한 문장으로 쓰고, 그렇게 말하면 좋은 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u5-C16","difficulty":4,"kind":"essay","stem":"승연이네 대화방에서 친구 1이 그림말 대신 할 말을 한 문장으로 쓰고, 그렇게 말하면 좋은 까닭을 쓰세요.","answer_guide":{"answer":"예: 「나는 우리 동네 공원을 발표 주제로 하면 좋겠어.」라고 말한다. 모인 까닭인 주제에 맞는 말을 하면 모두 알아들을 수 있고 대화가 앞으로 나아가기 때문이다.","scoring_points":["그림말 대신 주제에 맞는 말을 썼는가","모두 알아들을 수 있는 말로 썼는가","대화가 나아간다는 까닭을 썼는가"]},"explanation":["모인 까닭을 떠올려요.","주제에 맞게 말해요.","대화가 나아가요."],"asset":{"type":"speech","turns":[{"who":"승연","text":"우리 모둠 발표 주제 뭘로 할까?"},{"who":"친구 1","text":"(주제와 상관없는 그림말을 여러 번 보냄)"},{"who":"승연","text":"…… 주제 정해야 하는데."},{"who":"친구 1","text":"(또 같은 그림말을 보냄)"},{"who":"채율","text":"무슨 말인지 모르겠어. 뭘 하자는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_challenge#9','kor',4,2,'u5','L03','g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C25',4,'essay','teacher','우리 반 온라인 대화 예절을 하나 정한다면 무엇으로 할지 쓰고, 「실제로 할 수 있는가」와 「좋은 점이 불편한 점보다 큰가」로 따져 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u5-C25","difficulty":4,"kind":"essay","stem":"우리 반 온라인 대화 예절을 하나 정한다면 무엇으로 할지 쓰고, 「실제로 할 수 있는가」와 「좋은 점이 불편한 점보다 큰가」로 따져 쓰세요.","answer_guide":{"answer":"예: 「대화방에 부를 때는 먼저 물어보자.」로 정한다. 부르기 전에 한 줄만 물으면 되니 모두 실제로 할 수 있다. 조금 번거롭지만 원하지 않는 친구가 억지로 들어오는 일이 없어지니 좋은 점이 더 크다.","scoring_points":["예절을 하나 정했는가","실제로 할 수 있는지 따졌는가","좋은 점과 불편한 점을 견주었는가"]},"explanation":["하나를 정해요.","지킬 수 있나요?","좋은 점이 더 큰가요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L03_challenge#10','kor',4,2,'u5','L03','g4_2_kor_u5_L03_challenge','lesson_challenge','K4-2-u5-C20',4,'mc','auto','온라인 대화 예절 다섯 가지를 모두 묶는 한 가지 물음으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X08','K4-2-u5-X20','K4-2-u5-X13']::text[],false,'{"seq":10,"concept":"K4-2-u5-C20","difficulty":4,"kind":"mc","stem":"온라인 대화 예절 다섯 가지를 모두 묶는 한 가지 물음으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「이렇게 하면 상대에게 무슨 일이 생길까?」","correct":true},{"t":"「이렇게 하면 내가 더 빨리 끝낼 수 있을까?」","mis":"K4-2-u5-X08"},{"t":"「이렇게 하면 대화방이 더 재미있어질까?」","mis":"K4-2-u5-X20"},{"t":"「이렇게 하면 온라인 대화를 덜 쓰게 될까?」","mis":"K4-2-u5-X13"}],"explanation":["예절은 상대를 위한 것이에요.","상대에게 생길 일을 봐요.","그 물음이 다섯 가지를 묶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_basic#1','kor',4,2,'u5','L05','g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C27',1,'mc','auto','다음 가운데 직접 만나서 말하는 편이 나은 것은 무엇인가요?',ARRAY['K4-2-u5-X26']::text[],false,'{"seq":1,"concept":"K4-2-u5-C27","difficulty":1,"kind":"mc","stem":"다음 가운데 직접 만나서 말하는 편이 나은 것은 무엇인가요?","options":[{"t":"다투어서 마음이 상한 짝에게 사과할 때","correct":true},{"t":"모둠 발표에 쓸 자료를 서로 나눠 줄 때","mis":"K4-2-u5-X26"},{"t":"내일 준비물을 반 전체에 알릴 때","mis":"K4-2-u5-X26"},{"t":"멀리 사는 사촌에게 안부를 물을 때","mis":"K4-2-u5-X26"}],"explanation":["표정과 목소리가 필요한 일이에요.","마음 상한 일을 풀어요.","사과는 얼굴을 보고요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_basic#2','kor',4,2,'u5','L05','g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C30',1,'mc','auto','온라인에서 모르는 사람이 사진과 학교를 물어볼 때 할 일은 무엇인가요?',ARRAY['K4-2-u5-X29','K4-2-u5-X30']::text[],false,'{"seq":2,"concept":"K4-2-u5-C30","difficulty":1,"kind":"mc","stem":"온라인에서 모르는 사람이 사진과 학교를 물어볼 때 할 일은 무엇인가요?","options":[{"t":"알려 주지 않고 어른께 바로 알린다","correct":true},{"t":"예의를 지켜야 하니 물어본 것은 알려 준다","mis":"K4-2-u5-X29"},{"t":"혼자 아무 말 없이 넘어간다","mis":"K4-2-u5-X30"},{"t":"학교 이름만 알려 준다","mis":"K4-2-u5-X29"}],"explanation":["예절이 아니라 나를 지키는 일이에요.","알려 주지 않아요.","어른께 바로 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_basic#3','kor',4,2,'u5','L05','g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C32',1,'mc','auto','대화 상대가 내 말을 못 알아들었을 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X22','K4-2-u5-X34']::text[],false,'{"seq":3,"concept":"K4-2-u5-C32","difficulty":1,"kind":"mc","stem":"대화 상대가 내 말을 못 알아들었을 때 알맞은 것은 무엇인가요?","options":[{"t":"뜻이 잘 통하도록 풀어서 다시 말한다","correct":true},{"t":"똑같은 말을 한 번 더 보낸다","mis":"K4-2-u5-X22"},{"t":"「그것도 모르냐」고 말한다","mis":"K4-2-u5-X22"},{"t":"대화방을 말없이 나간다","mis":"K4-2-u5-X34"}],"explanation":["상대 잘못이 아니에요.","알아듣게 해요.","풀어서 다시 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_basic#4','kor',4,2,'u5','L05','g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C33',1,'ox','auto','점검표에서 「아니요」가 나오면 「예」로 고쳐 두면 돼요.',ARRAY['K4-2-u5-X31']::text[],false,'{"seq":4,"concept":"K4-2-u5-C33","difficulty":1,"kind":"ox","stem":"점검표에서 「아니요」가 나오면 「예」로 고쳐 두면 돼요.","answer":"X","reason_options":[{"t":"「아니요」가 나온 줄이 다음에 고칠 부분이라 그 줄로 돌아가 다시 생각해야 하기 때문에","correct":true},{"t":"점검표는 모두 「예」가 되어야 잘한 것이기 때문에","mis":"K4-2-u5-X31"}],"mis":"K4-2-u5-X31","explanation":["점검표는 고칠 곳을 찾는 표예요.","「아니요」가 그 자리예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_basic#5','kor',4,2,'u5','L05','g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C28',2,'match','auto','온라인 대화 계획의 칸과 정한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u5-C28","difficulty":2,"kind":"match","stem":"온라인 대화 계획의 칸과 정한 내용을 알맞게 이으세요.","pairs":[{"l":"대화 상대","r":"다른 학교 4학년 친구들"},{"l":"온라인으로 하는 까닭","r":"서로 학교가 달라 만나기 어렵기 때문에"},{"l":"대화 주제","r":"학교 텃밭에서 기른 것 소개하기"}],"mis":"K4-2-u5-X27","explanation":["누구와?","왜 온라인으로?","무엇에 대해?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_basic#6','kor',4,2,'u5','L05','g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C29',2,'mc','auto','이웃 어른께 온라인으로 여쭐 때 알맞은 말은 무엇인가요?',ARRAY['K4-2-u5-X28']::text[],false,'{"seq":6,"concept":"K4-2-u5-C29","difficulty":2,"kind":"mc","stem":"이웃 어른께 온라인으로 여쭐 때 알맞은 말은 무엇인가요?","options":[{"t":"「안녕하세요. 내일 몇 시에 뵐 수 있을까요?」","correct":true},{"t":"「내일 몇 시야? 빨리 답 줘.」","mis":"K4-2-u5-X28"},{"t":"「내일요. 시간.」","mis":"K4-2-u5-X28"},{"t":"「내일 몇 시에 볼 수 있어?」","mis":"K4-2-u5-X28"}],"explanation":["받는 사람이 웃어른이에요.","화면에서도 높여요.","「뵐 수 있을까요?」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_basic#7','kor',4,2,'u5','L05','g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C26',2,'mc','auto','온라인 대화가 특히 편리한 때는 언제인가요?',ARRAY['K4-2-u5-X06','K4-2-u5-X14']::text[],false,'{"seq":7,"concept":"K4-2-u5-C26","difficulty":2,"kind":"mc","stem":"온라인 대화가 특히 편리한 때는 언제인가요?","options":[{"t":"서로 시간이 맞지 않아 각자 편한 때에 글을 남겨야 할 때","correct":true},{"t":"옆에 앉은 짝과 바로 이야기하고 싶을 때","mis":"K4-2-u5-X06"},{"t":"마음이 상한 친구와 얼굴 보고 풀고 싶을 때","mis":"K4-2-u5-X06"},{"t":"편리하니 만나서 하는 대화를 그만두고 싶을 때","mis":"K4-2-u5-X14"}],"explanation":["시간이 안 맞을 때가 있어요.","글로 남겨 둘 수 있어요.","그때 편리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_basic#8','kor',4,2,'u5','L05','g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C31',2,'mc','auto','대화방에서 할 일이 생겨 먼저 나가야 해요. 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X34','K4-2-u5-X61']::text[],false,'{"seq":8,"concept":"K4-2-u5-C31","difficulty":2,"kind":"mc","stem":"대화방에서 할 일이 생겨 먼저 나가야 해요. 알맞은 것은 무엇인가요?","options":[{"t":"「할 일이 생겨서 먼저 나갈게. 다음에 또 이야기하자.」라고 남긴다","correct":true},{"t":"아무 말 없이 나간다","mis":"K4-2-u5-X34"},{"t":"「끝.」이라고만 남기고 나간다","mis":"K4-2-u5-X34"},{"t":"나간다는 말 대신 그림말만 하나 보낸다","mis":"K4-2-u5-X61"}],"explanation":["먼저 나갈 땐 양해를 구해요.","까닭을 밝혀요.","인사도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_basic#9','kor',4,2,'u5','L05','g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C34',2,'mc','auto','오늘 배운 것으로 다짐을 정할 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X33','K4-2-u5-X31']::text[],false,'{"seq":9,"concept":"K4-2-u5-C34","difficulty":2,"kind":"mc","stem":"오늘 배운 것으로 다짐을 정할 때 알맞은 것은 무엇인가요?","options":[{"t":"배운 것 가운데 한 가지를 골라 이번 주에 꼭 지킨다","correct":true},{"t":"배운 것을 모두 다짐으로 적어 둔다","mis":"K4-2-u5-X33"},{"t":"다짐은 많을수록 좋으니 열 가지를 쓴다","mis":"K4-2-u5-X33"},{"t":"지켰는지 묻는 표에 「예」를 미리 다 표시해 둔다","mis":"K4-2-u5-X31"}],"explanation":["많이 정하기보다요.","하나를 지켜요.","한 가지를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_basic#10','kor',4,2,'u5','L05','g4_2_kor_u5_L05_basic','lesson_basic','K4-2-u5-C30',3,'error','auto','모르는 사람이 말을 걸어올 때를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u5-X29','K4-2-u5-X30']::text[],false,'{"seq":10,"concept":"K4-2-u5-C30","difficulty":3,"kind":"error","stem":"모르는 사람이 말을 걸어올 때를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「예절을 지켜야 하니 물어보면 사는 곳을 알려 줘야 해.」","correct":true,"mis_target":"K4-2-u5-X29"},{"t":"친구 가 — 「만나자고 해도 따르지 않아.」","mis":"K4-2-u5-X30"},{"t":"친구 다 — 「어른께 바로 알려.」","mis":"K4-2-u5-X30"}],"explanation":["이것은 예절의 일이 아니에요.","나를 지키는 일이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_challenge#1','kor',4,2,'u5','L05','g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C28',2,'sa','auto','온라인 대화 계획에서 「누구와 할까요」를 정하는 칸의 이름은 「대화 (  )」예요. 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u5-C28","difficulty":2,"kind":"sa","stem":"온라인 대화 계획에서 「누구와 할까요」를 정하는 칸의 이름은 「대화 (  )」예요. 빈칸에 알맞은 말을 쓰세요.","answer":["상대"],"explanation":["누구와 하나요?","대화하는 사람이에요.","‘상대’예요."],"mis":"K4-2-u5-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_challenge#2','kor',4,2,'u5','L05','g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C26',2,'mc','auto','민솔이에게 온라인 대화가 고마웠던 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X03','K4-2-u5-X26','K4-2-u5-X16']::text[],false,'{"seq":2,"concept":"K4-2-u5-C26","difficulty":2,"kind":"mc","stem":"민솔이에게 온라인 대화가 고마웠던 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"떨어져 있어 만날 수 없는데도 반 친구들의 소식을 날마다 받을 수 있었기 때문에","correct":true},{"t":"병원에서는 예절을 지키지 않아도 되기 때문에","mis":"K4-2-u5-X03"},{"t":"온라인 대화가 직접 만나는 것보다 언제나 좋기 때문에","mis":"K4-2-u5-X26"},{"t":"반 친구들이 그림말만 보내 주었기 때문에","mis":"K4-2-u5-X16"}],"explanation":["민솔이는 입원해 있었어요.","만날 수 없었어요.","소식을 받을 수 있었어요."],"asset":{"type":"speech","turns":[{"who":"민솔","text":"입원해 있는 동안 학교에 못 갔는데, 반 친구들이 날마다 대화방에 소식을 남겨 주었어."},{"who":"나윤","text":"혼자 있는 것 같지 않았겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_challenge#3','kor',4,2,'u5','L05','g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C29',3,'mc','auto','친구에게 보낸 「자료 보냈어. 확인해 줘.」를 선생님께 보낼 말로 알맞게 바꾼 것은 무엇인가요?',ARRAY['K4-2-u5-X28','K4-2-u5-X40']::text[],false,'{"seq":3,"concept":"K4-2-u5-C29","difficulty":3,"kind":"mc","stem":"친구에게 보낸 「자료 보냈어. 확인해 줘.」를 선생님께 보낼 말로 알맞게 바꾼 것은 무엇인가요?","options":[{"t":"「자료 보내 드렸습니다. 확인해 주시겠어요?」","correct":true},{"t":"「자료 보냈어요. 확인해.」","mis":"K4-2-u5-X28"},{"t":"「자료 보냈습니다. 확인해 줘.」","mis":"K4-2-u5-X40"},{"t":"「자료. 확인.」","mis":"K4-2-u5-X28"}],"explanation":["누구에게 하나요?","문장 끝까지 높여요.","「주시겠어요?」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_challenge#4','kor',4,2,'u5','L05','g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C30',3,'mc','auto','이런 쪽지를 받았을 때 알맞게 한 것은 무엇인가요?',ARRAY['K4-2-u5-X29','K4-2-u5-X30']::text[],false,'{"seq":4,"concept":"K4-2-u5-C30","difficulty":3,"kind":"mc","stem":"이런 쪽지를 받았을 때 알맞게 한 것은 무엇인가요?","options":[{"t":"학교와 사진을 알려 주지 않고 부모님이나 선생님께 바로 보여 드린다","correct":true},{"t":"같은 4학년이라니 학교 이름 정도는 알려 준다","mis":"K4-2-u5-X29"},{"t":"친구 해 준다니 사진을 한 장 보낸다","mis":"K4-2-u5-X29"},{"t":"무섭지만 혼자 지우고 아무에게도 말하지 않는다","mis":"K4-2-u5-X30"}],"explanation":["모르는 사람이에요.","알려 주지 않아요.","어른께 바로 알려요."],"asset":{"type":"speech","turns":[{"who":"모르는 사람","text":"안녕? 나도 4학년이야. 너 어느 학교 다녀?"},{"who":"모르는 사람","text":"사진 한 장 보내 주면 친구 해 줄게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_challenge#5','kor',4,2,'u5','L05','g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C27',3,'ox','auto','온라인 대화는 편리하니까 짝과 다툰 일도 온라인으로 사과하는 것이 언제나 더 나아요.',ARRAY['K4-2-u5-X26']::text[],false,'{"seq":5,"concept":"K4-2-u5-C27","difficulty":3,"kind":"ox","stem":"온라인 대화는 편리하니까 짝과 다툰 일도 온라인으로 사과하는 것이 언제나 더 나아요.","answer":"X","reason_options":[{"t":"마음이 상한 일을 풀 때는 표정과 목소리가 함께 가는 직접 대화가 더 잘 전해질 수 있기 때문에","correct":true},{"t":"온라인 대화는 언제나 만나서 하는 대화보다 편하기 때문에","mis":"K4-2-u5-X26"}],"mis":"K4-2-u5-X26","explanation":["언제나 편하지는 않아요.","표정과 목소리가 필요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_challenge#6','kor',4,2,'u5','L05','g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C33',3,'mc','auto','대화를 마치고 스스로 확인하는 표에 점수가 없는 까닭은 무엇인가요?',ARRAY['K4-2-u5-X32','K4-2-u5-X31']::text[],false,'{"seq":6,"concept":"K4-2-u5-C33","difficulty":3,"kind":"mc","stem":"대화를 마치고 스스로 확인하는 표에 점수가 없는 까닭은 무엇인가요?","options":[{"t":"잘한 것처럼 보이려고가 아니라 「아니요」 줄을 찾아 고치려고 채우는 표이기 때문에","correct":true},{"t":"점검표는 아무렇게나 채워도 되기 때문에","mis":"K4-2-u5-X32"},{"t":"모두 「예」가 나오면 점수가 필요 없기 때문에","mis":"K4-2-u5-X31"},{"t":"점검은 하지 않아도 되는 일이기 때문에","mis":"K4-2-u5-X32"}],"explanation":["보이려고 채우지 않아요.","고칠 곳을 찾아요.","그래서 점수가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_challenge#7','kor',4,2,'u5','L05','g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C32',3,'mc','auto','서아가 「민재야, 무슨 말이야?」라고 물었어요. 민재가 할 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X22','K4-2-u5-X61']::text[],false,'{"seq":7,"concept":"K4-2-u5-C32","difficulty":3,"kind":"mc","stem":"서아가 「민재야, 무슨 말이야?」라고 물었어요. 민재가 할 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「미안, 줄여 써서 헷갈렸지? 나는 금요일에 물을 줄게.」","correct":true},{"t":"같은 줄인 말을 한 번 더 보낸다","mis":"K4-2-u5-X22"},{"t":"「그것도 모르냐?」라고 보낸다","mis":"K4-2-u5-X22"},{"t":"그림말 하나만 보내고 나간다","mis":"K4-2-u5-X61"}],"explanation":["못 알아들은 건 서아 잘못이 아니에요.","풀어서 다시 말해요.","당번 이야기로 돌아와요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"이번 주 텃밭 물 당번 순서 정하자."},{"who":"민재","text":"(주제와 상관없는 그림말만 계속 보냄)"},{"who":"서아","text":"민재야, 당번 순서 먼저 정하고 이야기하자."},{"who":"민재","text":"(뜻을 알기 어렵게 줄인 말로 대답함)"},{"who":"하준","text":"그럼 월요일은 내가 할게. 화요일은 누가 할래?"},{"who":"서아","text":"나는 수요일이 좋아. 민재는?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_challenge#8','kor',4,2,'u5','L05','g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C28',4,'essay','teacher','학교 텃밭 이야기를 다른 학교 친구들과 나누는 온라인 대화를 계획해 보세요. 네 칸(대화 상대 · 온라인으로 하는 까닭 · 대화 방식 · 대화 주제)을 모두 채워 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u5-C28","difficulty":4,"kind":"essay","stem":"학교 텃밭 이야기를 다른 학교 친구들과 나누는 온라인 대화를 계획해 보세요. 네 칸(대화 상대 · 온라인으로 하는 까닭 · 대화 방식 · 대화 주제)을 모두 채워 쓰세요.","answer_guide":{"answer":"예: 대화 상대 — 다른 학교 4학년 친구들 · 까닭 — 학교가 멀어 직접 만나기 어렵기 때문에 · 대화 방식 — 학급끼리 함께 들어오는 영상 회의 · 대화 주제 — 서로의 텃밭에서 기른 채소 소개하기.","scoring_points":["네 칸을 모두 채웠는가","온라인으로 하는 까닭이 상대와 이어지는가","대화 주제를 하나로 정했는가"]},"explanation":["누구 · 왜","어떻게 · 무엇","네 칸을 모두요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_challenge#9','kor',4,2,'u5','L05','g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C33',4,'essay','teacher','온라인 대화 점검표의 「올리기 전에 사실인지 확인했나요」에 「아니요」가 나왔어요. 다음에 할 일을 쓰고, 점검표를 그렇게 쓰는 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u5-C33","difficulty":4,"kind":"essay","stem":"온라인 대화 점검표의 「올리기 전에 사실인지 확인했나요」에 「아니요」가 나왔어요. 다음에 할 일을 쓰고, 점검표를 그렇게 쓰는 까닭을 쓰세요.","answer_guide":{"answer":"예: 내가 올린 글 가운데 확인하지 않은 것이 있는지 다시 보고, 다음에는 올리기 전에 정말인지 먼저 알아본다. 점검표는 잘한 것처럼 보이려고 채우는 것이 아니라 「아니요」가 나온 줄을 찾아 고치려고 쓰기 때문이다.","scoring_points":["「아니요」 줄로 돌아가 고칠 일을 썼는가","「예」로 고쳐 두거나 넘기지 않았는가","점검표의 쓸모를 까닭으로 썼는가"]},"explanation":["그 줄로 돌아가요.","어떻게 고칠지 써요.","고칠 곳 찾는 표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L05_challenge#10','kor',4,2,'u5','L05','g4_2_kor_u5_L05_challenge','lesson_challenge','K4-2-u5-C27',4,'mc','auto','다음 가운데 온라인 대화와 직접 만나는 대화를 고른 생각이 둘 다 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X26','K4-2-u5-X13','K4-2-u5-X06']::text[],false,'{"seq":10,"concept":"K4-2-u5-C27","difficulty":4,"kind":"mc","stem":"다음 가운데 온라인 대화와 직접 만나는 대화를 고른 생각이 둘 다 알맞은 것은 무엇인가요?","options":[{"t":"반 전체 준비물 알림은 대화방으로, 다툰 짝에게 하는 사과는 만나서","correct":true},{"t":"반 전체 알림도 사과도 모두 대화방으로","mis":"K4-2-u5-X26"},{"t":"반 전체 알림도 사과도 모두 만나서 한 명씩","mis":"K4-2-u5-X13"},{"t":"반 전체 알림은 만나서, 사과는 대화방으로","mis":"K4-2-u5-X06"}],"explanation":["여럿에게 한꺼번에 — 대화방","마음 상한 일 — 만나서","상황마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_basic#1','kor',4,2,'u5','L07','g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C37',1,'mc','auto','유담이의 편지가 전하는 마음은 무엇인가요?',ARRAY['K4-2-u5-X37']::text[],false,'{"seq":1,"concept":"K4-2-u5-C37","difficulty":1,"kind":"mc","stem":"유담이의 편지가 전하는 마음은 무엇인가요?","options":[{"t":"별자리를 알려 주셔서 고마운 마음","correct":true},{"t":"시골에 못 가게 되어 미안한 마음","mis":"K4-2-u5-X37"},{"t":"생일을 축하하는 마음","mis":"K4-2-u5-X37"},{"t":"큰이모가 다치셔서 걱정하는 마음","mis":"K4-2-u5-X37"}],"explanation":["무슨 일이 있었나요?","별자리를 짚어 주셨어요.","고마운 마음이에요."],"asset":{"type":"passage","lines":["큰이모께","큰이모, 안녕하세요? 요즘 바람이 차가워졌는데 건강하시지요?","여름 방학에 큰이모 댁에서 지낸 사흘이 자꾸 생각나서 편지를 써요.","그날 밤 큰이모께서 마당에서 별자리 이름을 하나씩 짚어 주셨지요.","돌아온 뒤에도 밤마다 창밖을 올려다봐요. 정말 고맙습니다.","다음에 뵈면 제가 외운 별자리를 알려 드릴게요. 건강하세요.","20○○년 ○○월 ○○일","조카 유담 올림"],"title":"유담이가 큰이모께 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_basic#2','kor',4,2,'u5','L07','g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C38',1,'mc','auto','편지의 짜임에서 「조카 유담 올림」은 무엇에 해당하나요?',ARRAY['K4-2-u5-X38','K4-2-u5-X39']::text[],false,'{"seq":2,"concept":"K4-2-u5-C38","difficulty":1,"kind":"mc","stem":"편지의 짜임에서 「조카 유담 올림」은 무엇에 해당하나요?","options":[{"t":"쓴 사람","correct":true},{"t":"받는 사람","mis":"K4-2-u5-X38"},{"t":"첫인사","mis":"K4-2-u5-X38"},{"t":"추신","mis":"K4-2-u5-X39"}],"explanation":["맨 끝에 있어요.","이름 뒤에 「올림」이 있어요.","쓴 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_basic#3','kor',4,2,'u5','L07','g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C39',1,'ox','auto','편지에는 언제나 추신을 꼭 써야 해요.',ARRAY['K4-2-u5-X39']::text[],false,'{"seq":3,"concept":"K4-2-u5-C39","difficulty":1,"kind":"ox","stem":"편지에는 언제나 추신을 꼭 써야 해요.","answer":"X","reason_options":[{"t":"추신은 다 쓴 뒤 보탤 말이 있을 때만 쓰기 때문에","correct":true},{"t":"추신이 없으면 짜임이 모자란 편지이기 때문에","mis":"K4-2-u5-X39"}],"mis":"K4-2-u5-X39","explanation":["추신은 덧붙이는 말이에요.","보탤 말이 있을 때만이요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_basic#4','kor',4,2,'u5','L07','g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C36',1,'mc','auto','편지로 마음을 전할 때의 좋은 점은 무엇인가요?',ARRAY['K4-2-u5-X36','K4-2-u5-X03']::text[],false,'{"seq":4,"concept":"K4-2-u5-C36","difficulty":1,"kind":"mc","stem":"편지로 마음을 전할 때의 좋은 점은 무엇인가요?","options":[{"t":"천천히 정리하고 고쳐 쓸 수 있어 마음을 더 잘 담을 수 있다","correct":true},{"t":"말보다 언제나 빠르게 닿는다","mis":"K4-2-u5-X36"},{"t":"다른 방법보다 언제나 더 좋은 방법이다","mis":"K4-2-u5-X36"},{"t":"편지에서는 예절을 지키지 않아도 된다","mis":"K4-2-u5-X03"}],"explanation":["말로 할 때와 견주어요.","천천히 써요.","고쳐 쓸 수도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_basic#5','kor',4,2,'u5','L07','g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C38',2,'match','auto','유담이 편지의 줄을 알맞은 짜임에 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u5-C38","difficulty":2,"kind":"match","stem":"유담이 편지의 줄을 알맞은 짜임에 이으세요.","pairs":[{"l":"「큰이모, 안녕하세요? 건강하시지요?」","r":"첫인사"},{"l":"「별자리 이름을 짚어 주셨지요. 고맙습니다.」","r":"전하고 싶은 말"},{"l":"「조카 유담 올림」","r":"쓴 사람"}],"mis":"K4-2-u5-X38","explanation":["안부를 묻는 줄은?","쓴 까닭과 마음은?","이름 뒤 「올림」은?"],"asset":{"type":"passage","lines":["큰이모께","큰이모, 안녕하세요? 요즘 바람이 차가워졌는데 건강하시지요?","여름 방학에 큰이모 댁에서 지낸 사흘이 자꾸 생각나서 편지를 써요.","그날 밤 큰이모께서 마당에서 별자리 이름을 하나씩 짚어 주셨지요.","돌아온 뒤에도 밤마다 창밖을 올려다봐요. 정말 고맙습니다.","다음에 뵈면 제가 외운 별자리를 알려 드릴게요. 건강하세요.","20○○년 ○○월 ○○일","조카 유담 올림"],"title":"유담이가 큰이모께 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_basic#6','kor',4,2,'u5','L07','g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C40',2,'mc','auto','이웃 어른께 쓰는 편지로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X40']::text[],false,'{"seq":6,"concept":"K4-2-u5-C40","difficulty":2,"kind":"mc","stem":"이웃 어른께 쓰는 편지로 알맞은 것은 무엇인가요?","options":[{"t":"「○○○께 … 고맙습니다. ○○○ 올림」","correct":true},{"t":"「○○○에게 … 고마워. ○○○ 씀」","mis":"K4-2-u5-X40"},{"t":"「○○○께 … 고마워. ○○○ 씀」","mis":"K4-2-u5-X40"},{"t":"「○○○께 … 고맙습니다. ○○○ 씀」","mis":"K4-2-u5-X40"}],"explanation":["부르는 말을 봐요.","문장 끝을 봐요.","이름 뒤까지 세 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_basic#7','kor',4,2,'u5','L07','g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C42',2,'mc','auto','유담이가 먼저 썼던 편지에서 고쳐야 할 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X42','K4-2-u5-X39']::text[],false,'{"seq":7,"concept":"K4-2-u5-C42","difficulty":2,"kind":"mc","stem":"유담이가 먼저 썼던 편지에서 고쳐야 할 점으로 알맞은 것은 무엇인가요?","options":[{"t":"웃어른께 쓰는데 높임 표현을 쓰지 않았다","correct":true},{"t":"편지가 너무 길어서 읽기 어렵다","mis":"K4-2-u5-X42"},{"t":"글씨를 또박또박 쓰지 않았다","mis":"K4-2-u5-X42"},{"t":"추신을 쓰지 않았다","mis":"K4-2-u5-X39"}],"explanation":["받는 사람이 누구인가요?","「에게 … 고마워 … 씀」이에요.","높임을 맞추지 않았어요."],"asset":{"type":"passage","lines":["큰이모에게","저 유담이야. 고마운 게 있어서 편지를 씀.","그때 정말 좋았어. 진짜 고마워.","유담 씀"],"title":"유담이가 먼저 썼던 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_basic#8','kor',4,2,'u5','L07','g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C43',2,'mc','auto','「읽는 이를 생각한다」는 무슨 뜻인가요?',ARRAY['K4-2-u5-X43','K4-2-u5-X44','K4-2-u5-X41']::text[],false,'{"seq":8,"concept":"K4-2-u5-C43","difficulty":2,"kind":"mc","stem":"「읽는 이를 생각한다」는 무슨 뜻인가요?","options":[{"t":"전하려는 마음은 그대로 두고, 읽는 이의 상황을 살펴 표현을 고른다","correct":true},{"t":"읽는 이가 좋아할 말만 골라서 쓴다","mis":"K4-2-u5-X43"},{"t":"읽는 이는 생각하지 않고 떠오르는 대로 쓴다","mis":"K4-2-u5-X44"},{"t":"읽는 이가 웃어른일 때만 마음을 쓴다","mis":"K4-2-u5-X41"}],"explanation":["좋아할 말만도 아니에요.","내 마음대로도 아니에요.","마음은 그대로, 표현을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_basic#9','kor',4,2,'u5','L07','g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C35',2,'mc','auto','편지에 대해 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u5-X35']::text[],false,'{"seq":9,"concept":"K4-2-u5-C35","difficulty":2,"kind":"mc","stem":"편지에 대해 알맞게 말한 것은 무엇인가요?","options":[{"t":"종이가 생기기 훨씬 전부터 사람들은 나무판이나 가죽에 글을 적어 마음을 보냈다","correct":true},{"t":"편지는 디지털 기기가 생긴 뒤에 생긴 방법이다","mis":"K4-2-u5-X35"},{"t":"편지는 옛날 것이라 이제는 쓸 수 없다","mis":"K4-2-u5-X35"},{"t":"기기가 없던 때에는 마음이 오가지 않았다","mis":"K4-2-u5-X35"}],"explanation":["편지는 아주 오래된 방법이에요.","흙판·나무판·가죽에도 썼어요.","기기가 없어도 마음은 오갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_basic#10','kor',4,2,'u5','L07','g4_2_kor_u5_L07_basic','lesson_basic','K4-2-u5-C41',3,'error','auto','높임 표현을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u5-X41','K4-2-u5-X40']::text[],false,'{"seq":10,"concept":"K4-2-u5-C41","difficulty":3,"kind":"error","stem":"높임 표현을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「친구에게 높임말을 안 쓰면 마음이 작은 거야.」","correct":true,"mis_target":"K4-2-u5-X41"},{"t":"친구 가 — 「웃어른께는 부르는 말, 문장 끝, 이름 뒤를 모두 높여.」","mis":"K4-2-u5-X40"},{"t":"친구 나 — 「친구에게 쓸 땐 이름 뒤에 ‘씀’을 붙여도 돼.」","mis":"K4-2-u5-X41"}],"explanation":["높임은 상대에 맞춰요.","마음의 크기가 아니에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_challenge#1','kor',4,2,'u5','L07','g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C39',2,'sa','auto','편지를 다 쓴 뒤에 보탤 말이 생겼을 때 덧붙이는 짜임의 이름을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u5-C39","difficulty":2,"kind":"sa","stem":"편지를 다 쓴 뒤에 보탤 말이 생겼을 때 덧붙이는 짜임의 이름을 두 글자로 쓰세요.","answer":["추신"],"explanation":["다 쓴 뒤에 덧붙여요.","필요할 때만 써요.","‘추신’이에요."],"mis":"K4-2-u5-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_challenge#2','kor',4,2,'u5','L07','g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C40',2,'blank','auto','웃어른께 쓰는 편지의 받는 사람을 「큰이모(  )」로 써요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u5-X40']::text[],false,'{"seq":2,"concept":"K4-2-u5-C40","difficulty":2,"kind":"blank","stem":"웃어른께 쓰는 편지의 받는 사람을 「큰이모(  )」로 써요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"께","correct":true},{"t":"에게","mis":"K4-2-u5-X40"},{"t":"한테","mis":"K4-2-u5-X40"},{"t":"야","mis":"K4-2-u5-X40"}],"explanation":["읽는 이가 웃어른이에요.","부르는 말도 높여요.","‘께’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_challenge#3','kor',4,2,'u5','L07','g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C42',3,'mc','auto','하준이의 쪽지에서 「무엇이 고마운지 알 수 없다」를 고친 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X48','K4-2-u5-X40']::text[],false,'{"seq":3,"concept":"K4-2-u5-C42","difficulty":3,"kind":"mc","stem":"하준이의 쪽지에서 「무엇이 고마운지 알 수 없다」를 고친 것으로 알맞은 것은 무엇인가요?","options":[{"t":"「장맛비가 쏟아지던 날 화분을 처마 밑으로 옮겨 주셔서 고맙습니다.」","correct":true},{"t":"「화분 정말정말 아주아주 고마워.」","mis":"K4-2-u5-X48"},{"t":"「고마워. 고마워. 고마워.」","mis":"K4-2-u5-X48"},{"t":"「할머니에게 쓴 쪽지는 이만 줄임.」","mis":"K4-2-u5-X40"}],"explanation":["무슨 일이 있었나요?","그 일을 밝혀요.","있었던 일을 써요."],"asset":{"type":"passage","lines":["할머니에게","화분 고마워.","그럼 안녕.","하준 씀"],"title":"하준이가 먼저 쓴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_challenge#4','kor',4,2,'u5','L07','g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C40',3,'mc','auto','하준이의 쪽지를 높임 표현에 맞게 고친 것은 무엇인가요?',ARRAY['K4-2-u5-X40']::text[],false,'{"seq":4,"concept":"K4-2-u5-C40","difficulty":3,"kind":"mc","stem":"하준이의 쪽지를 높임 표현에 맞게 고친 것은 무엇인가요?","options":[{"t":"「옆집 할머니께 … 고맙습니다 … 하준 올림」","correct":true},{"t":"「옆집 할머니께 … 고마워 … 하준 씀」","mis":"K4-2-u5-X40"},{"t":"「할머니에게 … 고맙습니다 … 하준 올림」","mis":"K4-2-u5-X40"},{"t":"「할머니에게 … 고마워 … 하준 올림」","mis":"K4-2-u5-X40"}],"explanation":["부르는 말 — 께","문장 끝 — 습니다","이름 뒤 — 올림"],"asset":{"type":"passage","lines":["할머니에게","화분 고마워.","그럼 안녕.","하준 씀"],"title":"하준이가 먼저 쓴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_challenge#5','kor',4,2,'u5','L07','g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C43',3,'mc','auto','처음에 시골이 심심할 줄 알았던 유담이가 「읽는 이를 생각하며」 쓴 문장으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X43','K4-2-u5-X44']::text[],false,'{"seq":5,"concept":"K4-2-u5-C43","difficulty":3,"kind":"mc","stem":"처음에 시골이 심심할 줄 알았던 유담이가 「읽는 이를 생각하며」 쓴 문장으로 알맞은 것은 무엇인가요?","options":[{"t":"「처음엔 심심할 줄 알았는데, 그날 밤 별을 보고 생각이 바뀌었어요.」","correct":true},{"t":"「정말 재미없었지만 좋아하실 테니 재미있었다고 쓸게요.」","mis":"K4-2-u5-X43"},{"t":"「시골은 심심하고 벌레도 많아서 다시는 가기 싫어요.」","mis":"K4-2-u5-X44"},{"t":"「큰이모 댁은 언제나 최고예요. 모든 게 완벽했어요.」","mis":"K4-2-u5-X43"}],"explanation":["솔직한 마음도 써요.","읽는 이도 살펴요.","둘 다 담았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_challenge#6','kor',4,2,'u5','L07','g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C36',3,'ox','auto','편지는 닿기까지 시간이 오래 걸리니 마음을 전하는 데 쓸모가 없어요.',ARRAY['K4-2-u5-X05']::text[],false,'{"seq":6,"concept":"K4-2-u5-C36","difficulty":3,"kind":"ox","stem":"편지는 닿기까지 시간이 오래 걸리니 마음을 전하는 데 쓸모가 없어요.","answer":"X","reason_options":[{"t":"시간이 드는 만큼 정성이 담기고 천천히 정리해 오래 남길 수 있기 때문에","correct":true},{"t":"빠르게 닿는 방법이 언제나 더 나은 방법이기 때문에","mis":"K4-2-u5-X05"}],"mis":"K4-2-u5-X05","explanation":["느린 만큼 담기는 것이 있어요.","오래 남아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_challenge#7','kor',4,2,'u5','L07','g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C37',3,'mc','auto','유담이가 편지에서 「무엇이 고마웠는지」를 밝힌 줄은 어느 것인가요?',ARRAY['K4-2-u5-X38','K4-2-u5-X37']::text[],false,'{"seq":7,"concept":"K4-2-u5-C37","difficulty":3,"kind":"mc","stem":"유담이가 편지에서 「무엇이 고마웠는지」를 밝힌 줄은 어느 것인가요?","options":[{"t":"「그날 밤 큰이모께서 마당에서 별자리 이름을 하나씩 짚어 주셨지요.」","correct":true},{"t":"「큰이모, 안녕하세요? 요즘 바람이 차가워졌는데 건강하시지요?」","mis":"K4-2-u5-X38"},{"t":"「20○○년 ○○월 ○○일」","mis":"K4-2-u5-X38"},{"t":"「돌아온 뒤에도 밤마다 창밖을 올려다봐요.」","mis":"K4-2-u5-X37"}],"explanation":["있었던 일을 찾아요.","누가 무엇을 해 주셨나요?","별자리를 짚어 주셨어요."],"asset":{"type":"passage","lines":["큰이모께","큰이모, 안녕하세요? 요즘 바람이 차가워졌는데 건강하시지요?","여름 방학에 큰이모 댁에서 지낸 사흘이 자꾸 생각나서 편지를 써요.","그날 밤 큰이모께서 마당에서 별자리 이름을 하나씩 짚어 주셨지요.","돌아온 뒤에도 밤마다 창밖을 올려다봐요. 정말 고맙습니다.","다음에 뵈면 제가 외운 별자리를 알려 드릴게요. 건강하세요.","20○○년 ○○월 ○○일","조카 유담 올림"],"title":"유담이가 큰이모께 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_challenge#8','kor',4,2,'u5','L07','g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C42',4,'essay','teacher','유담이가 먼저 썼던 편지에서 고쳐야 할 점을 두 가지 이상 쓰고, 그 가운데 한 가지를 골라 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u5-C42","difficulty":4,"kind":"essay","stem":"유담이가 먼저 썼던 편지에서 고쳐야 할 점을 두 가지 이상 쓰고, 그 가운데 한 가지를 골라 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 큰이모께 쓰는데 높임 표현을 쓰지 않았고, 무엇이 고마웠는지 알 수 없고, 첫인사·끝인사·쓴 날짜가 없다. 높임을 고치면 「큰이모께 … 고맙습니다 … 유담 올림」이 된다.","scoring_points":["고칠 점을 두 가지 이상 썼는가","높임·있었던 일·짜임 가운데에서 찾았는가","한 가지를 바르게 고쳐 썼는가"]},"explanation":["받는 사람을 봐요.","무엇이 고마웠나요?","짜임 일곱을 맞춰요."],"asset":{"type":"passage","lines":["큰이모에게","저 유담이야. 고마운 게 있어서 편지를 씀.","그때 정말 좋았어. 진짜 고마워.","유담 씀"],"title":"유담이가 먼저 썼던 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_challenge#9','kor',4,2,'u5','L07','g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C43',4,'essay','teacher','「읽는 이가 좋아할 말만 골라 쓰면 읽는 이를 생각한 편지다」라는 말에 대한 내 생각을 쓰고, 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u5-C43","difficulty":4,"kind":"essay","stem":"「읽는 이가 좋아할 말만 골라 쓰면 읽는 이를 생각한 편지다」라는 말에 대한 내 생각을 쓰고, 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 그렇지 않다. 좋아할 말만 고르면 내가 전하려던 마음이 빠지고 거짓이 될 수 있다. 읽는 이를 생각한다는 것은 전하려는 마음은 그대로 두고, 읽는 이의 상황을 살펴 상처받지 않게 표현을 고르는 것이다.","scoring_points":["「그렇지 않다」는 생각을 밝혔는가","좋아할 말만 쓰면 생기는 문제를 썼는가","마음은 그대로 두고 표현을 고른다는 뜻을 썼는가"]},"explanation":["좋아할 말만은 아니에요.","마음은 그대로예요.","표현을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L07_challenge#10','kor',4,2,'u5','L07','g4_2_kor_u5_L07_challenge','lesson_challenge','K4-2-u5-C41',4,'essay','teacher','친구 서아에게 쓰는 편지와 옆집 할머니께 쓰는 편지에서 받는 사람 · 문장 끝 · 쓴 사람이 어떻게 달라지는지 쓰고, 높임이 달라지는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u5-C41","difficulty":4,"kind":"essay","stem":"친구 서아에게 쓰는 편지와 옆집 할머니께 쓰는 편지에서 받는 사람 · 문장 끝 · 쓴 사람이 어떻게 달라지는지 쓰고, 높임이 달라지는 까닭을 쓰세요.","answer_guide":{"answer":"예: 서아에게는 「서아에게 … 고마워 … 하준 씀」, 할머니께는 「옆집 할머니께 … 고맙습니다 … 하준 올림」으로 쓴다. 높임은 마음의 크기가 아니라 읽는 사람이 누구인지에 맞추는 것이기 때문이다.","scoring_points":["친구에게 쓰는 세 곳을 썼는가","웃어른께 쓰는 세 곳을 높임으로 썼는가","높임은 상대에 맞춘다는 까닭을 썼는가"]},"explanation":["받는 사람 · 문장 끝 · 쓴 사람","상대가 누구인가요?","상대에 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_basic#1','kor',4,2,'u5','L09','g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C45',1,'mc','auto','다음 가운데 편지로 전하기 좋은 일은 무엇인가요?',ARRAY['K4-2-u5-X45']::text[],false,'{"seq":1,"concept":"K4-2-u5-C45","difficulty":1,"kind":"mc","stem":"다음 가운데 편지로 전하기 좋은 일은 무엇인가요?","options":[{"t":"내가 아픈 날 짝이 도서 도우미 일을 대신해 주었다","correct":true},{"t":"오늘 급식에 나온 반찬이 입에 잘 맞았다","mis":"K4-2-u5-X45"},{"t":"내일은 비가 오지 않았으면 좋겠다","mis":"K4-2-u5-X45"},{"t":"혼자 공책에 그림을 그렸다","mis":"K4-2-u5-X45"}],"explanation":["그 사람과 나 사이의 일인가요?","마음이 오간 일이에요.","짝이 대신해 주었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_basic#2','kor',4,2,'u5','L09','g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C46',1,'mc','auto','동생이 처음으로 혼자 자전거를 탔어요. 동생에게 전할 마음은 무엇인가요?',ARRAY['K4-2-u5-X46']::text[],false,'{"seq":2,"concept":"K4-2-u5-C46","difficulty":1,"kind":"mc","stem":"동생이 처음으로 혼자 자전거를 탔어요. 동생에게 전할 마음은 무엇인가요?","options":[{"t":"축하","correct":true},{"t":"사과","mis":"K4-2-u5-X46"},{"t":"위로","mis":"K4-2-u5-X46"},{"t":"응원","mis":"K4-2-u5-X46"}],"explanation":["좋은 일이 생겼어요.","해냈어요.","축하예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_basic#3','kor',4,2,'u5','L09','g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C47',1,'mc','auto','편지의 「가운데」에 들어갈 내용은 무엇인가요?',ARRAY['K4-2-u5-X47']::text[],false,'{"seq":3,"concept":"K4-2-u5-C47","difficulty":1,"kind":"mc","stem":"편지의 「가운데」에 들어갈 내용은 무엇인가요?","options":[{"t":"「그날 저 대신 책을 정리해 주셨지요. 정말 고마웠어요.」","correct":true},{"t":"「안녕하세요? 잘 지내시지요?」","mis":"K4-2-u5-X47"},{"t":"「20○○년 ○○월 ○○일 ○○ 올림」","mis":"K4-2-u5-X47"},{"t":"「건강하세요. 또 편지 드릴게요.」","mis":"K4-2-u5-X47"}],"explanation":["인사도 날짜도 아니에요.","편지를 쓴 진짜 까닭이에요.","있었던 일과 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_basic#4','kor',4,2,'u5','L09','g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C48',1,'ox','auto','편지를 구체적으로 쓰라는 말은 문장을 길게 쓰라는 뜻이에요.',ARRAY['K4-2-u5-X48']::text[],false,'{"seq":4,"concept":"K4-2-u5-C48","difficulty":1,"kind":"ox","stem":"편지를 구체적으로 쓰라는 말은 문장을 길게 쓰라는 뜻이에요.","answer":"X","reason_options":[{"t":"무슨 일이 있었는지 읽는 사람이 알 수 있게 쓰라는 뜻이기 때문에","correct":true},{"t":"문장이 길수록 마음이 더 많이 담기기 때문에","mis":"K4-2-u5-X48"}],"mis":"K4-2-u5-X48","explanation":["길이가 아니에요.","무슨 일인지 알 수 있게요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_basic#5','kor',4,2,'u5','L09','g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C46',2,'match','auto','상황에 알맞은 마음을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u5-C46","difficulty":2,"kind":"match","stem":"상황에 알맞은 마음을 이으세요.","pairs":[{"l":"짝이 다리를 다쳐 한동안 학교에 못 온다","r":"위로"},{"l":"내가 약속을 잊어 친구를 오래 기다리게 했다","r":"사과"},{"l":"사촌 언니가 다음 주에 큰 시험을 본다","r":"응원"}],"mis":"K4-2-u5-X46","explanation":["지금 힘든 일을 겪어요.","내가 잘못했어요.","무언가를 앞두고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_basic#6','kor',4,2,'u5','L09','g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C48',2,'mc','auto','㉮와 ㉯ 가운데 마음이 더 잘 전해지는 쪽과 그 까닭은 무엇인가요?',ARRAY['K4-2-u5-X48','K4-2-u5-X49']::text[],false,'{"seq":6,"concept":"K4-2-u5-C48","difficulty":2,"kind":"mc","stem":"㉮와 ㉯ 가운데 마음이 더 잘 전해지는 쪽과 그 까닭은 무엇인가요?","options":[{"t":"㉯ — 무슨 일이 있었는지 읽는 사람이 알 수 있기 때문에","correct":true},{"t":"㉯ — 문장이 더 길기 때문에","mis":"K4-2-u5-X48"},{"t":"㉮ — 짧고 시원해서 읽기 편하기 때문에","mis":"K4-2-u5-X49"},{"t":"㉮ — 「진짜」라는 말을 넣었기 때문에","mis":"K4-2-u5-X48"}],"explanation":["길이로 따지지 않아요.","그 일을 떠올릴 수 있나요?","㉯는 알 수 있어요."],"asset":{"type":"passage","lines":["㉮ 그때 정말 고마웠어. 진짜 좋았어.","㉯ 내가 아파서 못 온 날, 네가 도서 도우미 일을 대신해 주었지.","   돌아와 보니 책이 번호 순서대로 꽂혀 있어서 마음이 놓였어."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_basic#7','kor',4,2,'u5','L09','g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C49',2,'mc','auto','다리를 다쳐 학교에 못 오는 친구에게 쓰는 편지로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X44']::text[],false,'{"seq":7,"concept":"K4-2-u5-C49","difficulty":2,"kind":"mc","stem":"다리를 다쳐 학교에 못 오는 친구에게 쓰는 편지로 알맞은 것은 무엇인가요?","options":[{"t":"「네 자리가 비어 있어서 허전했어. 다 나으면 같이 놀자.」","correct":true},{"t":"「어제 운동장에서 신나게 뛰어놀았어. 너도 빨리 나아.」","mis":"K4-2-u5-X44"},{"t":"「아플 땐 아무 말도 안 하는 게 좋다고 해서 이만 줄일게.」","mis":"K4-2-u5-X44"},{"t":"「네가 없으니 우리 반이 더 신나게 놀고 있어.」","mis":"K4-2-u5-X44"}],"explanation":["친구가 이 줄을 읽을 때를 그려요.","처지를 살펴요.","마음은 그대로 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_basic#8','kor',4,2,'u5','L09','g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C51',2,'mc','auto','이웃 어른께 보내는 편지봉투로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X50','K4-2-u5-X51']::text[],false,'{"seq":8,"concept":"K4-2-u5-C51","difficulty":2,"kind":"mc","stem":"이웃 어른께 보내는 편지봉투로 알맞은 것은 무엇인가요?","options":[{"t":"오른쪽 아래에 「○○○ 귀하」","correct":true},{"t":"왼쪽 위에 「○○○ 귀하」","mis":"K4-2-u5-X50"},{"t":"오른쪽 아래에 「○○○ 앞」","mis":"K4-2-u5-X51"},{"t":"왼쪽 위에 「○○○에게」","mis":"K4-2-u5-X50"}],"explanation":["받는 사람은 어디에?","오른쪽 아래예요.","웃어른은 「귀하」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_basic#9','kor',4,2,'u5','L09','g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C44',2,'mc','auto','편지 쓰기 전 계획에서 「전하고 싶은 마음」 칸에 들어갈 것은 무엇인가요?',ARRAY['K4-2-u5-X27']::text[],false,'{"seq":9,"concept":"K4-2-u5-C44","difficulty":2,"kind":"mc","stem":"편지 쓰기 전 계획에서 「전하고 싶은 마음」 칸에 들어갈 것은 무엇인가요?","options":[{"t":"고마움","correct":true},{"t":"짝","mis":"K4-2-u5-X27"},{"t":"도서 도우미를 대신해 준 일","mis":"K4-2-u5-X27"},{"t":"「정말 고마웠어」라는 말","mis":"K4-2-u5-X27"}],"explanation":["사람 · 있었던 일 · 마음 · 표현","마음 칸이에요.","고마움이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_basic#10','kor',4,2,'u5','L09','g4_2_kor_u5_L09_basic','lesson_basic','K4-2-u5-C50',3,'error','auto','편지를 다 쓴 뒤를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u5-X31','K4-2-u5-X32']::text[],false,'{"seq":10,"concept":"K4-2-u5-C50","difficulty":3,"kind":"error","stem":"편지를 다 쓴 뒤를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「점검표에 ‘아니요’가 나오면 ‘예’로 고쳐 두면 돼.」","correct":true,"mis_target":"K4-2-u5-X31"},{"t":"친구 가 — 「소리 내어 천천히 읽으면 안 보이던 곳이 보여.」","mis":"K4-2-u5-X32"},{"t":"친구 다 — 「‘아니요’가 나온 줄이 고쳐 쓸 부분이야.」","mis":"K4-2-u5-X31"}],"explanation":["점검표는 고칠 곳 찾기예요.","「예」로 고치지 않아요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_challenge#1','kor',4,2,'u5','L09','g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C51',2,'sa','auto','편지봉투에 쓰는 우편 번호는 몇 자리인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u5-C51","difficulty":2,"kind":"sa","stem":"편지봉투에 쓰는 우편 번호는 몇 자리인가요? 숫자로 쓰세요.","answer":["5","다섯"],"explanation":["정확하게 써요.","자리 수를 세요.","다섯 자리예요."],"mis":"K4-2-u5-X51"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_challenge#2','kor',4,2,'u5','L09','g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C52',2,'mc','auto','다 쓴 편지를 두고 알맞게 생각한 것은 무엇인가요?',ARRAY['K4-2-u5-X52','K4-2-u5-X04']::text[],false,'{"seq":2,"concept":"K4-2-u5-C52","difficulty":2,"kind":"mc","stem":"다 쓴 편지를 두고 알맞게 생각한 것은 무엇인가요?","options":[{"t":"직접 건네거나 우체통에 넣어 보내야 마음이 전해진다","correct":true},{"t":"써 두기만 해도 마음은 저절로 전해진다","mis":"K4-2-u5-X52"},{"t":"잘 쓴 편지는 책상 서랍에 넣어 두는 것이 좋다","mis":"K4-2-u5-X52"},{"t":"부치지 않고 다른 사람에게 대신 말해 달라고만 한다","mis":"K4-2-u5-X04"}],"explanation":["편지는 닿아야 편지예요.","건네거나 보내요.","전해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_challenge#3','kor',4,2,'u5','L09','g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C48',3,'mc','auto','이안이의 사과 편지 ㉮와 ㉯ 가운데 마음이 더 잘 전해지는 쪽과 그 까닭은 무엇인가요?',ARRAY['K4-2-u5-X48','K4-2-u5-X49']::text[],false,'{"seq":3,"concept":"K4-2-u5-C48","difficulty":3,"kind":"mc","stem":"이안이의 사과 편지 ㉮와 ㉯ 가운데 마음이 더 잘 전해지는 쪽과 그 까닭은 무엇인가요?","options":[{"t":"㉯ — 무엇을 잘못했는지 밝혀서 서아가 그 일을 떠올릴 수 있기 때문에","correct":true},{"t":"㉮ — 「정말정말 아주아주」로 미안함을 크게 말했기 때문에","mis":"K4-2-u5-X48"},{"t":"㉮ — 짧아서 금방 읽을 수 있기 때문에","mis":"K4-2-u5-X49"},{"t":"㉯ — 글자 수가 더 많기 때문에","mis":"K4-2-u5-X48"}],"explanation":["되풀이가 구체적인 것은 아니에요.","무엇을 잘못했나요?","㉯가 밝혔어요."],"asset":{"type":"passage","lines":["㉮ 서아야, 미안해. 정말정말 아주아주 미안해. 앞으로 진짜 안 그럴게.","㉯ 어제 운동장에서 만나기로 해 놓고 내가 깜빡 잊었어.","   너는 한참이나 나를 기다렸다며. 정말 미안해."],"title":"이안이의 사과 편지 두 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_challenge#4','kor',4,2,'u5','L09','g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C46',3,'mc','auto','다음 가운데 「위로」하는 편지가 어울리는 사람은 누구인가요?',ARRAY['K4-2-u5-X46']::text[],false,'{"seq":4,"concept":"K4-2-u5-C46","difficulty":3,"kind":"mc","stem":"다음 가운데 「위로」하는 편지가 어울리는 사람은 누구인가요?","options":[{"t":"아끼던 화분이 말라 버려 속상해하는 짝","correct":true},{"t":"그림 대회에서 상을 받은 동생","mis":"K4-2-u5-X46"},{"t":"다음 주에 수영 대회에 나가는 사촌","mis":"K4-2-u5-X46"},{"t":"내가 빌린 책을 찢어 버린 일이 있는 친구","mis":"K4-2-u5-X46"}],"explanation":["위로는 언제 하나요?","힘든 일을 겪고 있을 때예요.","속상해하는 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_challenge#5','kor',4,2,'u5','L09','g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C47',3,'mc','auto','다친 친구에게 쓰는 편지의 「끝」에 쓰기 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X47']::text[],false,'{"seq":5,"concept":"K4-2-u5-C47","difficulty":3,"kind":"mc","stem":"다친 친구에게 쓰는 편지의 「끝」에 쓰기 알맞은 것은 무엇인가요?","options":[{"t":"「다 나으면 운동장에서 같이 놀자. 그때까지 잘 지내.」","correct":true},{"t":"「네가 못 온 날, 반에서는 이런 일이 있었어.」","mis":"K4-2-u5-X47"},{"t":"「짝아, 안녕? 다리는 좀 어때?」","mis":"K4-2-u5-X47"},{"t":"「그날 네가 넘어졌을 때 나는 정말 놀랐어.」","mis":"K4-2-u5-X47"}],"explanation":["끝에는 바라는 점과 인사예요.","처음은 안부예요.","가운데는 있었던 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_challenge#6','kor',4,2,'u5','L09','g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C49',3,'ox','auto','다친 친구를 배려하려면 친구가 슬퍼할까 봐 내 솔직한 마음은 하나도 쓰지 않는 것이 좋아요.',ARRAY['K4-2-u5-X44']::text[],false,'{"seq":6,"concept":"K4-2-u5-C49","difficulty":3,"kind":"ox","stem":"다친 친구를 배려하려면 친구가 슬퍼할까 봐 내 솔직한 마음은 하나도 쓰지 않는 것이 좋아요.","answer":"X","reason_options":[{"t":"솔직한 마음을 쓰되 친구의 처지를 살펴 표현을 고르면 되기 때문에","correct":true},{"t":"배려하려면 솔직함은 버려야 하기 때문에","mis":"K4-2-u5-X44"}],"mis":"K4-2-u5-X44","explanation":["솔직함과 배려는 함께예요.","둘 중 하나가 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_challenge#7','kor',4,2,'u5','L09','g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C51',3,'mc','auto','친구 서아에게 보내는 편지봉투로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X50','K4-2-u5-X51']::text[],false,'{"seq":7,"concept":"K4-2-u5-C51","difficulty":3,"kind":"mc","stem":"친구 서아에게 보내는 편지봉투로 알맞은 것은 무엇인가요?","options":[{"t":"오른쪽 아래에 받는 사람 주소와 「서아에게」","correct":true},{"t":"왼쪽 위에 받는 사람 주소와 「서아에게」","mis":"K4-2-u5-X50"},{"t":"오른쪽 아래에 받는 사람 주소만 쓰고 이름은 빼기","mis":"K4-2-u5-X51"},{"t":"오른쪽 아래에 우편 번호를 아무 숫자나 세 자리로","mis":"K4-2-u5-X51"}],"explanation":["받는 사람은 오른쪽 아래","친구에게는 「에게」","우편 번호는 다섯 자리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_challenge#8','kor',4,2,'u5','L09','g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C44',4,'essay','teacher','고마운 마음을 전하고 싶은 사람을 한 명 정해 편지 계획 네 가지(전할 사람 · 있었던 일 · 전하고 싶은 마음 · 마음을 나타내는 표현)를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u5-C44","difficulty":4,"kind":"essay","stem":"고마운 마음을 전하고 싶은 사람을 한 명 정해 편지 계획 네 가지(전할 사람 · 있었던 일 · 전하고 싶은 마음 · 마음을 나타내는 표현)를 쓰세요.","answer_guide":{"answer":"예: 전할 사람 — 이사 가시는 아랫집 어른 · 있었던 일 — 내가 열쇠를 잃어버린 날 집에 들어가게 해 주셨다 · 전하고 싶은 마음 — 고마움 · 표현 — 「그날 덕분에 무섭지 않았어요. 고맙습니다.」","scoring_points":["네 가지를 모두 썼는가","있었던 일이 그 사람과 나 사이에 마음이 오간 일인가","표현이 마음과 이어지는가"]},"explanation":["누구에게?","무슨 일이?","어떤 마음, 어떤 말?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_challenge#9','kor',4,2,'u5','L09','g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C48',4,'essay','teacher','이안이의 ㉮ 편지를 「무슨 일이 있었는지 알 수 있게」 고쳐 쓰고, 「정말정말 아주아주」를 늘리는 것과 무엇이 다른지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u5-C48","difficulty":4,"kind":"essay","stem":"이안이의 ㉮ 편지를 「무슨 일이 있었는지 알 수 있게」 고쳐 쓰고, 「정말정말 아주아주」를 늘리는 것과 무엇이 다른지 쓰세요.","answer_guide":{"answer":"예: 「서아야, 어제 운동장에서 만나기로 해 놓고 내가 깜빡 잊었어. 오래 기다리게 해서 정말 미안해.」 — 「정말정말」을 늘리면 길어지기만 하고, 무슨 일인지 밝히면 서아가 그 일을 떠올리며 내 마음을 알 수 있다.","scoring_points":["무엇을 잘못했는지 밝혀 고쳐 썼는가","강조어를 되풀이하지 않았는가","길게 쓰는 것과 구체적으로 쓰는 것의 차이를 썼는가"]},"explanation":["무슨 일이었나요?","되풀이는 빼요.","떠올릴 수 있게요."],"asset":{"type":"passage","lines":["㉮ 서아야, 미안해. 정말정말 아주아주 미안해. 앞으로 진짜 안 그럴게.","㉯ 어제 운동장에서 만나기로 해 놓고 내가 깜빡 잊었어.","   너는 한참이나 나를 기다렸다며. 정말 미안해."],"title":"이안이의 사과 편지 두 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L09_challenge#10','kor',4,2,'u5','L09','g4_2_kor_u5_L09_challenge','lesson_challenge','K4-2-u5-C49',4,'essay','teacher','다리를 다쳐 학교에 못 오는 짝에게 위로하는 편지의 가운데 부분을 두세 문장으로 쓰고, 짝의 처지를 어떻게 살폈는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u5-C49","difficulty":4,"kind":"essay","stem":"다리를 다쳐 학교에 못 오는 짝에게 위로하는 편지의 가운데 부분을 두세 문장으로 쓰고, 짝의 처지를 어떻게 살폈는지 쓰세요.","answer_guide":{"answer":"예: 「네가 없으니 짝 자리가 허전해. 오늘 배운 노래는 네가 오면 같이 불러 보자. 많이 답답하지?」 — 짝이 밖에서 뛰어놀 수 없는 처지라서 신나게 논 이야기 대신 짝을 기다리는 마음을 썼다.","scoring_points":["위로하는 마음이 드러나는가","짝의 처지를 살펴 표현을 골랐는가","어떻게 살폈는지 까닭을 썼는가"]},"explanation":["짝은 지금 어떤 처지인가요?","마음은 그대로 전해요.","표현을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_basic#1','kor',4,2,'u5','L11','g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C54',1,'mc','auto','온라인 대화 예절을 알리는 표어로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X53','K4-2-u5-X54']::text[],false,'{"seq":1,"concept":"K4-2-u5-C54","difficulty":1,"kind":"mc","stem":"온라인 대화 예절을 알리는 표어로 알맞은 것은 무엇인가요?","options":[{"t":"「화면 너머에도 사람이 있어요」","correct":true},{"t":"「온라인 대화는 기기를 사용하고 시간과 장소에 매이지 않습니다」","mis":"K4-2-u5-X53"},{"t":"「온라인 대화, 아예 하지 맙시다」","mis":"K4-2-u5-X54"},{"t":"「사진도 묻고 사실도 확인하고 존중도 하고 그림말도 줄입시다」","mis":"K4-2-u5-X53"}],"explanation":["짧은 한 줄이에요.","한 가지만 말해요.","바로 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_basic#2','kor',4,2,'u5','L11','g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C58',1,'mc','auto','「읽고」는 어떻게 소리 나나요?',ARRAY['K4-2-u5-X58','K4-2-u5-X59']::text[],false,'{"seq":2,"concept":"K4-2-u5-C58","difficulty":1,"kind":"mc","stem":"「읽고」는 어떻게 소리 나나요?","options":[{"t":"[일꼬]","correct":true},{"t":"[익꼬]","mis":"K4-2-u5-X58"},{"t":"[읽꼬]","mis":"K4-2-u5-X59"},{"t":"[이꼬]","mis":"K4-2-u5-X58"}],"explanation":["ㄺ 뒤에 무엇이 오나요?","ㄱ이 와요.","ㄹ로 소리 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_basic#3','kor',4,2,'u5','L11','g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C56',1,'mc','auto','비밀 친구 편지에 쓰지 않는 것이 좋은 내용은 무엇인가요?',ARRAY['K4-2-u5-X56']::text[],false,'{"seq":3,"concept":"K4-2-u5-C56","difficulty":1,"kind":"mc","stem":"비밀 친구 편지에 쓰지 않는 것이 좋은 내용은 무엇인가요?","options":[{"t":"둘이서만 겪었던 특별한 일","correct":true},{"t":"그 친구의 좋은 점 칭찬","mis":"K4-2-u5-X56"},{"t":"앞으로 친하게 지내고 싶다는 마음","mis":"K4-2-u5-X56"},{"t":"「○○에게」로 시작하는 부르는 말","mis":"K4-2-u5-X56"}],"explanation":["마지막 날까지 비밀이에요.","둘만 아는 일은 들켜요.","좋은 점을 칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_basic#4','kor',4,2,'u5','L11','g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C57',1,'ox','auto','매체 견주기 놀이는 어느 매체가 이기는지 정하는 놀이예요.',ARRAY['K4-2-u5-X57']::text[],false,'{"seq":4,"concept":"K4-2-u5-C57","difficulty":1,"kind":"ox","stem":"매체 견주기 놀이는 어느 매체가 이기는지 정하는 놀이예요.","answer":"X","reason_options":[{"t":"매체마다 잘하는 일이 달라 무엇을 잘하는지 견주는 놀이이기 때문에","correct":true},{"t":"모든 면에서 더 좋은 매체가 하나 있기 때문에","mis":"K4-2-u5-X57"}],"mis":"K4-2-u5-X57","explanation":["이기고 지는 놀이가 아니에요.","잘하는 일이 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_basic#5','kor',4,2,'u5','L11','g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C55',2,'mc','auto','표어를 온 학교에 오래 알리기에 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u5-X55']::text[],false,'{"seq":5,"concept":"K4-2-u5-C55","difficulty":2,"kind":"mc","stem":"표어를 온 학교에 오래 알리기에 알맞은 방법은 무엇인가요?","options":[{"t":"학교 알림판에 표어를 붙여 둔다","correct":true},{"t":"우리 모둠끼리 한 번 말해 본다","mis":"K4-2-u5-X55"},{"t":"내 공책에 적어 둔다","mis":"K4-2-u5-X55"},{"t":"짝에게만 쪽지로 알려 준다","mis":"K4-2-u5-X55"}],"explanation":["몇 사람이 보나요?","며칠 동안 보나요?","알림판이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_basic#6','kor',4,2,'u5','L11','g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C57',2,'mc','auto','매체 견주기 놀이에서 대답으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X57','K4-2-u5-X35','K4-2-u5-X05']::text[],false,'{"seq":6,"concept":"K4-2-u5-C57","difficulty":2,"kind":"mc","stem":"매체 견주기 놀이에서 대답으로 알맞은 것은 무엇인가요?","options":[{"t":"「온라인 대화방은 더 빠르고, 편지는 더 오래 남습니다」","correct":true},{"t":"「온라인 대화방이 편지보다 모든 면에서 더 좋습니다」","mis":"K4-2-u5-X57"},{"t":"「편지는 옛날 것이라 이제는 쓸 수 없습니다」","mis":"K4-2-u5-X35"},{"t":"「편지가 온라인 대화방보다 모든 면에서 더 좋습니다」","mis":"K4-2-u5-X05"}],"explanation":["어느 쪽이 이기나요? ✗","어느 쪽이 무엇을 잘하나요?","잘하는 일이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_basic#7','kor',4,2,'u5','L11','g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C58',2,'match','auto','낱말과 알맞은 발음을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K4-2-u5-C58","difficulty":2,"kind":"match","stem":"낱말과 알맞은 발음을 이으세요.","pairs":[{"l":"늙다","r":"[늑따]"},{"l":"늙고","r":"[늘꼬]"},{"l":"읽다","r":"[익따]"}],"mis":"K4-2-u5-X58","explanation":["뒤 글자의 첫소리를 봐요.","ㄱ이면 [ㄹ]","아니면 [ㄱ]"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_basic#8','kor',4,2,'u5','L11','g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C59',2,'mc','auto','「밟고」는 어떻게 소리 나나요?',ARRAY['K4-2-u5-X60','K4-2-u5-X59']::text[],false,'{"seq":8,"concept":"K4-2-u5-C59","difficulty":2,"kind":"mc","stem":"「밟고」는 어떻게 소리 나나요?","options":[{"t":"[밥꼬]","correct":true},{"t":"[발꼬]","mis":"K4-2-u5-X60"},{"t":"[밟꼬]","mis":"K4-2-u5-X59"},{"t":"[밤꼬]","mis":"K4-2-u5-X60"}],"explanation":["ㄼ은 보통 [ㄹ]이에요.","그런데 밟-은 달라요.","[밥꼬]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_basic#9','kor',4,2,'u5','L11','g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C60',2,'mc','auto','「바빠서 이만.」을 알아듣고 서운하지 않게 다시 쓴 말은 무엇인가요?',ARRAY['K4-2-u5-X61','K4-2-u5-X34']::text[],false,'{"seq":9,"concept":"K4-2-u5-C60","difficulty":2,"kind":"mc","stem":"「바빠서 이만.」을 알아듣고 서운하지 않게 다시 쓴 말은 무엇인가요?","options":[{"t":"「할 일이 있어서 먼저 나갈게. 내일 봐.」","correct":true},{"t":"「바쁨. 끝.」","mis":"K4-2-u5-X61"},{"t":"(아무 말 없이 대화방을 나간다)","mis":"K4-2-u5-X34"},{"t":"(손 흔드는 그림말 하나만 보낸다)","mis":"K4-2-u5-X61"}],"explanation":["받는 사람의 마음을 그려요.","까닭을 밝혀요.","인사도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_basic#10','kor',4,2,'u5','L11','g4_2_kor_u5_L11_basic','lesson_basic','K4-2-u5-C53',3,'error','auto','실천 활동을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u5-X53','K4-2-u5-X54']::text[],false,'{"seq":10,"concept":"K4-2-u5-C53","difficulty":3,"kind":"error","stem":"실천 활동을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「표어는 이 화면에서 다 지어 볼 수 있어.」","correct":true,"mis_target":"K4-2-u5-X53"},{"t":"친구 나 — 「표어를 짓는 일은 교실에서 하고, 화면에서는 기준을 정해.」","mis":"K4-2-u5-X53"},{"t":"친구 다 — 「지은 표어는 그 기준으로 스스로 가려낼 수 있어.」","mis":"K4-2-u5-X54"}],"explanation":["짓는 일은 교실에서요.","화면에서는 기준을요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
