INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_challenge#3','kor',4,2,'u5','L11','g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C58',3,'mc','auto','다음 가운데 ㄺ이 [ㄹ]로 소리 나는 낱말은 무엇인가요?',ARRAY['K4-2-u5-X58']::text[],false,'{"seq":3,"concept":"K4-2-u5-C58","difficulty":3,"kind":"mc","stem":"다음 가운데 ㄺ이 [ㄹ]로 소리 나는 낱말은 무엇인가요?","options":[{"t":"낡고","correct":true},{"t":"낡다","mis":"K4-2-u5-X58"},{"t":"긁지","mis":"K4-2-u5-X58"},{"t":"굵다","mis":"K4-2-u5-X58"}],"explanation":["뒤 글자의 첫소리를 봐요.","ㄱ이 오는 것은?","낡고[날꼬]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_challenge#4','kor',4,2,'u5','L11','g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C59',3,'mc','auto','다음 ㄼ 낱말 가운데 받침 소리가 다른 하나는 무엇인가요?',ARRAY['K4-2-u5-X60']::text[],false,'{"seq":4,"concept":"K4-2-u5-C59","difficulty":3,"kind":"mc","stem":"다음 ㄼ 낱말 가운데 받침 소리가 다른 하나는 무엇인가요?","options":[{"t":"밟다","correct":true},{"t":"넓다","mis":"K4-2-u5-X60"},{"t":"얇다","mis":"K4-2-u5-X60"},{"t":"짧다","mis":"K4-2-u5-X60"}],"explanation":["ㄼ은 보통 [ㄹ]이에요.","밟-만 달라요.","밟다[밥따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_challenge#5','kor',4,2,'u5','L11','g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C56',3,'mc','auto','비밀 친구 편지로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X56','K4-2-u5-X41']::text[],false,'{"seq":5,"concept":"K4-2-u5-C56","difficulty":3,"kind":"mc","stem":"비밀 친구 편지로 알맞은 것은 무엇인가요?","options":[{"t":"「○○에게 — 모둠 활동 때 친구들 말을 끝까지 들어 주는 네가 멋져. 비밀 친구 씀」","correct":true},{"t":"「○○에게 — 어제 둘이서 문구점 앞에서 나눈 이야기 기억나지? 비밀 친구 씀」","mis":"K4-2-u5-X56"},{"t":"「○○께 — 언제나 응원합니다. 비밀 친구 올림」","mis":"K4-2-u5-X41"},{"t":"「○○에게 — 나는 셋째 줄 맨 앞자리에 앉는 친구야. 비밀 친구 씀」","mis":"K4-2-u5-X56"}],"explanation":["누구인지 드러나면 안 돼요.","좋은 점을 칭찬해요.","친구에게는 「에게 … 씀」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_challenge#6','kor',4,2,'u5','L11','g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C54',3,'ox','auto','표어에는 지켜야 할 예절을 되도록 많이 담을수록 좋아요.',ARRAY['K4-2-u5-X53']::text[],false,'{"seq":6,"concept":"K4-2-u5-C54","difficulty":3,"kind":"ox","stem":"표어에는 지켜야 할 예절을 되도록 많이 담을수록 좋아요.","answer":"X","reason_options":[{"t":"여러 가지를 담으면 하나도 마음에 남지 않아 한 가지만 짧게 담아야 하기 때문에","correct":true},{"t":"많이 담아야 빠뜨린 예절이 없기 때문에","mis":"K4-2-u5-X53"}],"mis":"K4-2-u5-X53","explanation":["표어는 한 줄이에요.","한 가지만 남겨요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_challenge#7','kor',4,2,'u5','L11','g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C60',3,'mc','auto','대화방에서 친구가 「그건 좀.」이라고만 보냈어요. 알아듣고 서운하지 않게 다시 쓴 것은 무엇인가요?',ARRAY['K4-2-u5-X61','K4-2-u5-X22']::text[],false,'{"seq":7,"concept":"K4-2-u5-C60","difficulty":3,"kind":"mc","stem":"대화방에서 친구가 「그건 좀.」이라고만 보냈어요. 알아듣고 서운하지 않게 다시 쓴 것은 무엇인가요?","options":[{"t":"「그 방법은 시간이 오래 걸릴 것 같아. 다른 방법도 같이 찾아보자.」","correct":true},{"t":"「별로.」","mis":"K4-2-u5-X61"},{"t":"(고개 젓는 그림말만 보낸다)","mis":"K4-2-u5-X61"},{"t":"「그건 좀이라고. 알아서 해.」","mis":"K4-2-u5-X22"}],"explanation":["툭 던지는 말이에요.","까닭을 밝혀요.","함께 하자고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_challenge#8','kor',4,2,'u5','L11','g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C54',4,'essay','teacher','온라인 대화 예절을 알리는 표어를 하나 짓고, 표어다운 세 가지(한 가지만 · 바로 알 수 있는 말 · 무엇을 하자는 것)에 맞는지 따져 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u5-C54","difficulty":4,"kind":"essay","stem":"온라인 대화 예절을 알리는 표어를 하나 짓고, 표어다운 세 가지(한 가지만 · 바로 알 수 있는 말 · 무엇을 하자는 것)에 맞는지 따져 쓰세요.","answer_guide":{"answer":"예: 「올리기 전에 한 번 더 확인해요」 — 사실 확인 한 가지만 담았고, 쉬운 말이라 바로 알 수 있으며, 확인하자는 것이 들어 있다.","scoring_points":["표어를 한 줄로 지었는가","세 가지 기준으로 하나씩 따졌는가","한쪽으로 치우친 말(아예 하지 말자)이 아닌가"]},"explanation":["한 줄로 지어요.","세 기준으로 따져요.","무엇을 하자?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_challenge#9','kor',4,2,'u5','L11','g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C57',4,'essay','teacher','매체 견주기 놀이에서 「편지」와 「영상 통화」 카드를 뽑았어요. 「얼마나 오래 남나요」에 두 매체를 견주어 대답하고, 이 놀이가 이기고 지는 놀이가 아닌 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u5-C57","difficulty":4,"kind":"essay","stem":"매체 견주기 놀이에서 「편지」와 「영상 통화」 카드를 뽑았어요. 「얼마나 오래 남나요」에 두 매체를 견주어 대답하고, 이 놀이가 이기고 지는 놀이가 아닌 까닭을 쓰세요.","answer_guide":{"answer":"예: 편지는 글로 남아 오래 간직할 수 있고, 영상 통화는 얼굴을 보며 말하지만 끝나면 남지 않는다. 대신 영상 통화는 떨어져 있어도 표정을 볼 수 있다. 매체마다 잘하는 일이 달라 상황에 맞게 고르는 것이라 이기고 지는 놀이가 아니다.","scoring_points":["두 매체를 같은 물음으로 견주었는가","한쪽이 모든 면에서 낫다고 하지 않았는가","매체마다 잘하는 일이 다르다는 까닭을 썼는가"]},"explanation":["같은 물음으로 견줘요.","잘하는 일이 달라요.","이기고 지는 놀이가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_L11_challenge#10','kor',4,2,'u5','L11','g4_2_kor_u5_L11_challenge','lesson_challenge','K4-2-u5-C58',4,'essay','teacher','「읽다」와 「읽고」가 다르게 소리 나는 까닭을 쓰고, 「굵다」와 「굵게」의 발음도 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u5-C58","difficulty":4,"kind":"essay","stem":"「읽다」와 「읽고」가 다르게 소리 나는 까닭을 쓰고, 「굵다」와 「굵게」의 발음도 함께 쓰세요.","answer_guide":{"answer":"예: ㄺ은 보통 [ㄱ]으로 소리 나서 읽다는 [익따]이지만, 뒤에 ㄱ이 오면 [ㄹ]로 소리 나서 읽고는 [일꼬]이다. 굵다는 [국따], 굵게는 [굴께]이다.","scoring_points":["ㄺ이 보통 [ㄱ]으로 소리 난다고 썼는가","뒤에 ㄱ이 오면 [ㄹ]로 소리 난다고 썼는가","굵다·굵게의 발음을 바르게 썼는가"]},"explanation":["받침은 그대로예요.","뒤 글자를 봐요.","ㄱ이 오면 [ㄹ]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#1','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C6',1,'mc','auto','이 단원을 마치며 다시 묻습니다. 마음을 전할 때 가장 먼저 생각할 것은 무엇인가요?',ARRAY['K4-2-u5-X07','K4-2-u5-X13','K4-2-u5-X08']::text[],false,'{"seq":1,"concept":"K4-2-u5-C6","difficulty":1,"kind":"mc","stem":"이 단원을 마치며 다시 묻습니다. 마음을 전할 때 가장 먼저 생각할 것은 무엇인가요?","options":[{"t":"상대가 지금 어떤 상황인지, 어떤 마음일지","correct":true},{"t":"가장 빠르게 전할 수 있는 방법","mis":"K4-2-u5-X07"},{"t":"되도록 온라인은 쓰지 않는 것","mis":"K4-2-u5-X13"},{"t":"내가 가장 하기 편한 방법","mis":"K4-2-u5-X08"}],"explanation":["처음에 물었던 물음이에요.","방법보다 먼저예요.","상대를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#2','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C9',1,'mc','auto','다음 가운데 온라인 대화가 아닌 것은 무엇인가요?',ARRAY['K4-2-u5-X09']::text[],false,'{"seq":2,"concept":"K4-2-u5-C9","difficulty":1,"kind":"mc","stem":"다음 가운데 온라인 대화가 아닌 것은 무엇인가요?","options":[{"t":"혼자 누리집에서 날씨 정보를 찾아 읽는다","correct":true},{"t":"학급 대화방에 준비물을 물어보는 글을 쓴다","mis":"K4-2-u5-X09"},{"t":"누리집 게시판의 글에 댓글을 단다","mis":"K4-2-u5-X09"},{"t":"영상 통화로 할아버지와 이야기한다","mis":"K4-2-u5-X09"}],"explanation":["상대와 말이 오가나요?","혼자 읽는 일은요?","그것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#3','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C21',1,'mc','auto','친구 사진을 학급 대화방에 올리고 싶을 때 먼저 할 일은 무엇인가요?',ARRAY['K4-2-u5-X20']::text[],false,'{"seq":3,"concept":"K4-2-u5-C21","difficulty":1,"kind":"mc","stem":"친구 사진을 학급 대화방에 올리고 싶을 때 먼저 할 일은 무엇인가요?","options":[{"t":"사진에 찍힌 친구에게 올려도 되는지 물어본다","correct":true},{"t":"다들 재미있어할 테니 바로 올린다","mis":"K4-2-u5-X20"},{"t":"찍힌 친구 몰래 올렸다가 나중에 말한다","mis":"K4-2-u5-X20"},{"t":"사진을 크게 만들어 올린다","mis":"K4-2-u5-X20"}],"explanation":["찍힌 사람이 있어요.","허락이 먼저예요.","먼저 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#4','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C30',1,'mc','auto','온라인에서 모르는 사람이 「만나서 같이 놀자」고 할 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X29','K4-2-u5-X30']::text[],false,'{"seq":4,"concept":"K4-2-u5-C30","difficulty":1,"kind":"mc","stem":"온라인에서 모르는 사람이 「만나서 같이 놀자」고 할 때 알맞은 것은 무엇인가요?","options":[{"t":"따르지 않고 어른께 바로 알린다","correct":true},{"t":"예의 있게 만날 곳을 정한다","mis":"K4-2-u5-X29"},{"t":"혼자 조용히 대화를 지우고 넘어간다","mis":"K4-2-u5-X30"},{"t":"친한 친구 한 명만 데리고 나간다","mis":"K4-2-u5-X29"}],"explanation":["모르는 사람이에요.","따르지 않아요.","어른께 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#5','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C38',1,'mc','auto','편지에서 안부를 묻고 날씨나 내 소식을 덧붙이는 부분은 무엇인가요?',ARRAY['K4-2-u5-X38','K4-2-u5-X39']::text[],false,'{"seq":5,"concept":"K4-2-u5-C38","difficulty":1,"kind":"mc","stem":"편지에서 안부를 묻고 날씨나 내 소식을 덧붙이는 부분은 무엇인가요?","options":[{"t":"첫인사","correct":true},{"t":"끝인사","mis":"K4-2-u5-X38"},{"t":"쓴 사람","mis":"K4-2-u5-X38"},{"t":"추신","mis":"K4-2-u5-X39"}],"explanation":["편지의 처음이에요.","안부를 물어요.","첫인사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#6','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C40',1,'mc','auto','웃어른께 쓰는 편지에서 이름 뒤에 붙이기 알맞은 말은 무엇인가요?',ARRAY['K4-2-u5-X40']::text[],false,'{"seq":6,"concept":"K4-2-u5-C40","difficulty":1,"kind":"mc","stem":"웃어른께 쓰는 편지에서 이름 뒤에 붙이기 알맞은 말은 무엇인가요?","options":[{"t":"올림","correct":true},{"t":"씀","mis":"K4-2-u5-X40"},{"t":"가","mis":"K4-2-u5-X40"},{"t":"에게","mis":"K4-2-u5-X40"}],"explanation":["웃어른께 쓰는 편지예요.","이름 뒤도 높여요.","‘올림’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#7','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C46',1,'mc','auto','내가 약속을 잊어 친구를 오래 기다리게 했어요. 전할 마음은 무엇인가요?',ARRAY['K4-2-u5-X46']::text[],false,'{"seq":7,"concept":"K4-2-u5-C46","difficulty":1,"kind":"mc","stem":"내가 약속을 잊어 친구를 오래 기다리게 했어요. 전할 마음은 무엇인가요?","options":[{"t":"사과","correct":true},{"t":"축하","mis":"K4-2-u5-X46"},{"t":"응원","mis":"K4-2-u5-X46"},{"t":"감사","mis":"K4-2-u5-X46"}],"explanation":["내가 잘못했어요.","미안한 마음이에요.","사과예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#8','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C58',1,'mc','auto','「늙고」는 어떻게 소리 나나요?',ARRAY['K4-2-u5-X58','K4-2-u5-X59']::text[],false,'{"seq":8,"concept":"K4-2-u5-C58","difficulty":1,"kind":"mc","stem":"「늙고」는 어떻게 소리 나나요?","options":[{"t":"[늘꼬]","correct":true},{"t":"[늑꼬]","mis":"K4-2-u5-X58"},{"t":"[늙꼬]","mis":"K4-2-u5-X59"},{"t":"[느꼬]","mis":"K4-2-u5-X58"}],"explanation":["ㄺ 뒤에 ㄱ이 와요.","[ㄹ]로 소리 나요.","[늘꼬]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#9','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C11',2,'mc','auto','「온라인 대화는 언제 들어가도 상관없다」는 말이 맞지 않는 예는 무엇인가요?',ARRAY['K4-2-u5-X11']::text[],false,'{"seq":9,"concept":"K4-2-u5-C11","difficulty":2,"kind":"mc","stem":"「온라인 대화는 언제 들어가도 상관없다」는 말이 맞지 않는 예는 무엇인가요?","options":[{"t":"정해진 같은 시간에 모두 들어와야 하는 영상 회의","correct":true},{"t":"아무 때나 글을 남기는 게시판","mis":"K4-2-u5-X11"},{"t":"밤에 읽어도 되는 전자 우편","mis":"K4-2-u5-X11"},{"t":"나중에 확인해도 되는 쪽지","mis":"K4-2-u5-X11"}],"explanation":["언제나 그런 것은 아니에요.","같은 시간에 모여야 하는 것은?","영상 회의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#10','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C18',2,'mc','auto','온라인에서 거친 말이 더 쉽게 나오는 까닭은 무엇인가요?',ARRAY['K4-2-u5-X18','K4-2-u5-X19','K4-2-u5-X16']::text[],false,'{"seq":10,"concept":"K4-2-u5-C18","difficulty":2,"kind":"mc","stem":"온라인에서 거친 말이 더 쉽게 나오는 까닭은 무엇인가요?","options":[{"t":"상대의 얼굴이 보이지 않고 내 이름이 드러나지 않을 때가 있어서","correct":true},{"t":"스마트폰 자체가 나쁜 물건이어서","mis":"K4-2-u5-X18"},{"t":"글자를 치는 것이 말보다 느려서","mis":"K4-2-u5-X19"},{"t":"대화방에 늘 사람이 많아서","mis":"K4-2-u5-X16"}],"explanation":["기기 탓이 아니에요.","얼굴과 이름이 안 보여요.","그래서 더 조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#11','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C26',2,'mc','auto','다음 가운데 온라인 대화를 고르는 편이 편리한 때는 언제인가요?',ARRAY['K4-2-u5-X26','K4-2-u5-X06']::text[],false,'{"seq":11,"concept":"K4-2-u5-C26","difficulty":2,"kind":"mc","stem":"다음 가운데 온라인 대화를 고르는 편이 편리한 때는 언제인가요?","options":[{"t":"여러 사람에게 한꺼번에 알려야 할 때","correct":true},{"t":"다툰 친구와 마음을 풀어야 할 때","mis":"K4-2-u5-X26"},{"t":"옆자리 짝에게 바로 물어볼 때","mis":"K4-2-u5-X06"},{"t":"얼굴을 보고 축하를 건네고 싶을 때","mis":"K4-2-u5-X06"}],"explanation":["한꺼번에 여럿에게","대화방이 잘하는 일이에요.","그때 편리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#12','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C33',2,'mc','auto','온라인 대화 점검표에서 「아니요」가 나왔어요. 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X31','K4-2-u5-X32']::text[],false,'{"seq":12,"concept":"K4-2-u5-C33","difficulty":2,"kind":"mc","stem":"온라인 대화 점검표에서 「아니요」가 나왔어요. 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"그 줄로 돌아가 어떻게 할지 다시 생각한다","correct":true},{"t":"「예」가 되도록 표시를 고쳐 둔다","mis":"K4-2-u5-X31"},{"t":"그 줄은 넘기고 다음 줄을 본다","mis":"K4-2-u5-X32"},{"t":"점검표를 버리고 새로 채운다","mis":"K4-2-u5-X31"}],"explanation":["「아니요」가 고칠 곳이에요.","넘기지 않아요.","그 줄로 돌아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#13','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C48',2,'mc','auto','「구체적으로 쓴 편지」로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X48','K4-2-u5-X49']::text[],false,'{"seq":13,"concept":"K4-2-u5-C48","difficulty":2,"kind":"mc","stem":"「구체적으로 쓴 편지」로 알맞은 것은 무엇인가요?","options":[{"t":"「지난주에 제 가방 끈을 고쳐 주셔서 고맙습니다.」","correct":true},{"t":"「아주아주 많이 정말정말 고맙습니다.」","mis":"K4-2-u5-X48"},{"t":"「그때 고마웠어요.」","mis":"K4-2-u5-X49"},{"t":"「고맙습니다. 고맙습니다. 고맙습니다.」","mis":"K4-2-u5-X48"}],"explanation":["무슨 일이었나요?","읽는 사람이 떠올릴 수 있게요.","있었던 일을 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#14','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C51',2,'mc','auto','편지봉투에서 보내는 사람의 주소와 이름은 어디에 쓰나요?',ARRAY['K4-2-u5-X50','K4-2-u5-X51']::text[],false,'{"seq":14,"concept":"K4-2-u5-C51","difficulty":2,"kind":"mc","stem":"편지봉투에서 보내는 사람의 주소와 이름은 어디에 쓰나요?","options":[{"t":"왼쪽 위","correct":true},{"t":"오른쪽 아래","mis":"K4-2-u5-X50"},{"t":"봉투 한가운데","mis":"K4-2-u5-X50"},{"t":"봉투 뒷면 아무 곳","mis":"K4-2-u5-X51"}],"explanation":["받는 사람은 오른쪽 아래예요.","보내는 사람은 그 반대쪽","왼쪽 위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#15','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C54',2,'mc','auto','표어다운 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X53','K4-2-u5-X54']::text[],false,'{"seq":15,"concept":"K4-2-u5-C54","difficulty":2,"kind":"mc","stem":"표어다운 것으로 알맞은 것은 무엇인가요?","options":[{"t":"「올리기 전에 한 번 더 확인해요」","correct":true},{"t":"「온라인 대화는 디지털 기기로 하는 대화이며 종류가 여럿입니다」","mis":"K4-2-u5-X53"},{"t":"「대화방을 아예 없앱시다」","mis":"K4-2-u5-X54"},{"t":"「확인하고 묻고 존중하고 줄인 말 안 쓰고 그림말 안 씁시다」","mis":"K4-2-u5-X53"}],"explanation":["한 줄 · 한 가지","바로 알 수 있게","무엇을 하자?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#16','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C60',2,'mc','auto','「지금 못 감.」을 알아듣고 서운하지 않게 다시 쓴 말은 무엇인가요?',ARRAY['K4-2-u5-X61','K4-2-u5-X34']::text[],false,'{"seq":16,"concept":"K4-2-u5-C60","difficulty":2,"kind":"mc","stem":"「지금 못 감.」을 알아듣고 서운하지 않게 다시 쓴 말은 무엇인가요?","options":[{"t":"「숙제를 마저 해야 해서 지금은 못 가. 끝나면 연락할게.」","correct":true},{"t":"「못 감. 끝.」","mis":"K4-2-u5-X61"},{"t":"(우는 그림말 하나만 보낸다)","mis":"K4-2-u5-X61"},{"t":"(대답 없이 대화방을 나간다)","mis":"K4-2-u5-X34"}],"explanation":["까닭을 밝혀요.","다음을 약속해요.","알아듣게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#17','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C14',3,'mc','auto','온라인 대화에 대해 가장 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u5-X13','K4-2-u5-X14']::text[],false,'{"seq":17,"concept":"K4-2-u5-C14","difficulty":3,"kind":"mc","stem":"온라인 대화에 대해 가장 알맞은 생각은 무엇인가요?","options":[{"t":"상황에 맞게 고르고, 예절을 지키며 쓴다","correct":true},{"t":"온라인 대화는 문제가 많으니 쓰지 않는 것이 가장 좋다","mis":"K4-2-u5-X13"},{"t":"편리하니까 만나서 하는 대화는 이제 필요 없다","mis":"K4-2-u5-X14"},{"t":"온라인에서는 무엇을 해도 괜찮다","mis":"K4-2-u5-X14"}],"explanation":["한쪽으로 치우치지 않아요.","상황에 맞게 골라요.","예절을 지키며 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#18','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C25',3,'mc','auto','모둠 토의에서 나온 의견 가운데 예절로 정하기에 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X24']::text[],false,'{"seq":18,"concept":"K4-2-u5-C25","difficulty":3,"kind":"mc","stem":"모둠 토의에서 나온 의견 가운데 예절로 정하기에 가장 알맞은 것은 무엇인가요?","options":[{"t":"「뜻을 모를 것 같은 말은 풀어서 쓰자」","correct":true},{"t":"「줄인 말을 쓰면 대화방에서 내보내자」","mis":"K4-2-u5-X24"},{"t":"「우리 모둠은 대화방을 아예 쓰지 말자」","mis":"K4-2-u5-X24"},{"t":"「좋은 말이니 모두에게 언제나 칭찬만 하자」","mis":"K4-2-u5-X24"}],"explanation":["지킬 수 있나요?","좋은 점이 더 큰가요?","모두 지킬 수 있는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#19','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C43',3,'mc','auto','「읽는 이를 생각하며」 쓴 편지에 대해 가장 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u5-X43','K4-2-u5-X44']::text[],false,'{"seq":19,"concept":"K4-2-u5-C43","difficulty":3,"kind":"mc","stem":"「읽는 이를 생각하며」 쓴 편지에 대해 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"전하려는 마음은 그대로 두고, 읽는 이의 상황을 살펴 표현을 골랐다","correct":true},{"t":"읽는 이가 좋아할 말만 골라 썼다","mis":"K4-2-u5-X43"},{"t":"읽는 이는 생각하지 않고 떠오르는 대로 썼다","mis":"K4-2-u5-X44"},{"t":"읽는 이가 슬퍼할까 봐 아무 말도 쓰지 않았다","mis":"K4-2-u5-X44"}],"explanation":["좋아할 말만도 아니에요.","내 마음대로도 아니에요.","마음은 그대로, 표현을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#20','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C42',3,'mc','auto','하준이가 먼저 쓴 쪽지에서 고쳐야 할 점이 아닌 것은 무엇인가요?',ARRAY['K4-2-u5-X42']::text[],false,'{"seq":20,"concept":"K4-2-u5-C42","difficulty":3,"kind":"mc","stem":"하준이가 먼저 쓴 쪽지에서 고쳐야 할 점이 아닌 것은 무엇인가요?","options":[{"t":"추신이 없다","correct":true},{"t":"웃어른께 쓰는데 높임 표현을 쓰지 않았다","mis":"K4-2-u5-X42"},{"t":"무엇이 고마운지 알 수 없다","mis":"K4-2-u5-X42"},{"t":"첫인사와 쓴 날짜가 없다","mis":"K4-2-u5-X42"}],"explanation":["추신은 필요할 때만이에요.","나머지는 모두 빠진 것이에요.","추신이 없는 것은 괜찮아요."],"asset":{"type":"passage","lines":["할머니에게","화분 고마워.","그럼 안녕.","하준 씀"],"title":"하준이가 먼저 쓴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#21','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C57',3,'mc','auto','「편지」와 「온라인 대화방」을 「얼마나 빨리 전해지나요」로 견준 대답으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X57','K4-2-u5-X35','K4-2-u5-X36']::text[],false,'{"seq":21,"concept":"K4-2-u5-C57","difficulty":3,"kind":"mc","stem":"「편지」와 「온라인 대화방」을 「얼마나 빨리 전해지나요」로 견준 대답으로 알맞은 것은 무엇인가요?","options":[{"t":"「온라인 대화방은 바로 닿고, 편지는 며칠이 걸릴 수 있어요.」","correct":true},{"t":"「온라인 대화방이 모든 면에서 이겨요.」","mis":"K4-2-u5-X57"},{"t":"「편지는 옛날 것이라 견줄 수 없어요.」","mis":"K4-2-u5-X35"},{"t":"「둘 다 똑같이 빨라요.」","mis":"K4-2-u5-X36"}],"explanation":["같은 물음으로 견줘요.","이기고 지기가 아니에요.","잘하는 일을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#22','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C56',3,'mc','auto','비밀 친구 편지에 둘만 겪은 특별한 일을 쓰지 않는 까닭은 무엇인가요?',ARRAY['K4-2-u5-X56','K4-2-u5-X53']::text[],false,'{"seq":22,"concept":"K4-2-u5-C56","difficulty":3,"kind":"mc","stem":"비밀 친구 편지에 둘만 겪은 특별한 일을 쓰지 않는 까닭은 무엇인가요?","options":[{"t":"내가 누구인지 드러나 활동의 재미가 사라지기 때문에","correct":true},{"t":"특별한 일은 편지에 쓰면 안 되는 내용이기 때문에","mis":"K4-2-u5-X56"},{"t":"비밀 친구 편지는 짧게만 써야 하기 때문에","mis":"K4-2-u5-X53"},{"t":"칭찬은 편지에 쓰면 안 되기 때문에","mis":"K4-2-u5-X56"}],"explanation":["마지막 날까지 비밀이에요.","둘만 아는 일은 들켜요.","그래서 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#23','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C6',4,'essay','teacher','1차시와 마지막 차시에 같은 물음 「마음을 전할 때 가장 먼저 생각할 것은?」이 나왔어요. 내 답을 쓰고, 그 답이 온라인 대화와 편지에 어떻게 쓰였는지 하나씩 예를 들어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u5-C6","difficulty":4,"kind":"essay","stem":"1차시와 마지막 차시에 같은 물음 「마음을 전할 때 가장 먼저 생각할 것은?」이 나왔어요. 내 답을 쓰고, 그 답이 온라인 대화와 편지에 어떻게 쓰였는지 하나씩 예를 들어 쓰세요.","answer_guide":{"answer":"예: 상대가 지금 어떤 상황인지, 어떤 마음일지를 먼저 생각한다. 온라인 대화에서는 상대가 알아듣지 못하면 풀어서 다시 말했고, 편지에서는 다리를 다친 친구의 처지를 살펴 신나게 논 이야기 대신 기다리는 마음을 썼다.","scoring_points":["상대의 상황과 마음을 먼저 생각한다고 썼는가","온라인 대화의 예를 들었는가","편지의 예를 들었는가"]},"explanation":["처음과 끝이 같은 물음이에요.","상대를 먼저 살펴요.","두 곳 모두 예를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#24','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C48',4,'essay','teacher','고마운 사람에게 쓰는 편지의 「가운데」를 써 보세요. 무슨 일이 있었는지 알 수 있게 쓰고, 읽는 이에 맞는 높임 표현을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u5-C48","difficulty":4,"kind":"essay","stem":"고마운 사람에게 쓰는 편지의 「가운데」를 써 보세요. 무슨 일이 있었는지 알 수 있게 쓰고, 읽는 이에 맞는 높임 표현을 쓰세요.","answer_guide":{"answer":"예: (경비 아저씨께) 「지난주 제가 열쇠를 잃어버려 현관 앞에 서 있을 때, 아저씨께서 엄마께 전화를 걸어 주셨지요. 그날 혼자 기다리지 않아도 되어서 마음이 놓였어요. 정말 고맙습니다.」","scoring_points":["무슨 일이 있었는지 알 수 있게 썼는가","그때의 마음을 썼는가","읽는 이에 맞게 높임 표현을 썼는가"]},"explanation":["무슨 일이었나요?","그때 마음은?","높임도 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_a#25','kor',4,2,'u5','','g4_2_kor_u5_review_a','unit_review','K4-2-u5-C20',4,'essay','teacher','하준이네 대화방(텃밭 물 당번)에서 민재가 지키지 않은 예절을 두 가지 찾아 쓰고, 민재가 다시 쓸 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u5-C20","difficulty":4,"kind":"essay","stem":"하준이네 대화방(텃밭 물 당번)에서 민재가 지키지 않은 예절을 두 가지 찾아 쓰고, 민재가 다시 쓸 말을 쓰세요.","answer_guide":{"answer":"예: 주제와 상관없는 그림말을 되풀이했고, 뜻을 알기 어렵게 줄인 말로 대답했다. 다시 쓴다면 「미안, 딴 이야기 했지? 나는 금요일에 물을 줄게.」라고 쓴다.","scoring_points":["주제와 상관없는 그림말을 찾았는가","뜻을 알기 어려운 줄인 말을 찾았는가","주제에 맞고 알아들을 수 있게 다시 썼는가"]},"explanation":["모인 까닭은 당번 정하기예요.","모두 알아듣게요.","주제에 맞게 다시 써요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"이번 주 텃밭 물 당번 순서 정하자."},{"who":"민재","text":"(주제와 상관없는 그림말만 계속 보냄)"},{"who":"서아","text":"민재야, 당번 순서 먼저 정하고 이야기하자."},{"who":"민재","text":"(뜻을 알기 어렵게 줄인 말로 대답함)"},{"who":"하준","text":"그럼 월요일은 내가 할게. 화요일은 누가 할래?"},{"who":"서아","text":"나는 수요일이 좋아. 민재는?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#1','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C6',1,'mc','auto','할머니께 안부를 전하려는 서아가 방법을 고르기 전에 먼저 할 일은 무엇인가요?',ARRAY['K4-2-u5-X07','K4-2-u5-X08','K4-2-u5-X05']::text[],false,'{"seq":1,"concept":"K4-2-u5-C6","difficulty":1,"kind":"mc","stem":"할머니께 안부를 전하려는 서아가 방법을 고르기 전에 먼저 할 일은 무엇인가요?","options":[{"t":"할머니께서 지금 어떤 상황이신지, 어떤 마음이실지 떠올린다","correct":true},{"t":"가장 빨리 닿는 방법부터 고른다","mis":"K4-2-u5-X07"},{"t":"서아가 가장 쓰기 편한 방법부터 고른다","mis":"K4-2-u5-X08"},{"t":"편지가 가장 좋은 방법이니 편지부터 쓴다","mis":"K4-2-u5-X05"}],"explanation":["방법은 그다음이에요.","할머니를 먼저 살펴요.","상황과 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#2','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C8',1,'mc','auto','한 사람에게 글을 보내는 온라인 대화는 무엇인가요?',ARRAY['K4-2-u5-X10']::text[],false,'{"seq":2,"concept":"K4-2-u5-C8","difficulty":1,"kind":"mc","stem":"한 사람에게 글을 보내는 온라인 대화는 무엇인가요?","options":[{"t":"쪽지나 전자 우편","correct":true},{"t":"영상 회의","mis":"K4-2-u5-X10"},{"t":"온라인 게시판","mis":"K4-2-u5-X10"},{"t":"여럿이 모인 대화방","mis":"K4-2-u5-X10"}],"explanation":["받는 사람이 한 명이에요.","글로 보내요.","쪽지 · 전자 우편이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#3','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C22',1,'mc','auto','새 대화방에 친구를 부르기 전에 할 일은 무엇인가요?',ARRAY['K4-2-u5-X21']::text[],false,'{"seq":3,"concept":"K4-2-u5-C22","difficulty":1,"kind":"mc","stem":"새 대화방에 친구를 부르기 전에 할 일은 무엇인가요?","options":[{"t":"들어올지 친구에게 먼저 물어본다","correct":true},{"t":"묻지 않고 바로 부른다","mis":"K4-2-u5-X21"},{"t":"나간 친구도 자꾸 다시 부른다","mis":"K4-2-u5-X21"},{"t":"친구의 친구까지 모두 부른다","mis":"K4-2-u5-X21"}],"explanation":["상대의 뜻이 있어요.","억지로 부르지 않아요.","먼저 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#4','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C30',1,'ox','auto','모르는 사람이 물어도 예의를 지켜 사는 곳은 알려 주어야 해요.',ARRAY['K4-2-u5-X29']::text[],false,'{"seq":4,"concept":"K4-2-u5-C30","difficulty":1,"kind":"ox","stem":"모르는 사람이 물어도 예의를 지켜 사는 곳은 알려 주어야 해요.","answer":"X","reason_options":[{"t":"모르는 사람에게는 이름·사는 곳·학교·사진을 알려 주지 않는 것이 나를 지키는 일이기 때문에","correct":true},{"t":"묻는 말에는 언제나 답해야 예절을 지킨 것이기 때문에","mis":"K4-2-u5-X29"}],"mis":"K4-2-u5-X29","explanation":["예절의 일이 아니에요.","나를 지키는 일이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
