INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#9','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C12',2,'mc','auto','화면이 사이에 있어도 직접 대화와 똑같이 필요한 것은 무엇인가요?',ARRAY['K4-2-u5-X10','K4-2-u5-X12']::text[],false,'{"seq":9,"concept":"K4-2-u5-C12","difficulty":2,"kind":"mc","stem":"화면이 사이에 있어도 직접 대화와 똑같이 필요한 것은 무엇인가요?","options":[{"t":"상대를 존중하고 주제에 맞는 말을 하는 것","correct":true},{"t":"같은 시간에 같은 곳에 있는 것","mis":"K4-2-u5-X10"},{"t":"디지털 기기를 들고 있는 것","mis":"K4-2-u5-X10"},{"t":"상대의 이름을 몰라도 되는 것","mis":"K4-2-u5-X12"}],"explanation":["화면 너머에도 사람이 있어요.","존중이 필요해요.","주제도 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
