INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#13','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C48',2,'mc','auto','편지를 「구체적으로」 쓴다는 것은 무엇인가요?',ARRAY['K4-2-u5-X48','K4-2-u5-X49']::text[],false,'{"seq":13,"concept":"K4-2-u5-C48","difficulty":2,"kind":"mc","stem":"편지를 「구체적으로」 쓴다는 것은 무엇인가요?","options":[{"t":"무슨 일이 있었는지 읽는 사람이 알 수 있게 쓰는 것","correct":true},{"t":"문장을 되도록 길게 늘이는 것","mis":"K4-2-u5-X48"},{"t":"「정말」을 여러 번 되풀이하는 것","mis":"K4-2-u5-X48"},{"t":"짧고 시원하게 한마디만 쓰는 것","mis":"K4-2-u5-X49"}],"explanation":["길이가 아니에요.","되풀이도 아니에요.","무슨 일인지 알 수 있게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#14','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C51',2,'mc','auto','웃어른께 보내는 봉투에서 받는 사람 이름 뒤에 쓰기 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X51']::text[],false,'{"seq":14,"concept":"K4-2-u5-C51","difficulty":2,"kind":"mc","stem":"웃어른께 보내는 봉투에서 받는 사람 이름 뒤에 쓰기 알맞은 것은 무엇인가요?","options":[{"t":"님께","correct":true},{"t":"앞","mis":"K4-2-u5-X51"},{"t":"에게","mis":"K4-2-u5-X51"},{"t":"씀","mis":"K4-2-u5-X51"}],"explanation":["받는 사람이 웃어른이에요.","「귀하」나 「님께」","‘님께’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#15','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C55',2,'mc','auto','우리 반 친구들에게만 오늘 한 번 알리기에 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u5-X55']::text[],false,'{"seq":15,"concept":"K4-2-u5-C55","difficulty":2,"kind":"mc","stem":"우리 반 친구들에게만 오늘 한 번 알리기에 알맞은 방법은 무엇인가요?","options":[{"t":"아침 시간에 교실에서 팻말을 들고 알린다","correct":true},{"t":"학교 방송으로 온 학교에 알린다","mis":"K4-2-u5-X55"},{"t":"학교 알림판에 한 달 동안 붙인다","mis":"K4-2-u5-X55"},{"t":"내 공책에만 적어 둔다","mis":"K4-2-u5-X55"}],"explanation":["누구에게? — 우리 반","언제? — 오늘","교실에서 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#16','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C32',2,'mc','auto','내가 쓴 말을 할머니께서 알아듣지 못하셨어요. 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X22','K4-2-u5-X61']::text[],false,'{"seq":16,"concept":"K4-2-u5-C32","difficulty":2,"kind":"mc","stem":"내가 쓴 말을 할머니께서 알아듣지 못하셨어요. 알맞은 것은 무엇인가요?","options":[{"t":"할머니께서 아시는 말로 풀어서 다시 말씀드린다","correct":true},{"t":"같은 말을 한 번 더 보낸다","mis":"K4-2-u5-X22"},{"t":"「그것도 모르세요?」라고 보낸다","mis":"K4-2-u5-X22"},{"t":"그림말만 보내고 대화를 끝낸다","mis":"K4-2-u5-X61"}],"explanation":["못 알아들은 건 상대 잘못이 아니에요.","풀어서 말해요.","높임도 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#17','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C19',3,'error','auto','이 단원을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u5-X13','K4-2-u5-X14']::text[],false,'{"seq":17,"concept":"K4-2-u5-C19","difficulty":3,"kind":"error","stem":"이 단원을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「문제 상황을 많이 보았으니 온라인 대화는 나쁜 거야.」","correct":true,"mis_target":"K4-2-u5-X13"},{"t":"친구 나 — 「멀리 이사 간 친구와는 온라인 대화가 큰 힘이 돼.」","mis":"K4-2-u5-X13"},{"t":"친구 다 — 「우리가 배운 건 온라인 대화를 잘 쓰는 법이야.」","mis":"K4-2-u5-X14"}],"explanation":["문제 상황을 보았어도요.","알맞은 때가 있어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#18','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C25',3,'mc','auto','「밤 열 시가 넘으면 대화방에 글을 쓰지 말자」를 따질 때 알맞은 물음은 무엇인가요?',ARRAY['K4-2-u5-X24','K4-2-u5-X15']::text[],false,'{"seq":18,"concept":"K4-2-u5-C25","difficulty":3,"kind":"mc","stem":"「밤 열 시가 넘으면 대화방에 글을 쓰지 말자」를 따질 때 알맞은 물음은 무엇인가요?","options":[{"t":"「모두 실제로 지킬 수 있고, 좋은 점이 불편한 점보다 큰가?」","correct":true},{"t":"「말이 멋있게 들리는가?」","mis":"K4-2-u5-X24"},{"t":"「가장 엄격한 의견인가?」","mis":"K4-2-u5-X24"},{"t":"「내가 낸 의견인가?」","mis":"K4-2-u5-X15"}],"explanation":["두 가지 기준이 있어요.","할 수 있나요?","좋은 점이 더 큰가요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#19','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C49',3,'mc','auto','시험을 망쳐 속상한 사촌 언니에게 쓰는 편지로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X44','K4-2-u5-X43']::text[],false,'{"seq":19,"concept":"K4-2-u5-C49","difficulty":3,"kind":"mc","stem":"시험을 망쳐 속상한 사촌 언니에게 쓰는 편지로 알맞은 것은 무엇인가요?","options":[{"t":"「많이 속상했지? 언니가 밤늦게까지 공부하던 거 나는 알아.」","correct":true},{"t":"「나는 이번 시험에서 다 맞았어!」","mis":"K4-2-u5-X44"},{"t":"「시험이 별것 아니니 속상해하지 마.」","mis":"K4-2-u5-X44"},{"t":"「언니는 언제나 최고야. 시험은 언니 잘못이 아니야.」","mis":"K4-2-u5-X43"}],"explanation":["언니의 처지를 살펴요.","솔직한 마음도 담아요.","언니가 한 일을 알아줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#20','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C42',3,'mc','auto','하준이의 쪽지와 편지를 견주었을 때, 편지에서 새로 채운 것이 아닌 것은 무엇인가요?',ARRAY['K4-2-u5-X42']::text[],false,'{"seq":20,"concept":"K4-2-u5-C42","difficulty":3,"kind":"mc","stem":"하준이의 쪽지와 편지를 견주었을 때, 편지에서 새로 채운 것이 아닌 것은 무엇인가요?","options":[{"t":"글씨 크기","correct":true},{"t":"높임 표현","mis":"K4-2-u5-X42"},{"t":"있었던 일","mis":"K4-2-u5-X42"},{"t":"첫인사와 끝인사","mis":"K4-2-u5-X42"}],"explanation":["높임을 맞췄어요.","있었던 일을 밝혔어요.","인사를 채웠어요."],"asset":{"type":"passage","lines":["옆집 할머니께","할머니, 안녕하세요? 비가 그치고 나니 날이 많이 선선해졌어요.","지난주 장맛비가 쏟아지던 날, 저희 가족은 모두 집을 비웠지요.","할머니께서 대문 앞 화분들을 처마 밑으로 옮겨 주셨다고 들었어요.","제가 아끼던 고추 모종이 하나도 쓰러지지 않았어요. 정말 고맙습니다.","고추가 열리면 제일 먼저 가져다 드릴게요. 건강하세요.","20○○년 ○○월 ○○일","하준 올림"],"title":"하준이가 옆집 할머니께 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#21','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C57',3,'mc','auto','「영상 통화」와 「게시판」을 「한 번에 몇 사람에게 닿나요」로 견준 대답으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X57','K4-2-u5-X13','K4-2-u5-X10']::text[],false,'{"seq":21,"concept":"K4-2-u5-C57","difficulty":3,"kind":"mc","stem":"「영상 통화」와 「게시판」을 「한 번에 몇 사람에게 닿나요」로 견준 대답으로 알맞은 것은 무엇인가요?","options":[{"t":"「게시판은 여러 사람이 볼 수 있고, 영상 통화는 함께 들어온 사람과만 이야기해요.」","correct":true},{"t":"「영상 통화가 게시판보다 모든 면에서 좋아요.」","mis":"K4-2-u5-X57"},{"t":"「게시판은 위험하니 쓰지 말아야 해요.」","mis":"K4-2-u5-X13"},{"t":"「영상 통화는 아무에게나 닿아요.」","mis":"K4-2-u5-X10"}],"explanation":["닿는 사람 수를 견줘요.","잘하는 일이 달라요.","이기는 쪽은 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#22','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C45',3,'mc','auto','다음 가운데 편지 글감으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X45']::text[],false,'{"seq":22,"concept":"K4-2-u5-C45","difficulty":3,"kind":"mc","stem":"다음 가운데 편지 글감으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"이사 가시는 아랫집 어른께서 그동안 동생을 돌봐 주신 일","correct":true},{"t":"오늘 점심 반찬이 입에 맞았던 일","mis":"K4-2-u5-X45"},{"t":"내일 비가 오지 않았으면 하는 바람","mis":"K4-2-u5-X45"},{"t":"혼자 만화책을 끝까지 읽은 일","mis":"K4-2-u5-X45"}],"explanation":["그 사람과 나 사이의 일인가요?","마음이 오간 일이에요.","돌봐 주신 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#23','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C1',4,'essay','teacher','이 단원에서 배운 두 가지(온라인 대화 예절 · 편지 쓰기)가 어떤 점에서 같은지 쓰고, 이번 주에 한 사람에게 마음을 전한다면 어떤 방법을 고를지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u5-C1","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 두 가지(온라인 대화 예절 · 편지 쓰기)가 어떤 점에서 같은지 쓰고, 이번 주에 한 사람에게 마음을 전한다면 어떤 방법을 고를지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 둘 다 화면 너머와 종이 너머에 있는 사람을 먼저 살피는 일이다. 이번 주에 멀리 사는 할머니께 안부를 전하고 싶은데, 할머니께서 오래 간직하실 수 있도록 편지를 써서 보내겠다.","scoring_points":["두 가지의 같은 점(상대를 살핌)을 썼는가","마음을 전할 사람과 방법을 골랐는가","상대의 상황에 맞춘 까닭을 썼는가"]},"explanation":["둘 다 상대를 살펴요.","한 사람을 정해요.","알맞은 방법을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#24','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C42',4,'essay','teacher','하준이가 먼저 쓴 쪽지를 편지의 짜임과 높임에 맞게 고쳐 쓰세요(받는 사람 · 첫인사 · 전하고 싶은 말 · 끝인사 · 쓴 날짜 · 쓴 사람).','{}'::text[],false,'{"seq":24,"concept":"K4-2-u5-C42","difficulty":4,"kind":"essay","stem":"하준이가 먼저 쓴 쪽지를 편지의 짜임과 높임에 맞게 고쳐 쓰세요(받는 사람 · 첫인사 · 전하고 싶은 말 · 끝인사 · 쓴 날짜 · 쓴 사람).","answer_guide":{"answer":"예: 옆집 할머니께 / 할머니, 안녕하세요? 날이 많이 선선해졌어요. / 장맛비가 쏟아지던 날 화분을 처마 밑으로 옮겨 주셔서 고추 모종이 하나도 쓰러지지 않았어요. 정말 고맙습니다. / 건강하세요. / 20○○년 ○○월 ○○일 / 하준 올림","scoring_points":["짜임 여섯 가지를 모두 갖추었는가","높임 표현을 세 곳(부르는 말·문장 끝·이름 뒤)에 맞추었는가","무엇이 고마운지 있었던 일을 밝혔는가"]},"explanation":["짜임을 하나씩 채워요.","세 곳을 높여요.","있었던 일을 밝혀요."],"asset":{"type":"passage","lines":["할머니에게","화분 고마워.","그럼 안녕.","하준 씀"],"title":"하준이가 먼저 쓴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_b#25','kor',4,2,'u5','','g4_2_kor_u5_review_b','unit_review','K4-2-u5-C29',4,'essay','teacher','같은 내용 「내일 모임이 몇 시인지 알려 줘.」를 친구에게 보낼 때와 이웃 어른께 보낼 때로 나누어 쓰고, 다르게 쓴 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u5-C29","difficulty":4,"kind":"essay","stem":"같은 내용 「내일 모임이 몇 시인지 알려 줘.」를 친구에게 보낼 때와 이웃 어른께 보낼 때로 나누어 쓰고, 다르게 쓴 까닭을 쓰세요.","answer_guide":{"answer":"예: 친구에게 — 「내일 모임 몇 시인지 알려 줘.」 / 이웃 어른께 — 「안녕하세요. 내일 모임이 몇 시인지 알려 주시겠어요?」 같은 내용이라도 받는 사람이 웃어른이면 화면에서도 높임 표현을 쓰기 때문이다.","scoring_points":["친구에게 보낼 말을 썼는가","이웃 어른께 보낼 말을 높임 표현으로 썼는가","받는 사람에 따라 달라진다는 까닭을 썼는가"]},"explanation":["누구에게 보내나요?","화면에서도 높여요.","상대에 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#1','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C6',1,'ox','auto','마음을 전할 때는 내가 가장 편한 방법부터 고르면 돼요.',ARRAY['K4-2-u5-X08']::text[],false,'{"seq":1,"concept":"K4-2-u5-C6","difficulty":1,"kind":"ox","stem":"마음을 전할 때는 내가 가장 편한 방법부터 고르면 돼요.","answer":"X","reason_options":[{"t":"방법을 고르기 전에 상대의 상황과 마음을 먼저 살펴야 하기 때문에","correct":true},{"t":"내가 편해야 마음도 잘 전해지기 때문에","mis":"K4-2-u5-X08"}],"mis":"K4-2-u5-X08","explanation":["내가 편한 것보다요.","상대가 먼저예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#2','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C7',1,'mc','auto','온라인 대화를 하려면 꼭 있어야 하는 것은 무엇인가요?',ARRAY['K4-2-u5-X10','K4-2-u5-X11']::text[],false,'{"seq":2,"concept":"K4-2-u5-C7","difficulty":1,"kind":"mc","stem":"온라인 대화를 하려면 꼭 있어야 하는 것은 무엇인가요?","options":[{"t":"디지털 기기","correct":true},{"t":"편지지와 우표","mis":"K4-2-u5-X10"},{"t":"같은 교실","mis":"K4-2-u5-X10"},{"t":"같은 시각","mis":"K4-2-u5-X11"}],"explanation":["인터넷이나 스마트폰","기기가 있어야 해요.","디지털 기기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#3','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C17',1,'ox','auto','「아마 맞을걸」이라고 들은 이야기는 게시판에 올려도 돼요.',ARRAY['K4-2-u5-X17']::text[],false,'{"seq":3,"concept":"K4-2-u5-C17","difficulty":1,"kind":"ox","stem":"「아마 맞을걸」이라고 들은 이야기는 게시판에 올려도 돼요.","answer":"X","reason_options":[{"t":"확인하지 않은 이야기를 여러 사람이 읽는 곳에 쓰면 그 글에 나온 사람이 다칠 수 있기 때문에","correct":true},{"t":"아마 맞을 이야기는 사실과 같기 때문에","mis":"K4-2-u5-X17"}],"mis":"K4-2-u5-X17","explanation":["「아마」는 확인이 아니에요.","여러 사람이 읽어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#4','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C30',1,'mc','auto','모르는 사람에게 알려 주어도 괜찮은 것은 무엇인가요?',ARRAY['K4-2-u5-X29']::text[],false,'{"seq":4,"concept":"K4-2-u5-C30","difficulty":1,"kind":"mc","stem":"모르는 사람에게 알려 주어도 괜찮은 것은 무엇인가요?","options":[{"t":"아무것도 알려 주지 않고 어른께 먼저 보여 드린다","correct":true},{"t":"학교 이름","mis":"K4-2-u5-X29"},{"t":"내 사진","mis":"K4-2-u5-X29"},{"t":"사는 동네","mis":"K4-2-u5-X29"}],"explanation":["이름 · 사는 곳 · 학교 · 사진","모두 알려 주지 않아요.","어른께 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#5','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C38',1,'mc','auto','하준이의 편지에서 「옆집 할머니께」는 무엇에 해당하나요?',ARRAY['K4-2-u5-X38','K4-2-u5-X39']::text[],false,'{"seq":5,"concept":"K4-2-u5-C38","difficulty":1,"kind":"mc","stem":"하준이의 편지에서 「옆집 할머니께」는 무엇에 해당하나요?","options":[{"t":"받는 사람","correct":true},{"t":"쓴 사람","mis":"K4-2-u5-X38"},{"t":"끝인사","mis":"K4-2-u5-X38"},{"t":"추신","mis":"K4-2-u5-X39"}],"explanation":["맨 처음에 있어요.","누구에게 쓰나요?","받는 사람이에요."],"asset":{"type":"passage","lines":["옆집 할머니께","할머니, 안녕하세요? 비가 그치고 나니 날이 많이 선선해졌어요.","지난주 장맛비가 쏟아지던 날, 저희 가족은 모두 집을 비웠지요.","할머니께서 대문 앞 화분들을 처마 밑으로 옮겨 주셨다고 들었어요.","제가 아끼던 고추 모종이 하나도 쓰러지지 않았어요. 정말 고맙습니다.","고추가 열리면 제일 먼저 가져다 드릴게요. 건강하세요.","20○○년 ○○월 ○○일","하준 올림"],"title":"하준이가 옆집 할머니께 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#6','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C29',1,'mc','auto','선생님께 온라인으로 보낼 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X28']::text[],false,'{"seq":6,"concept":"K4-2-u5-C29","difficulty":1,"kind":"mc","stem":"선생님께 온라인으로 보낼 말로 알맞은 것은 무엇인가요?","options":[{"t":"「숙제 파일 보내 드렸습니다. 확인해 주시겠어요?」","correct":true},{"t":"「숙제 파일 보냄. 확인.」","mis":"K4-2-u5-X28"},{"t":"「숙제 파일 보냈어. 빨리 봐.」","mis":"K4-2-u5-X28"},{"t":"「숙제. 파일.」","mis":"K4-2-u5-X28"}],"explanation":["받는 사람이 웃어른이에요.","화면에서도 높여요.","문장 끝까지 높여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#7','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C46',1,'mc','auto','내가 아픈 날 짝이 도서 도우미 일을 대신해 주었어요. 짝에게 전할 마음은 무엇인가요?',ARRAY['K4-2-u5-X46']::text[],false,'{"seq":7,"concept":"K4-2-u5-C46","difficulty":1,"kind":"mc","stem":"내가 아픈 날 짝이 도서 도우미 일을 대신해 주었어요. 짝에게 전할 마음은 무엇인가요?","options":[{"t":"감사","correct":true},{"t":"사과","mis":"K4-2-u5-X46"},{"t":"위로","mis":"K4-2-u5-X46"},{"t":"축하","mis":"K4-2-u5-X46"}],"explanation":["도움을 받았어요.","고마운 마음이에요.","감사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#8','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C59',1,'mc','auto','「짧다」는 어떻게 소리 나나요?',ARRAY['K4-2-u5-X60','K4-2-u5-X59']::text[],false,'{"seq":8,"concept":"K4-2-u5-C59","difficulty":1,"kind":"mc","stem":"「짧다」는 어떻게 소리 나나요?","options":[{"t":"[짤따]","correct":true},{"t":"[짭따]","mis":"K4-2-u5-X60"},{"t":"[짧따]","mis":"K4-2-u5-X59"},{"t":"[자따]","mis":"K4-2-u5-X60"}],"explanation":["ㄼ은 보통 [ㄹ]이에요.","밟-이 아니에요.","[짤따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#9','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C11',2,'ox','auto','온라인 대화에서는 언제나 상대가 누구인지 알 수 없어요.',ARRAY['K4-2-u5-X11']::text[],false,'{"seq":9,"concept":"K4-2-u5-C11","difficulty":2,"kind":"ox","stem":"온라인 대화에서는 언제나 상대가 누구인지 알 수 없어요.","answer":"X","reason_options":[{"t":"우리 반 대화방처럼 누가 말하는지 모두 아는 온라인 대화도 있기 때문에","correct":true},{"t":"온라인에서는 누구나 이름을 숨기기 때문에","mis":"K4-2-u5-X11"}],"mis":"K4-2-u5-X11","explanation":["대체로 그런 성질이에요.","반 대화방은 알아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#10','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C17',2,'mc','auto','확인하지 않은 이야기를 학년 게시판에 쓰면 생기는 일은 무엇인가요?',ARRAY['K4-2-u5-X17','K4-2-u5-X20']::text[],false,'{"seq":10,"concept":"K4-2-u5-C17","difficulty":2,"kind":"mc","stem":"확인하지 않은 이야기를 학년 게시판에 쓰면 생기는 일은 무엇인가요?","options":[{"t":"그 글에 나온 사람이 크게 다칠 수 있다","correct":true},{"t":"글이 짧아서 아무도 읽지 않는다","mis":"K4-2-u5-X17"},{"t":"여러 사람이 읽으니 저절로 사실이 된다","mis":"K4-2-u5-X17"},{"t":"게시판이 더 재미있어진다","mis":"K4-2-u5-X20"}],"explanation":["여러 사람이 읽어요.","확인하지 않았어요.","한 사람이 다칠 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#11','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C27',2,'ox','auto','온라인 대화는 편리하니 이제 만나서 하는 대화는 필요 없어요.',ARRAY['K4-2-u5-X14']::text[],false,'{"seq":11,"concept":"K4-2-u5-C27","difficulty":2,"kind":"ox","stem":"온라인 대화는 편리하니 이제 만나서 하는 대화는 필요 없어요.","answer":"X","reason_options":[{"t":"마음을 푸는 일처럼 직접 만나서 하는 편이 더 잘 전해지는 때가 있기 때문에","correct":true},{"t":"온라인 대화가 모든 면에서 더 편하기 때문에","mis":"K4-2-u5-X14"}],"mis":"K4-2-u5-X14","explanation":["언제나 편하지는 않아요.","직접 만나는 편이 나을 때가 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#12','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C50',2,'ox','auto','편지 점검표의 칸이 모두 「예」면 다시 읽어 볼 필요가 없어요.',ARRAY['K4-2-u5-X31']::text[],false,'{"seq":12,"concept":"K4-2-u5-C50","difficulty":2,"kind":"ox","stem":"편지 점검표의 칸이 모두 「예」면 다시 읽어 볼 필요가 없어요.","answer":"X","reason_options":[{"t":"소리 내어 다시 읽으면 쓸 때 안 보이던 곳이 보이고, 점검표도 고칠 곳을 찾으려고 채우는 것이기 때문에","correct":true},{"t":"「예」가 다 나오면 잘 쓴 것이 확실하기 때문에","mis":"K4-2-u5-X31"}],"mis":"K4-2-u5-X31","explanation":["소리 내어 읽어요.","안 보이던 곳이 보여요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#13','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C48',2,'ox','auto','「정말정말 아주아주 고마워」처럼 쓰면 고마운 마음이 구체적으로 전해져요.',ARRAY['K4-2-u5-X48']::text[],false,'{"seq":13,"concept":"K4-2-u5-C48","difficulty":2,"kind":"ox","stem":"「정말정말 아주아주 고마워」처럼 쓰면 고마운 마음이 구체적으로 전해져요.","answer":"X","reason_options":[{"t":"강조하는 말을 되풀이해도 무엇이 고마운지는 알 수 없기 때문에","correct":true},{"t":"강조하는 말이 많을수록 마음이 크게 전해지기 때문에","mis":"K4-2-u5-X48"}],"mis":"K4-2-u5-X48","explanation":["되풀이는 길게 만들 뿐이에요.","무엇이 고마운가요?","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#14','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C51',2,'mc','auto','편지봉투에 우편 번호를 쓰는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X51']::text[],false,'{"seq":14,"concept":"K4-2-u5-C51","difficulty":2,"kind":"mc","stem":"편지봉투에 우편 번호를 쓰는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"다섯 자리를 정확하게 쓴다","correct":true},{"t":"기억나는 숫자만 쓴다","mis":"K4-2-u5-X51"},{"t":"세 자리만 써도 된다","mis":"K4-2-u5-X51"},{"t":"보내는 사람 것만 쓴다","mis":"K4-2-u5-X51"}],"explanation":["우편 번호는 다섯 자리예요.","정확하게 써요.","빠짐없이요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#15','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C54',2,'ox','auto','표어는 무엇을 하자는 것인지 바로 알 수 있게 짧게 써요.',ARRAY['K4-2-u5-X53']::text[],false,'{"seq":15,"concept":"K4-2-u5-C54","difficulty":2,"kind":"ox","stem":"표어는 무엇을 하자는 것인지 바로 알 수 있게 짧게 써요.","answer":"O","reason_options":[{"t":"표어는 짧은 한 줄로 지나가는 사람의 마음에 남기는 글이기 때문에","correct":true},{"t":"표어는 길게 설명할수록 잘 알려지기 때문에","mis":"K4-2-u5-X53"}],"mis":"K4-2-u5-X53","explanation":["한 줄로 써요.","한 가지만요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#16','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C23',2,'mc','auto','친구들이 모두 아는 줄인 말이라도 다시 생각해야 하는 까닭은 무엇인가요?',ARRAY['K4-2-u5-X22','K4-2-u5-X61']::text[],false,'{"seq":16,"concept":"K4-2-u5-C23","difficulty":2,"kind":"mc","stem":"친구들이 모두 아는 줄인 말이라도 다시 생각해야 하는 까닭은 무엇인가요?","options":[{"t":"그 말을 모르는 사람은 대화에서 밀려날 수 있기 때문에","correct":true},{"t":"줄인 말은 쓰면 무조건 벌을 받기 때문에","mis":"K4-2-u5-X22"},{"t":"줄인 말을 쓰면 대화가 저절로 빨라지기 때문에","mis":"K4-2-u5-X61"},{"t":"모르는 사람이 잘못한 것이기 때문에","mis":"K4-2-u5-X22"}],"explanation":["모르는 사람이 있을 수 있어요.","그 사람은 밀려나요.","알아듣게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#17','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C4',3,'mc','auto','「더 좋은 방법은 없고 상황에 알맞은 방법이 있을 뿐이다」에 맞는 생각은 무엇인가요?',ARRAY['K4-2-u5-X05','K4-2-u5-X07']::text[],false,'{"seq":17,"concept":"K4-2-u5-C4","difficulty":3,"kind":"mc","stem":"「더 좋은 방법은 없고 상황에 알맞은 방법이 있을 뿐이다」에 맞는 생각은 무엇인가요?","options":[{"t":"오래 간직할 마음은 편지로, 멀리 있는 친척 안부는 영상 대화로","correct":true},{"t":"언제나 편지로","mis":"K4-2-u5-X05"},{"t":"언제나 온라인 대화로","mis":"K4-2-u5-X05"},{"t":"그때그때 가장 빠른 것으로","mis":"K4-2-u5-X07"}],"explanation":["상황이 달라요.","방법도 달라요.","알맞은 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#18','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C25',3,'ox','auto','「좋은 말 같으니까」라는 까닭만으로 우리 반 예절을 정해도 돼요.',ARRAY['K4-2-u5-X24']::text[],false,'{"seq":18,"concept":"K4-2-u5-C25","difficulty":3,"kind":"ox","stem":"「좋은 말 같으니까」라는 까닭만으로 우리 반 예절을 정해도 돼요.","answer":"X","reason_options":[{"t":"실제로 지킬 수 있는지, 좋은 점이 불편한 점보다 큰지 따져야 하기 때문에","correct":true},{"t":"좋은 말은 모두 지켜지기 때문에","mis":"K4-2-u5-X24"}],"mis":"K4-2-u5-X24","explanation":["좋은 말만으로는 안 돼요.","지킬 수 있어야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#19','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C43',3,'ox','auto','읽는 이를 생각하려면 내 솔직한 마음은 감추고 상대가 좋아할 말만 써야 해요.',ARRAY['K4-2-u5-X43']::text[],false,'{"seq":19,"concept":"K4-2-u5-C43","difficulty":3,"kind":"ox","stem":"읽는 이를 생각하려면 내 솔직한 마음은 감추고 상대가 좋아할 말만 써야 해요.","answer":"X","reason_options":[{"t":"전하려는 마음은 그대로 두고 상대의 상황을 살펴 표현을 고르는 것이기 때문에","correct":true},{"t":"상대가 좋아하는 말이 언제나 가장 좋은 편지이기 때문에","mis":"K4-2-u5-X43"}],"mis":"K4-2-u5-X43","explanation":["솔직함과 배려는 함께예요.","마음은 그대로예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#20','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C40',3,'mc','auto','「큰이모께 … 진짜 고마워 … 유담 씀」을 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u5-X40']::text[],false,'{"seq":20,"concept":"K4-2-u5-C40","difficulty":3,"kind":"mc","stem":"「큰이모께 … 진짜 고마워 … 유담 씀」을 바르게 고친 것은 무엇인가요?","options":[{"t":"「큰이모께 … 정말 고맙습니다 … 유담 올림」","correct":true},{"t":"「큰이모에게 … 정말 고맙습니다 … 유담 올림」","mis":"K4-2-u5-X40"},{"t":"「큰이모께 … 정말 고맙습니다 … 유담 씀」","mis":"K4-2-u5-X40"},{"t":"「큰이모께 … 진짜 고마워 … 유담 올림」","mis":"K4-2-u5-X40"}],"explanation":["부르는 말은 맞았어요.","문장 끝과 이름 뒤를 봐요.","세 곳 모두 높여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#21','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C57',3,'error','auto','매체 견주기 놀이를 마치고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u5-X57','K4-2-u5-X05']::text[],false,'{"seq":21,"concept":"K4-2-u5-C57","difficulty":3,"kind":"error","stem":"매체 견주기 놀이를 마치고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「결국 영상 통화가 가장 좋은 매체야.」","correct":true,"mis_target":"K4-2-u5-X57"},{"t":"친구 가 — 「편지는 오래 남고, 대화방은 빨라.」","mis":"K4-2-u5-X57"},{"t":"친구 나 — 「상황에 따라 알맞은 매체가 달라.」","mis":"K4-2-u5-X05"}],"explanation":["가장 좋은 매체는 없어요.","잘하는 일이 달라요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#22','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C44',3,'match','auto','하준이의 편지 계획을 알맞은 칸에 이으세요.','{}'::text[],false,'{"seq":22,"concept":"K4-2-u5-C44","difficulty":3,"kind":"match","stem":"하준이의 편지 계획을 알맞은 칸에 이으세요.","pairs":[{"l":"마음을 전할 사람","r":"옆집 할머니"},{"l":"있었던 일","r":"장맛비에 화분을 옮겨 주신 일"},{"l":"전하고 싶은 마음","r":"고마움"}],"mis":"K4-2-u5-X27","explanation":["누구에게?","무슨 일이?","어떤 마음?"],"asset":{"type":"passage","lines":["옆집 할머니께","할머니, 안녕하세요? 비가 그치고 나니 날이 많이 선선해졌어요.","지난주 장맛비가 쏟아지던 날, 저희 가족은 모두 집을 비웠지요.","할머니께서 대문 앞 화분들을 처마 밑으로 옮겨 주셨다고 들었어요.","제가 아끼던 고추 모종이 하나도 쓰러지지 않았어요. 정말 고맙습니다.","고추가 열리면 제일 먼저 가져다 드릴게요. 건강하세요.","20○○년 ○○월 ○○일","하준 올림"],"title":"하준이가 옆집 할머니께 쓴 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#23','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C4',4,'essay','teacher','「온라인 대화는 나쁘다」는 친구와 「이제 편지는 필요 없다」는 친구에게 각각 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u5-C4","difficulty":4,"kind":"essay","stem":"「온라인 대화는 나쁘다」는 친구와 「이제 편지는 필요 없다」는 친구에게 각각 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 첫째 친구에게는 「멀리 이사 간 친구와 소식을 나눌 때처럼 온라인 대화가 큰 힘이 될 때가 있어. 예절을 지키며 잘 쓰면 돼.」라고 말한다. 둘째 친구에게는 「편지는 천천히 정성을 담아 오래 남길 수 있어. 상황에 따라 알맞은 방법이 다를 뿐이야.」라고 말한다.","scoring_points":["첫째 친구에게 온라인 대화가 알맞은 때를 들어 말했는가","둘째 친구에게 편지가 잘하는 일을 들어 말했는가","「상황에 알맞은 방법」이라는 생각이 드러나는가"]},"explanation":["양쪽 모두 치우쳤어요.","잘하는 일이 달라요.","상황에 알맞게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#24','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C46',4,'essay','teacher','마음의 다섯 갈래(감사 · 사과 · 축하 · 위로 · 응원) 가운데 하나를 골라, 그 마음이 어울리는 상황을 쓰고 그 사람에게 전할 한두 문장을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u5-C46","difficulty":4,"kind":"essay","stem":"마음의 다섯 갈래(감사 · 사과 · 축하 · 위로 · 응원) 가운데 하나를 골라, 그 마음이 어울리는 상황을 쓰고 그 사람에게 전할 한두 문장을 쓰세요.","answer_guide":{"answer":"예: 응원 — 다음 주에 피아노 발표회에 나가는 짝. 「연습실에서 날마다 남아 연습하던 너를 봤어. 발표회 날 떨리더라도 네 소리를 믿어!」","scoring_points":["마음의 갈래를 하나 골랐는가","그 마음에 어울리는 상황을 썼는가","상황이 드러나게 전할 말을 썼는가"]},"explanation":["어떤 마음인가요?","상대의 처지를 봐요.","있었던 일을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_c#25','kor',4,2,'u5','','g4_2_kor_u5_review_c','unit_review','K4-2-u5-C30',4,'essay','teacher','모르는 사람에게서 「사진 보내 주면 선물 줄게.」라는 쪽지를 받았어요. 내가 할 일을 차례대로 쓰고, 이것이 예절이 아니라 나를 지키는 일인 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u5-C30","difficulty":4,"kind":"essay","stem":"모르는 사람에게서 「사진 보내 주면 선물 줄게.」라는 쪽지를 받았어요. 내가 할 일을 차례대로 쓰고, 이것이 예절이 아니라 나를 지키는 일인 까닭을 쓰세요.","answer_guide":{"answer":"예: 사진을 보내지 않고, 답장도 하지 않고, 부모님이나 선생님께 쪽지를 바로 보여 드린다. 모르는 사람에게 내 정보를 주면 나에게 위험한 일이 생길 수 있어서, 친절하게 답하는 예절보다 나를 지키는 것이 먼저이기 때문이다.","scoring_points":["사진과 정보를 보내지 않는다고 썼는가","어른께 바로 알린다고 썼는가","나를 지키는 일인 까닭을 썼는가"]},"explanation":["보내지 않아요.","어른께 알려요.","나를 지켜요."],"asset":{"type":"speech","turns":[{"who":"모르는 사람","text":"안녕? 나도 4학년이야. 너 어느 학교 다녀?"},{"who":"모르는 사람","text":"사진 한 장 보내 주면 친구 해 줄게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#1','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C6',1,'mc','auto','온라인 대화도 편지도 시작이 같다고 했어요. 둘이 함께 시작하는 곳은 어디인가요?',ARRAY['K4-2-u5-X07','K4-2-u5-X01','K4-2-u5-X13']::text[],false,'{"seq":1,"concept":"K4-2-u5-C6","difficulty":1,"kind":"mc","stem":"온라인 대화도 편지도 시작이 같다고 했어요. 둘이 함께 시작하는 곳은 어디인가요?","options":[{"t":"상대의 상황과 마음을 살피는 일","correct":true},{"t":"가장 빠른 기기를 고르는 일","mis":"K4-2-u5-X07"},{"t":"편지지와 봉투를 사는 일","mis":"K4-2-u5-X01"},{"t":"온라인 대화를 줄이는 일","mis":"K4-2-u5-X13"}],"explanation":["화면 너머에도, 종이 너머에도","사람이 있어요.","상대를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#2','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C9',1,'ox','auto','공책에 오늘 있었던 일을 적는 것도 온라인 대화예요.',ARRAY['K4-2-u5-X09']::text[],false,'{"seq":2,"concept":"K4-2-u5-C9","difficulty":1,"kind":"ox","stem":"공책에 오늘 있었던 일을 적는 것도 온라인 대화예요.","answer":"X","reason_options":[{"t":"상대와 말을 주고받는 일이 아니고 디지털 기기로 하는 일도 아니기 때문에","correct":true},{"t":"글로 쓰는 것은 모두 온라인 대화이기 때문에","mis":"K4-2-u5-X09"}],"mis":"K4-2-u5-X09","explanation":["상대가 있나요?","기기로 하나요?","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#3','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C20',1,'mc','auto','온라인 대화에서 지켜야 할 예절은 무엇인가요?',ARRAY['K4-2-u5-X23','K4-2-u5-X16','K4-2-u5-X22']::text[],false,'{"seq":3,"concept":"K4-2-u5-C20","difficulty":1,"kind":"mc","stem":"온라인 대화에서 지켜야 할 예절은 무엇인가요?","options":[{"t":"상대가 보이지 않아도 존중하며 말한다","correct":true},{"t":"답이 늦으면 답할 때까지 계속 말을 건다","mis":"K4-2-u5-X23"},{"t":"주제와 상관없는 그림말을 되풀이한다","mis":"K4-2-u5-X16"},{"t":"뜻을 몰라도 내가 쓰던 말을 그대로 쓴다","mis":"K4-2-u5-X22"}],"explanation":["화면 너머에도 사람이 있어요.","보이지 않아도요.","존중하며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#4','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C30',1,'mc','auto','모르는 사람의 쪽지 때문에 걱정될 때 할 일은 무엇인가요?',ARRAY['K4-2-u5-X30','K4-2-u5-X29']::text[],false,'{"seq":4,"concept":"K4-2-u5-C30","difficulty":1,"kind":"mc","stem":"모르는 사람의 쪽지 때문에 걱정될 때 할 일은 무엇인가요?","options":[{"t":"부모님이나 선생님께 쪽지를 보여 드린다","correct":true},{"t":"혼자 고민하며 아무에게도 말하지 않는다","mis":"K4-2-u5-X30"},{"t":"답장을 보내 누구인지 직접 알아본다","mis":"K4-2-u5-X29"},{"t":"쪽지만 지우면 끝난 일이라 여긴다","mis":"K4-2-u5-X30"}],"explanation":["혼자 판단하지 않아도 돼요.","어른께 보여 드려요.","함께 해결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#5','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C38',1,'mc','auto','편지를 쓴 까닭과 전하려는 마음을 쓰는 부분은 무엇인가요?',ARRAY['K4-2-u5-X38','K4-2-u5-X39']::text[],false,'{"seq":5,"concept":"K4-2-u5-C38","difficulty":1,"kind":"mc","stem":"편지를 쓴 까닭과 전하려는 마음을 쓰는 부분은 무엇인가요?","options":[{"t":"전하고 싶은 말","correct":true},{"t":"첫인사","mis":"K4-2-u5-X38"},{"t":"쓴 날짜","mis":"K4-2-u5-X38"},{"t":"추신","mis":"K4-2-u5-X39"}],"explanation":["편지의 한가운데예요.","쓴 까닭과 마음이에요.","전하고 싶은 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#6','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C41',1,'ox','auto','친구에게 쓰는 편지에 높임말을 쓰지 않으면 마음이 작은 거예요.',ARRAY['K4-2-u5-X41']::text[],false,'{"seq":6,"concept":"K4-2-u5-C41","difficulty":1,"kind":"ox","stem":"친구에게 쓰는 편지에 높임말을 쓰지 않으면 마음이 작은 거예요.","answer":"X","reason_options":[{"t":"높임은 마음의 크기가 아니라 읽는 사람에 맞추는 것이기 때문에","correct":true},{"t":"높임말을 많이 쓸수록 마음이 커지기 때문에","mis":"K4-2-u5-X41"}],"mis":"K4-2-u5-X41","explanation":["높임은 상대에 맞춰요.","마음의 크기가 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#7','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C46',1,'mc','auto','아끼던 강아지 인형을 잃어버려 속상해하는 동생에게 전할 마음은 무엇인가요?',ARRAY['K4-2-u5-X46']::text[],false,'{"seq":7,"concept":"K4-2-u5-C46","difficulty":1,"kind":"mc","stem":"아끼던 강아지 인형을 잃어버려 속상해하는 동생에게 전할 마음은 무엇인가요?","options":[{"t":"위로","correct":true},{"t":"축하","mis":"K4-2-u5-X46"},{"t":"사과","mis":"K4-2-u5-X46"},{"t":"응원","mis":"K4-2-u5-X46"}],"explanation":["힘든 일을 겪고 있어요.","마음을 달래 줘요.","위로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#8','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C59',1,'mc','auto','「여덟」은 어떻게 소리 나나요?',ARRAY['K4-2-u5-X60','K4-2-u5-X59']::text[],false,'{"seq":8,"concept":"K4-2-u5-C59","difficulty":1,"kind":"mc","stem":"「여덟」은 어떻게 소리 나나요?","options":[{"t":"[여덜]","correct":true},{"t":"[여덥]","mis":"K4-2-u5-X60"},{"t":"[여덟]","mis":"K4-2-u5-X59"},{"t":"[여더]","mis":"K4-2-u5-X60"}],"explanation":["ㄼ은 보통 [ㄹ]이에요.","받침 하나만 소리 나요.","[여덜]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#9','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C12',2,'mc','auto','온라인 대화를 「다른 세상의 일」로 여기면 생기기 쉬운 일은 무엇인가요?',ARRAY['K4-2-u5-X12']::text[],false,'{"seq":9,"concept":"K4-2-u5-C12","difficulty":2,"kind":"mc","stem":"온라인 대화를 「다른 세상의 일」로 여기면 생기기 쉬운 일은 무엇인가요?","options":[{"t":"보이지 않는 상대에게 직접 만나면 하지 않을 말을 하게 된다","correct":true},{"t":"대화가 더 친절해진다","mis":"K4-2-u5-X12"},{"t":"예절을 더 잘 지키게 된다","mis":"K4-2-u5-X12"},{"t":"상대를 더 존중하게 된다","mis":"K4-2-u5-X12"}],"explanation":["같은 사람끼리의 대화예요.","다르다고 여기면요?","함부로 말하게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#10','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C18',2,'ox','auto','온라인 대화에서 문제가 생기는 것은 디지털 기기가 나쁘기 때문이에요.',ARRAY['K4-2-u5-X18']::text[],false,'{"seq":10,"concept":"K4-2-u5-C18","difficulty":2,"kind":"ox","stem":"온라인 대화에서 문제가 생기는 것은 디지털 기기가 나쁘기 때문이에요.","answer":"X","reason_options":[{"t":"얼굴을 마주 보지 않고 이름이 드러나지 않을 때가 있어서 더 조심해야 하는 것이기 때문에","correct":true},{"t":"기기를 쓰면 사람이 나빠지기 때문에","mis":"K4-2-u5-X18"}],"mis":"K4-2-u5-X18","explanation":["기기가 나쁜 것이 아니에요.","보이지 않아서예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#11','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C26',2,'mc','auto','민솔이가 입원해 있을 때 온라인 대화가 힘이 된 까닭은 무엇인가요?',ARRAY['K4-2-u5-X26','K4-2-u5-X03','K4-2-u5-X16']::text[],false,'{"seq":11,"concept":"K4-2-u5-C26","difficulty":2,"kind":"mc","stem":"민솔이가 입원해 있을 때 온라인 대화가 힘이 된 까닭은 무엇인가요?","options":[{"t":"떨어져 있어 만날 수 없는데도 소식을 주고받을 수 있었기 때문에","correct":true},{"t":"온라인 대화는 언제나 만나는 것보다 좋기 때문에","mis":"K4-2-u5-X26"},{"t":"병원에서는 예절을 안 지켜도 되기 때문에","mis":"K4-2-u5-X03"},{"t":"그림말만 주고받아도 되기 때문에","mis":"K4-2-u5-X16"}],"explanation":["민솔이는 학교에 못 갔어요.","떨어져 있었어요.","그래도 소식이 닿았어요."],"asset":{"type":"speech","turns":[{"who":"민솔","text":"입원해 있는 동안 학교에 못 갔는데, 반 친구들이 날마다 대화방에 소식을 남겨 주었어."},{"who":"나윤","text":"혼자 있는 것 같지 않았겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#12','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C33',2,'mc','auto','점검표를 「잘한 것처럼 보이려고」 채우면 생기는 일은 무엇인가요?',ARRAY['K4-2-u5-X31','K4-2-u5-X32']::text[],false,'{"seq":12,"concept":"K4-2-u5-C33","difficulty":2,"kind":"mc","stem":"점검표를 「잘한 것처럼 보이려고」 채우면 생기는 일은 무엇인가요?","options":[{"t":"고쳐야 할 곳을 찾지 못하게 된다","correct":true},{"t":"예절을 더 잘 지키게 된다","mis":"K4-2-u5-X31"},{"t":"대화가 더 좋아진다","mis":"K4-2-u5-X31"},{"t":"다음 대화가 저절로 나아진다","mis":"K4-2-u5-X32"}],"explanation":["모두 「예」로 채우면요?","고칠 곳이 숨어요.","찾지 못하게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#13','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C49',2,'mc','auto','「그때 정말 좋았어.」만 쓴 편지를 받은 사람에게 생기기 쉬운 일은 무엇인가요?',ARRAY['K4-2-u5-X49','K4-2-u5-X40']::text[],false,'{"seq":13,"concept":"K4-2-u5-C49","difficulty":2,"kind":"mc","stem":"「그때 정말 좋았어.」만 쓴 편지를 받은 사람에게 생기기 쉬운 일은 무엇인가요?","options":[{"t":"어느 일을 말하는지 떠올리기 어렵다","correct":true},{"t":"짧아서 마음이 더 잘 전해진다","mis":"K4-2-u5-X49"},{"t":"읽기 편해서 더 기억에 남는다","mis":"K4-2-u5-X49"},{"t":"길지 않으니 높임이 저절로 맞춰진다","mis":"K4-2-u5-X40"}],"explanation":["「그때」는 언제인가요?","읽는 사람은 몰라요.","떠올리기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#14','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C51',2,'mc','auto','친구에게 보내는 봉투에서 받는 사람 이름 뒤에 쓰기 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X41','K4-2-u5-X51']::text[],false,'{"seq":14,"concept":"K4-2-u5-C51","difficulty":2,"kind":"mc","stem":"친구에게 보내는 봉투에서 받는 사람 이름 뒤에 쓰기 알맞은 것은 무엇인가요?","options":[{"t":"앞","correct":true},{"t":"귀하","mis":"K4-2-u5-X41"},{"t":"님께","mis":"K4-2-u5-X41"},{"t":"올림","mis":"K4-2-u5-X51"}],"explanation":["받는 사람이 친구예요.","「에게」나 「앞」","‘앞’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#15','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C55',2,'mc','auto','표어를 알리는 계획에서 「누구에게」에 들어갈 것은 무엇인가요?',ARRAY['K4-2-u5-X27']::text[],false,'{"seq":15,"concept":"K4-2-u5-C55","difficulty":2,"kind":"mc","stem":"표어를 알리는 계획에서 「누구에게」에 들어갈 것은 무엇인가요?","options":[{"t":"우리 학년","correct":true},{"t":"점심시간","mis":"K4-2-u5-X27"},{"t":"복도","mis":"K4-2-u5-X27"},{"t":"알림판에 붙이기","mis":"K4-2-u5-X27"}],"explanation":["언제 · 어디서 · 누구에게 · 어떻게","사람을 찾아요.","우리 학년이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#16','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C60',2,'ox','auto','대화방에서는 짧게 줄여 쓸수록 상대가 더 잘 알아들어요.',ARRAY['K4-2-u5-X61']::text[],false,'{"seq":16,"concept":"K4-2-u5-C60","difficulty":2,"kind":"ox","stem":"대화방에서는 짧게 줄여 쓸수록 상대가 더 잘 알아들어요.","answer":"X","reason_options":[{"t":"뜻을 알기 어렵게 줄이면 상대가 알아듣지 못하거나 서운할 수 있기 때문에","correct":true},{"t":"짧은 말이 언제나 빠르고 정확하기 때문에","mis":"K4-2-u5-X61"}],"mis":"K4-2-u5-X61","explanation":["짧은 것이 아니라요.","알아듣게 쓰는 것이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#17','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C14',3,'ox','auto','이 단원에서 예절을 배운 것은 온라인 대화를 되도록 쓰지 말라는 뜻이에요.',ARRAY['K4-2-u5-X13']::text[],false,'{"seq":17,"concept":"K4-2-u5-C14","difficulty":3,"kind":"ox","stem":"이 단원에서 예절을 배운 것은 온라인 대화를 되도록 쓰지 말라는 뜻이에요.","answer":"X","reason_options":[{"t":"조심할 점을 알고 예절을 지키며 잘 쓰는 법을 배운 것이기 때문에","correct":true},{"t":"예절을 배워야 할 만큼 온라인 대화는 나쁜 것이기 때문에","mis":"K4-2-u5-X13"}],"mis":"K4-2-u5-X13","explanation":["쓰지 말자는 게 아니에요.","잘 쓰는 법이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#18','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C24',3,'mc','auto','토의에서 내 의견과 다른 의견이 나왔을 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X15','K4-2-u5-X25']::text[],false,'{"seq":18,"concept":"K4-2-u5-C24","difficulty":3,"kind":"mc","stem":"토의에서 내 의견과 다른 의견이 나왔을 때 알맞은 것은 무엇인가요?","options":[{"t":"끝까지 존중하며 듣고 두 기준으로 함께 따져 본다","correct":true},{"t":"내 의견이 이길 때까지 말을 멈추지 않는다","mis":"K4-2-u5-X15"},{"t":"말차례를 기다리지 않고 바로 반대한다","mis":"K4-2-u5-X25"},{"t":"토의 주제와 상관없는 이야기로 바꾼다","mis":"K4-2-u5-X25"}],"explanation":["토의는 함께 정하는 일이에요.","존중하며 들어요.","기준으로 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#19','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C49',3,'mc','auto','다리를 다친 짝에게 쓴 「어제 운동장에서 신나게 뛰어놀았어.」가 마음과 다르게 닿을 수 있는 까닭은 무엇인가요?',ARRAY['K4-2-u5-X42','K4-2-u5-X41']::text[],false,'{"seq":19,"concept":"K4-2-u5-C49","difficulty":3,"kind":"mc","stem":"다리를 다친 짝에게 쓴 「어제 운동장에서 신나게 뛰어놀았어.」가 마음과 다르게 닿을 수 있는 까닭은 무엇인가요?","options":[{"t":"짝은 지금 뛰어놀 수 없는 처지이기 때문에","correct":true},{"t":"문장이 너무 짧기 때문에","mis":"K4-2-u5-X42"},{"t":"높임 표현을 쓰지 않았기 때문에","mis":"K4-2-u5-X41"},{"t":"운동장이라는 낱말이 어렵기 때문에","mis":"K4-2-u5-X42"}],"explanation":["짝은 지금 어떤 처지인가요?","그 줄을 읽을 때를 그려요.","처지를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#20','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C42',3,'ox','auto','하준이가 먼저 쓴 쪽지는 짧아서 고쳐 써야 해요.',ARRAY['K4-2-u5-X42']::text[],false,'{"seq":20,"concept":"K4-2-u5-C42","difficulty":3,"kind":"ox","stem":"하준이가 먼저 쓴 쪽지는 짧아서 고쳐 써야 해요.","answer":"X","reason_options":[{"t":"짧은 것이 아니라 높임·있었던 일·인사와 날짜가 빠진 것이 문제이기 때문에","correct":true},{"t":"편지는 길수록 좋은 것이기 때문에","mis":"K4-2-u5-X42"}],"mis":"K4-2-u5-X42","explanation":["길이가 문제가 아니에요.","무엇이 빠졌나요?","그래서 X예요."],"asset":{"type":"passage","lines":["할머니에게","화분 고마워.","그럼 안녕.","하준 씀"],"title":"하준이가 먼저 쓴 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#21','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C5',3,'ox','auto','편지와 온라인 대화방 가운데 언제나 더 나은 쪽이 하나 있어요.',ARRAY['K4-2-u5-X05']::text[],false,'{"seq":21,"concept":"K4-2-u5-C5","difficulty":3,"kind":"ox","stem":"편지와 온라인 대화방 가운데 언제나 더 나은 쪽이 하나 있어요.","answer":"X","reason_options":[{"t":"방법마다 잘하는 일이 달라 상황에 알맞은 것을 고르기 때문에","correct":true},{"t":"빠른 방법이 언제나 더 낫기 때문에","mis":"K4-2-u5-X05"}],"mis":"K4-2-u5-X05","explanation":["잘하는 일이 달라요.","상황이 정해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#22','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C28',3,'mc','auto','다른 학교 친구들과 영상 회의를 하려는 계획에서 「온라인으로 하는 까닭」으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u5-X26','K4-2-u5-X27']::text[],false,'{"seq":22,"concept":"K4-2-u5-C28","difficulty":3,"kind":"mc","stem":"다른 학교 친구들과 영상 회의를 하려는 계획에서 「온라인으로 하는 까닭」으로 알맞은 것은 무엇인가요?","options":[{"t":"두 학교가 멀리 떨어져 있어 직접 만나기 어렵기 때문에","correct":true},{"t":"온라인이 언제나 더 재미있기 때문에","mis":"K4-2-u5-X26"},{"t":"텃밭에서 기른 채소를 소개하려고","mis":"K4-2-u5-X27"},{"t":"다른 학교 4학년 친구들","mis":"K4-2-u5-X27"}],"explanation":["왜 만나서 하지 않나요?","떨어져 있어요.","그것이 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#23','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C14',4,'essay','teacher','온라인 대화의 좋은 점과 조심할 점을 하나씩 쓰고, 둘을 함께 생각했을 때 내가 지킬 다짐 한 가지를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u5-C14","difficulty":4,"kind":"essay","stem":"온라인 대화의 좋은 점과 조심할 점을 하나씩 쓰고, 둘을 함께 생각했을 때 내가 지킬 다짐 한 가지를 쓰세요.","answer_guide":{"answer":"예: 좋은 점은 멀리 있는 친구와도 바로 이야기할 수 있다는 것이고, 조심할 점은 남의 사진을 함부로 올리면 피해가 갈 수 있다는 것이다. 그래서 나는 이번 주에 사진을 올리기 전에 찍힌 사람에게 꼭 먼저 묻겠다.","scoring_points":["좋은 점을 썼는가","조심할 점을 썼는가","둘을 함께 생각한 다짐을 하나만 썼는가"]},"explanation":["좋은 점 하나","조심할 점 하나","다짐은 하나"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#24','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C43',4,'essay','teacher','친구에게 서운했던 마음을 편지로 전하려고 해요. 솔직한 마음과 읽는 이에 대한 배려가 함께 드러나게 두세 문장으로 쓰고, 어디에서 배려했는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u5-C43","difficulty":4,"kind":"essay","stem":"친구에게 서운했던 마음을 편지로 전하려고 해요. 솔직한 마음과 읽는 이에 대한 배려가 함께 드러나게 두세 문장으로 쓰고, 어디에서 배려했는지 쓰세요.","answer_guide":{"answer":"예: 「어제 모둠 활동 때 내 의견을 끝까지 듣지 않아서 조금 서운했어. 너도 시간이 없어서 그랬다는 거 알아. 다음에는 내 말도 끝까지 들어 주면 좋겠어.」 — 친구의 사정을 헤아리는 말을 넣고, 탓하는 말 대신 바라는 점으로 썼다.","scoring_points":["서운한 마음을 솔직하게 썼는가","친구의 처지를 헤아리는 말을 넣었는가","어디에서 배려했는지 썼는가"]},"explanation":["솔직하게 써요.","친구를 헤아려요.","둘 다 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u5_review_d#25','kor',4,2,'u5','','g4_2_kor_u5_review_d','unit_review','K4-2-u5-C31',4,'essay','teacher','모둠 대화방에서 온라인 대화를 할 때 지킬 것 두 가지를 쓰고, 그 가운데 하나를 지키지 않았을 때 상대에게 생기는 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u5-C31","difficulty":4,"kind":"essay","stem":"모둠 대화방에서 온라인 대화를 할 때 지킬 것 두 가지를 쓰고, 그 가운데 하나를 지키지 않았을 때 상대에게 생기는 일을 쓰세요.","answer_guide":{"answer":"예: 정한 주제에 맞는 말을 하고, 먼저 나갈 때는 양해를 구한다. 말없이 나가 버리면 남은 친구들은 내가 화가 났는지, 대답을 기다려야 하는지 몰라 서운하고 대화가 멈춘다.","scoring_points":["지킬 것 두 가지를 썼는가","그 가운데 하나를 골랐는가","상대에게 생기는 일을 썼는가"]},"explanation":["주제 · 답하기 · 양해 · 풀어 쓰기","하나를 골라요.","상대에게 무슨 일이?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
